## Asymptotic and amortized analysis, made measurable by counting operations instead of time.
##
## Use it to check an analysis claim against a count: how many comparisons does a search make, how
## many element copies does a growing array pay, how many bit flips does a counter pay. A count
## is exact and repeatable, a stopwatch is neither. Big-O statements are about all large inputs,
## so the witness checks here (`isBigOOn`, `isBigOmegaOn`) test a stated constant over a finite
## range: they refute a wrong claim and support a right one, but do not prove it.

import std/options

type
  Growth* = enum
    gDoubling   ## a full array gets twice the capacity (capacity 0 becomes 1)
    gByOne      ## a full array gets one more slot

  AppendStep* = object
    ## One append to a growing array, after it happened.
    cost*: int        ## 1 for the write plus the elements copied by a resize
    size*: int        ## elements held
    capacity*: int    ## slots allocated

  Measure = proc(n: int): int {.noSideEffect, raises: [].}

func ceilLog2*(n: int): Option[int] {.raises: [].} =
  ## The smallest k with 2^k >= n, for n >= 1; none otherwise.
  if n < 1:
    return none(int)
  var k = 0
  var reach = 1
  while reach < n:
    reach *= 2
    inc k
  some(k)

func linearSearchSteps*(xs: openArray[int]; x: int): int {.raises: [].} =
  ## Elements looked at while scanning from the left for `x`: its position plus one when
  ## present, the length otherwise. Worst case n, so the cost is Theta(n) in the worst case.
  for i, v in xs:
    if v == x:
      return i + 1
  xs.len

func binarySearchSteps*(sortedXs: openArray[int]; x: int): int {.raises: [].} =
  ## Probes made by binary search on an ascending sequence (one probe = one three-way comparison
  ## with the middle element). At most floor(log2 n) + 1 for n >= 1 (ANALYSIS-ASYMP-02).
  var lo = 0
  var hi = sortedXs.len - 1
  while lo <= hi:
    inc result
    let mid = lo + (hi - lo) div 2
    if sortedXs[mid] == x:
      return
    if sortedXs[mid] < x: lo = mid + 1 else: hi = mid - 1

func naiveDuplicateComparisons*(xs: openArray[int]): tuple[found: bool, comparisons: int] {.raises: [].} =
  ## Compares every pair (i < j) until two are equal. With no duplicate it makes exactly
  ## n * (n - 1) / 2 comparisons: a nested loop is Theta(n^2) (ANALYSIS-ASYMP-01).
  for i in 0 ..< xs.len:
    for j in i + 1 ..< xs.len:
      inc result.comparisons
      if xs[i] == xs[j]:
        result.found = true
        return

func isBigOOn*(f, g: Measure; c, n0, upTo: int): bool {.raises: [].} =
  ## Does f(n) <= c * g(n) hold for every n in n0 .. upTo? A finite check of the claim
  ## "f is O(g) with constant c from n0 on" (ANALYSIS-ASYMP-03): `false` refutes the claim for
  ## these constants, `true` supports it up to `upTo` only.
  for n in n0 .. upTo:
    if f(n) > c * g(n):
      return false
  true

func isBigOmegaOn*(f, g: Measure; c, n0, upTo: int): bool {.raises: [].} =
  ## Does f(n) >= c * g(n) hold for every n in n0 .. upTo? (the lower-bound twin of `isBigOOn`.)
  for n in n0 .. upTo:
    if f(n) < c * g(n):
      return false
  true

func appendSteps*(n: int; growth: Growth): seq[AppendStep] {.raises: [].} =
  ## The cost of each of `n` appends to an empty growing array (none for n <= 0). Without a
  ## resize an append costs 1; a resize also copies every element already held, so it costs 1 + size.
  var size = 0
  var capacity = 0
  for _ in 1 .. n:
    var cost = 1
    if size == capacity:
      cost += size
      capacity = if growth == gDoubling: max(1, 2 * capacity) else: capacity + 1
    inc size
    result.add AppendStep(cost: cost, size: size, capacity: capacity)

func totalCost*(steps: openArray[AppendStep]): int {.raises: [].} =
  ## The aggregate method: add the real costs. Doubling: at most 3n for n appends
  ## (ANALYSIS-AMORT-01); growing by one: n + n(n - 1) / 2 (ANALYSIS-AMORT-02).
  for s in steps:
    result += s.cost

func potential*(size, capacity: int): int {.raises: [].} =
  ## Phi = 2 * size - capacity: the unspent "credit" of a doubling array. It is zero when empty,
  ## never negative while the array is more than half full, and is spent exactly when a resize copies.
  2 * size - capacity

func doublingAmortizedCosts*(n: int): seq[int] {.raises: [].} =
  ## The potential method for doubling: amortized cost of append i is its real cost plus
  ## Phi after minus Phi before. Each is at most 3 (ANALYSIS-AMORT-03), whatever the resizes.
  var before = 0
  for s in appendSteps(n, gDoubling):
    let after = potential(s.size, s.capacity)
    result.add s.cost + after - before
    before = after

func incrementBits*(bits: seq[bool]): tuple[bits: seq[bool], flips: int] {.raises: [].} =
  ## Adds one to a binary counter (least significant bit first; the counter grows by a bit on
  ## overflow) and counts the bits that changed. The old counter stays valid.
  var next = bits
  var i = 0
  while i < next.len and next[i]:
    next[i] = false
    inc result.flips
    inc i
  if i == next.len:
    next.add true
  else:
    next[i] = true
  inc result.flips
  result.bits = next

func counterFlips*(n: int): int {.raises: [].} =
  ## Total bit flips of `n` increments from zero. It is exactly 2n - popcount(n), so below 2n:
  ## an increment is amortized O(1) although a single one can flip every bit (ANALYSIS-AMORT-04).
  var bits: seq[bool]
  for _ in 1 .. n:
    let step = incrementBits(bits)
    bits = step.bits
    result += step.flips

## Approximation algorithm: a vertex cover at most twice the optimum, from a maximal matching.
##
## A vertex cover is a set of vertices that touches every edge; finding a smallest one is NP-hard.
## The 2-approximation scans the edges in order and, whenever an edge has both ends still
## uncovered, takes that edge into a matching and puts both ends into the cover. The matched edges
## share no vertex, and any cover must contain at least one end of each of them, so the optimum is
## at least the matching size m while the answer has at most 2m vertices: a guaranteed ratio of 2,
## whatever the graph. The ratio is tight (a path on four vertices, scanned left to right, picks
## all four where two suffice). Use it when an exact cover is too expensive and a bounded error
## is acceptable; reach for an exact search only for small graphs.
##
## The graph must be undirected. Edges are scanned in `edges(g)` order (ascending source, target)
## so the answer is deterministic. A self-loop `v - v` is covered only by `v` itself, so it joins
## the matching with the single vertex `v`.

import nimcs/fp/result
import nimcs/algo/graph

type CoverResult* = object
  ## The matching that was built and the cover derived from it.
  matching*: seq[Edge]    ## pairwise vertex-disjoint edges, in scan order
  cover*: seq[int]        ## ascending vertices of the cover

func maximalMatchingCover*(g: Graph): Result[CoverResult, GraphError] {.raises: [].} =
  ## A maximal set of vertex-disjoint edges (no further edge can be added) and the vertices they
  ## touch. Fails with `geNotUndirected` for a directed graph (APPROX-VC-06). Every edge of the
  ## graph has an end in `cover` (APPROX-VC-01) and `cover.len <= 2 * matching.len`
  ## (APPROX-VC-02).
  if g.isDirected:
    return err(CoverResult, geNotUndirected)
  var covered = newSeq[bool](g.vertexCount)
  var matching: seq[Edge]
  for e in g.edges:
    if not covered[e.source] and not covered[e.target]:
      covered[e.source] = true
      covered[e.target] = true
      matching.add e
  var cover: seq[int]
  for v in 0 ..< g.vertexCount:
    if covered[v]: cover.add v
  ok(CoverResult(matching: matching, cover: cover), GraphError)

func vertexCover2Approx*(g: Graph): Result[seq[int], GraphError] {.raises: [].} =
  ## The cover of `maximalMatchingCover`, ascending: at most twice the size of a smallest cover
  ## (APPROX-VC-03).
  let r = maximalMatchingCover(g)
  if r.isErr:
    return err(seq[int], r.error)
  ok(r.value.cover, GraphError)

func isVertexCover*(g: Graph; cover: openArray[int]): bool {.raises: [].} =
  ## Does every edge of `g` have an end in `cover`? Vertices outside the graph never help.
  var chosen = newSeq[bool](g.vertexCount)
  for v in cover:
    if g.inRange(v):
      chosen[v] = true
  for e in g.edges:
    if not chosen[e.source] and not chosen[e.target]:
      return false
  true

## Backtracking as a pure generator: a search tree is described by two functions, `children`
## (the ways to extend a partial state) and `isSolution`, and `backtrack` returns every solution in
## depth-first, left-to-right order. Nothing is mutated by the caller; the only `var` is the list being
## collected inside the walk.
##
## Use it for constraint problems with a small search tree: permutations, combinations, n-queens,
## sudoku-like puzzles. Pruning lives in `children`: return only extensions that can still
## lead to a solution. When the number of solutions is huge or only one is needed, use
## `firstSolution`; when sub-problems repeat, switch to dynamic programming (`memoization`).
##
## The domain helpers refuse sizes whose answer would not be a sensible list (negative, or large
## enough to take minutes); the limits are exported constants.

import std/options

type
  Children*[S] = proc(s: S): seq[S] {.noSideEffect, raises: [].}
  Accept*[S] = proc(s: S): bool {.noSideEffect, raises: [].}

const
  maxPermutationSize*: int = 9
  maxCombinationSize*: int = 20
  maxQueensSize*: int = 10

func walk[S](s: S; children: Children[S]; accept: Accept[S]; found: var seq[S]) {.raises: [].} =
  if accept(s):
    found.add s
  for c in children(s):
    walk(c, children, accept, found)

func backtrack*[S](start: S; children: Children[S]; accept: Accept[S]): seq[S] {.raises: [].} =
  ## Every state reachable from `start` for which `accept` holds, in pre-order (TECH-BT-GEN-01,
  ## TECH-BT-GEN-02). The same arguments always give the same list.
  result = @[]
  walk(start, children, accept, result)

func firstWalk[S](s: S; children: Children[S]; accept: Accept[S]): Option[S] {.raises: [].} =
  if accept(s):
    return some(s)
  for c in children(s):
    let r = firstWalk(c, children, accept)
    if r.isSome:
      return r
  none(S)

func firstSolution*[S](start: S; children: Children[S]; accept: Accept[S]): Option[S] {.raises: [].} =
  ## The first element `backtrack` would return, without visiting the rest of the tree (TECH-BT-GEN-03).
  firstWalk(start, children, accept)

func permutations*(n: int): Option[seq[seq[int]]] {.raises: [].} =
  ## All orderings of 0 ..< n in lexicographic order; one empty ordering when n is 0. None when
  ## n < 0 or n > `maxPermutationSize` (TECH-BT-PERM-01 .. TECH-BT-PERM-03).
  if n < 0 or n > maxPermutationSize:
    return none(seq[seq[int]])
  func kids(s: seq[int]): seq[seq[int]] {.raises: [].} =
    result = @[]
    if s.len < n:
      for v in 0 ..< n:
        if v notin s:
          result.add s & @[v]
  func done(s: seq[int]): bool {.raises: [].} = s.len == n
  some(backtrack(newSeq[int](), kids, done))

func combinations*(n, k: int): Option[seq[seq[int]]] {.raises: [].} =
  ## All k-element subsets of 0 ..< n, each ascending, in lexicographic order. Empty when k > n.
  ## None when n or k is negative or n > `maxCombinationSize` (TECH-BT-COMB-01, TECH-BT-COMB-02).
  if n < 0 or k < 0 or n > maxCombinationSize:
    return none(seq[seq[int]])
  func kids(s: seq[int]): seq[seq[int]] {.raises: [].} =
    result = @[]
    if s.len < k:
      let first = if s.len == 0: 0 else: s[s.len - 1] + 1
      for v in first ..< n:
        if n - v >= k - s.len:      # enough values left to reach size k
          result.add s & @[v]
  func done(s: seq[int]): bool {.raises: [].} = s.len == k
  some(backtrack(newSeq[int](), kids, done))

func safeToPlace(cols: seq[int]; col: int): bool {.raises: [].} =
  let row = cols.len
  for r in 0 ..< row:
    if cols[r] == col or abs(cols[r] - col) == row - r:
      return false
  true

func nQueens*(n: int): Option[seq[seq[int]]] {.raises: [].} =
  ## All placements of n non-attacking queens on an n x n board, as the column of the queen in each
  ## row, in lexicographic order. n = 0 has one (empty) placement. None when n < 0 or n >
  ## `maxQueensSize` (TECH-BT-QUEENS-01, TECH-BT-QUEENS-02).
  if n < 0 or n > maxQueensSize:
    return none(seq[seq[int]])
  func kids(s: seq[int]): seq[seq[int]] {.raises: [].} =
    result = @[]
    if s.len < n:
      for c in 0 ..< n:
        if safeToPlace(s, c):
          result.add s & @[c]
  func done(s: seq[int]): bool {.raises: [].} = s.len == n
  some(backtrack(newSeq[int](), kids, done))

## Bellman-Ford: relax every arc, V - 1 times; a further improvement proves a negative cycle.
##
## Use it for shortest paths when weights may be negative, or to detect a negative cycle (an
## arbitrage loop, an impossible constraint set). It costs O(V * E), slower than `dijkstra`, which
## is the better choice when no weight is negative. A negative cycle reachable from the source
## makes "shortest" meaningless, so the error value carries such a cycle instead of a bogus tree.
## An undirected edge of negative weight is a negative cycle of two arcs. Distances are `int`.

import std/[algorithm, options]
import nimcs/fp/result
import nimcs/algo/graph

type
  BellmanFordFailure* = enum
    bfBadSource       ## the source is not a vertex
    bfNegativeCycle   ## a negative cycle is reachable from the source

  BellmanFordError* = object
    case kind*: BellmanFordFailure
    of bfBadSource: discard
    of bfNegativeCycle:
      cycle*: seq[int]    ## v0 -> v1 -> ... -> vk -> v0, listed once around, starting at its smallest vertex

func cycleThrough(parent: seq[int]; changed: int): seq[int] {.raises: [].} =
  ## `changed` improved on the last pass, so following predecessors from it enters a cycle
  ## within n steps; then the cycle is read off.
  var inside = changed
  for _ in 0 ..< parent.len:
    inside = parent[inside]
  var backwards = @[inside]
  var current = parent[inside]
  while current != inside:
    backwards.add current
    current = parent[current]
  backwards.reverse
  var at = 0
  for i, v in backwards:
    if v < backwards[at]: at = i
  # Start at the smallest vertex, so the report does not depend on where the walk landed.
  backwards[at .. ^1] & backwards[0 ..< at]

func bellmanFord*(g: Graph; source: int): Result[PathTree, BellmanFordError] {.raises: [].} =
  ## Shortest distances from `source` (GRAPH-BELLMAN-01), or a negative cycle reachable from it
  ## (GRAPH-BELLMAN-02).
  if not g.inRange(source):
    return err(PathTree, BellmanFordError(kind: bfBadSource))
  let n = g.vertexCount
  var dist = newSeq[int](n)
  var reached = newSeq[bool](n)
  var parent = newSeq[int](n)
  for v in 0 ..< n:
    parent[v] = -1
  reached[source] = true
  for pass in 1 .. n:
    var changed = -1
    for u in 0 ..< n:
      if not reached[u]: continue
      for a in g.neighbors(u):
        let candidate = dist[u] + a.weight
        if not reached[a.target] or candidate < dist[a.target]:
          reached[a.target] = true
          dist[a.target] = candidate
          parent[a.target] = u
          changed = a.target
    if changed < 0:
      break
    if pass == n:
      return err(PathTree, BellmanFordError(kind: bfNegativeCycle, cycle: cycleThrough(parent, changed)))
  var distances = newSeq[Option[int]](n)
  var parents = newSeq[Option[int]](n)
  for v in 0 ..< n:
    if reached[v]:
      distances[v] = some(dist[v])
    if parent[v] >= 0 and v != source:
      parents[v] = some(parent[v])
  ok(PathTree(source: source, dist: distances, parent: parents), BellmanFordError)

## Counting sort over a stated key range lo .. hi, negative keys included.
##
## Use it to sort integers, or records by an integer key, when the range of keys is small next to
## the number of items (grades, ages, byte values, days of a year): it counts how many items have
## each key, turns the counts into start positions by a running sum, and places each item at its
## key's next free position, in O(n + range) with no comparisons. Placing items in input order
## makes it stable, which is what lets `radix_sort` run one counting pass per digit. The range is
## stated by the caller (or found by `countingSortAuto`) and capped, because it decides how much
## memory is allocated. For keys that start at zero, `radix_sort.nim` offers the same routine
## with a bound instead of a range. Inputs are never changed.

import std/options
import nimcs/fp/result

const maxCountingSpan* = 1 shl 24
  ## The most distinct key values (hi - lo + 1) that a counting sort here will allocate counters for.

type
  CountingError* = enum
    ceBadRange        ## lo is above hi
    ceRangeTooLarge   ## the range holds more than `maxCountingSpan` values
    ceOutOfRange      ## a key outside lo .. hi

func spanTooLarge(lo, hi: int): bool =
  ## hi - lo + 1 > maxCountingSpan without overflowing, for lo <= hi.
  if lo < 0 and hi >= 0:
    hi >= maxCountingSpan + lo     # hi - lo >= maxCountingSpan, rearranged so nothing overflows
  else:
    hi - lo >= maxCountingSpan     # both on one side of zero: the difference fits

func checkRange(lo, hi: int): Option[CountingError] =
  if lo > hi: some(ceBadRange)
  elif spanTooLarge(lo, hi): some(ceRangeTooLarge)
  else: none(CountingError)

func keyHistogram*(keys: openArray[int]; lo, hi: int): Result[seq[int], CountingError] {.raises: [].} =
  ## How many of `keys` equal each value of lo .. hi: entry i counts the keys equal to lo + i
  ## (SORT-COUNTING-05). The first step of the sort, useful on its own for frequency tables.
  let bad = checkRange(lo, hi)
  if bad.isSome:
    return err(seq[int], bad.get)
  var counts = newSeq[int](hi - lo + 1)
  for k in keys:
    if k < lo or k > hi:
      return err(seq[int], ceOutOfRange)
    inc counts[k - lo]
  ok(counts, CountingError)

func countingSortByRange*[T](xs: openArray[T]; lo, hi: int;
    key: proc(x: T): int {.noSideEffect, raises: [].}): Result[seq[T], CountingError] {.raises: [].} =
  ## Sorts by `key(x)`, which must lie in lo .. hi, keeping the input order of items with equal
  ## keys (SORT-COUNTING-02). Fails on a bad or oversized range and on a key outside it
  ## (SORT-COUNTING-03, SORT-COUNTING-04).
  let bad = checkRange(lo, hi)
  if bad.isSome:
    return err(seq[T], bad.get)
  var next = newSeq[int](hi - lo + 2)        # next[k - lo + 1] counts key k, then becomes its start
  for x in xs:
    let k = key(x)
    if k < lo or k > hi:
      return err(seq[T], ceOutOfRange)
    inc next[k - lo + 1]
  for i in 1 ..< next.len:
    next[i] += next[i - 1]                   # next[i] = number of items with a smaller key than lo + i
  var placed = newSeq[T](xs.len)
  for x in xs:
    let slot = key(x) - lo
    placed[next[slot]] = x
    inc next[slot]
  ok(placed, CountingError)

func countingSortRange*(xs: openArray[int]; lo, hi: int): Result[seq[int], CountingError] {.raises: [].} =
  ## Sorts integers that lie in lo .. hi (SORT-COUNTING-01); idempotent (SORT-COUNTING-07).
  countingSortByRange(xs, lo, hi, proc(x: int): int {.noSideEffect, raises: [].} = x)

func countingSortAuto*(xs: openArray[int]): Result[seq[int], CountingError] {.raises: [].} =
  ## Sorts any integers whose smallest and largest values are less than `maxCountingSpan` apart,
  ## finding the range itself (SORT-COUNTING-06). The empty input gives an empty result.
  if xs.len == 0:
    return ok(newSeq[int](), CountingError)
  var lo = xs[0]
  var hi = xs[0]
  for x in xs:
    lo = min(lo, x)
    hi = max(hi, x)
  countingSortRange(xs, lo, hi)

## Depth-first search, iterative: follow one branch as far as it goes, then back up.
##
## Use it for reachability, cycle detection, topological order (reverse postorder) and as the first
## pass of strongly connected components. It runs in O(V + E). The explicit stack means a path of
## a million vertices does not overflow the call stack. Neighbours are visited in the graph's
## order, so both orders are deterministic.

import nimcs/fp/result
import nimcs/algo/graph

type DfsOrder* = object
  ## Vertices in the order they were entered (preorder) and left (postorder).
  preorder*: seq[int]
  postorder*: seq[int]

func explore(g: Graph; start: int; visited: var seq[bool]; order: var DfsOrder) {.raises: [].} =
  ## Visits everything reachable from `start` that is not yet visited.
  var stack: seq[(int, int)]    # (vertex, index of its next neighbour to try)
  visited[start] = true
  order.preorder.add start
  stack.add (start, 0)
  while stack.len > 0:
    let (u, next) = stack[^1]
    let arcs = g.neighbors(u)
    if next < arcs.len:
      stack[^1] = (u, next + 1)
      let v = arcs[next].target
      if not visited[v]:
        visited[v] = true
        order.preorder.add v
        stack.add (v, 0)
    else:
      order.postorder.add u
      discard stack.pop

func dfs*(g: Graph; start: int): Result[DfsOrder, GraphError] {.raises: [].} =
  ## The vertices reachable from `start`, in preorder and postorder (GRAPH-DFS-01). Fails when
  ## `start` is not a vertex.
  if not g.inRange(start):
    return err(DfsOrder, geVertexOutOfRange)
  var visited = newSeq[bool](g.vertexCount)
  var order = DfsOrder()
  explore(g, start, visited, order)
  ok(order, GraphError)

func dfsForest*(g: Graph): DfsOrder {.raises: [].} =
  ## A search from vertex 0, then from the smallest vertex not yet visited, and so on, so every
  ## vertex appears exactly once in each order (GRAPH-DFS-02).
  var visited = newSeq[bool](g.vertexCount)
  for v in 0 ..< g.vertexCount:
    if not visited[v]:
      explore(g, v, visited, result)

## Dijkstra's algorithm: settle vertices in order of distance, always from the closest unsettled one.
##
## Use it for shortest paths on graphs whose weights are all non-negative (travel time, cost).
## A binary heap with lazy deletion gives O((V + E) log V). With a negative weight the greedy
## argument fails, so this refuses the graph; use `bellman_ford` instead. Distances are `int`
## sums of weights: the caller keeps them small enough not to overflow (an overflow is a Defect).

import std/[heapqueue, options]
import nimcs/fp/result
import nimcs/algo/graph

func dijkstra*(g: Graph; source: int): Result[PathTree, GraphError] {.raises: [].} =
  ## Shortest distances and predecessors from `source` (GRAPH-DIJKSTRA-01). Fails with
  ## `geVertexOutOfRange` for a bad source and `geNegativeWeight` when any arc is negative
  ## (GRAPH-DIJKSTRA-02). Unreachable vertices have distance none.
  if not g.inRange(source):
    return err(PathTree, geVertexOutOfRange)
  let n = g.vertexCount
  for u in 0 ..< n:
    for a in g.neighbors(u):
      if a.weight < 0:
        return err(PathTree, geNegativeWeight)
  var dist = newSeq[Option[int]](n)
  var parent = newSeq[Option[int]](n)
  var settled = newSeq[bool](n)
  var frontier = initHeapQueue[(int, int)]()    # (distance, vertex): ties go to the smaller vertex
  dist[source] = some(0)
  frontier.push (0, source)
  while frontier.len > 0:
    let (d, u) = frontier.pop
    if settled[u]: continue
    settled[u] = true
    for a in g.neighbors(u):
      let candidate = d + a.weight
      if dist[a.target].isNone or candidate < dist[a.target].get:
        dist[a.target] = some(candidate)
        parent[a.target] = some(u)
        frontier.push (candidate, a.target)
  ok(PathTree(source: source, dist: dist, parent: parent), GraphError)

## Divide and conquer: split the input, solve the halves, combine. Shown on the maximum-sum
## contiguous subarray, with Kadane's linear scan as the cross-check, and on the master theorem
## that says what a recurrence T(n) = a T(n/b) + Theta(n^d) costs.
##
## `maxSubarrayDc` solves the left half, the right half and the best subarray crossing the middle,
## and keeps the largest: T(n) = 2 T(n/2) + Theta(n) = Theta(n log n). `maxSubarrayKadane`
## does the same in Theta(n) by carrying the best sum ending at the current element. Prefer Kadane
## in practice; the divide-and-conquer form is the one that generalises (e.g. to a segment tree).
## Sums are assumed not to overflow `int`; that is the caller's precondition.

import std/options

type
  Subarray* = object
    ## The slice `xs[first .. last]` (both inclusive) with total `sum`.
    sum*, first*, last*: int

  MasterCase* = enum
    mcRoot      ## a < b^d: the work at the root dominates, T(n) = Theta(n^d)
    mcBalanced  ## a = b^d: every level costs the same, T(n) = Theta(n^d log n)
    mcLeaves    ## a > b^d: the leaves dominate, T(n) = Theta(n^(log_b a))

func maxSubarrayKadane*(xs: openArray[int]): Option[Subarray] {.raises: [].} =
  ## Best non-empty contiguous slice by one scan; none for empty input (TECH-DC-MAXSUB-01,
  ## TECH-DC-MAXSUB-04). On ties it keeps the first slice that reaches the maximum.
  if xs.len == 0:
    return none(Subarray)
  var best = Subarray(sum: xs[0], first: 0, last: 0)
  var cur = best
  for i in 1 ..< xs.len:
    if cur.sum < 0:
      cur = Subarray(sum: xs[i], first: i, last: i)
    else:
      cur = Subarray(sum: cur.sum + xs[i], first: cur.first, last: i)
    if cur.sum > best.sum:
      best = cur
  some(best)

func dcStep(xs: openArray[int]; lo, hi: int): Subarray {.raises: [].} =
  if lo == hi:
    return Subarray(sum: xs[lo], first: lo, last: lo)
  let mid = (lo + hi) div 2
  let left = dcStep(xs, lo, mid)
  let right = dcStep(xs, mid + 1, hi)
  var sum = 0
  var bestLeft = low(int)
  var from0 = mid
  for i in countdown(mid, lo):
    sum += xs[i]
    if sum > bestLeft:
      bestLeft = sum
      from0 = i
  sum = 0
  var bestRight = low(int)
  var to0 = mid + 1
  for i in mid + 1 .. hi:
    sum += xs[i]
    if sum > bestRight:
      bestRight = sum
      to0 = i
  result = left
  let across = Subarray(sum: bestLeft + bestRight, first: from0, last: to0)
  if across.sum > result.sum:
    result = across
  if right.sum > result.sum:
    result = right

func maxSubarrayDc*(xs: openArray[int]): Option[Subarray] {.raises: [].} =
  ## The same maximum by divide and conquer; none for empty input (TECH-DC-MAXSUB-02, TECH-DC-MAXSUB-04).
  ## The sum equals Kadane's; the slice may differ when several slices share the maximum.
  if xs.len == 0: none(Subarray)
  else: some(dcStep(xs, 0, xs.high))

func masterCase*(a, b, d: int): Option[MasterCase] {.raises: [].} =
  ## Which case of the master theorem applies to T(n) = a T(n/b) + Theta(n^d). None unless a >= 1,
  ## b >= 2 and d >= 0 (TECH-DC-MASTER-03). Compares a with b^d without ever forming an overflowing
  ## power (TECH-DC-MASTER-01, TECH-DC-MASTER-02).
  if a < 1 or b < 2 or d < 0:
    return none(MasterCase)
  var p = 1
  for _ in 1 .. d:
    if p > a div b:       # p * b > a: b^d exceeds a however large d is
      return some(mcRoot)
    p *= b
  if a < p: some(mcRoot)
  elif a == p: some(mcBalanced)
  else: some(mcLeaves)

## Edit (Levenshtein) distance: the least number of single-character insertions, deletions and
## substitutions that turn one string into another, together with a script that does it.
##
## Use it for fuzzy matching, spelling suggestions and diffs at character level. The script is
## a list of `EditOp` values, and `applyScript` replays it, which makes the result checkable.
## For a diff that never substitutes, use `lcs` (insert/delete distance = len a + len b - 2 lcs).

import std/options

type
  EditKind* = enum
    ekKeep, ekReplace, ekInsert, ekDelete

  EditOp* = object
    case kind*: EditKind
    of ekKeep, ekInsert, ekDelete:
      ch*: char
    of ekReplace:
      before*, after*: char

func keep*(c: char): EditOp {.raises: [].} = EditOp(kind: ekKeep, ch: c)
func insert*(c: char): EditOp {.raises: [].} = EditOp(kind: ekInsert, ch: c)
func delete*(c: char): EditOp {.raises: [].} = EditOp(kind: ekDelete, ch: c)
func replace*(before, after: char): EditOp {.raises: [].} =
  EditOp(kind: ekReplace, before: before, after: after)

func `==`*(x, y: EditOp): bool {.raises: [].} =
  if x.kind != y.kind: return false
  case x.kind
  of ekKeep, ekInsert, ekDelete: x.ch == y.ch
  of ekReplace: x.before == y.before and x.after == y.after

func cost*(op: EditOp): int {.raises: [].} =
  ## Keeping is free; every other operation costs one.
  case op.kind
  of ekKeep: 0
  of ekReplace, ekInsert, ekDelete: 1

func cost*(script: openArray[EditOp]): int {.raises: [].} =
  for op in script:
    result += op.cost

func editDistance*(a, b: string): int {.raises: [].} =
  ## Levenshtein distance (DP-EDIT-01 .. DP-EDIT-04).
  var prev = newSeq[int](b.len + 1)
  var cur = newSeq[int](b.len + 1)
  for j in 0 .. b.len:
    prev[j] = j
  for i in 1 .. a.len:
    cur[0] = i
    for j in 1 .. b.len:
      let sub = prev[j - 1] + (if a[i - 1] == b[j - 1]: 0 else: 1)
      cur[j] = min(sub, min(prev[j] + 1, cur[j - 1] + 1))
    swap(prev, cur)
  prev[b.len]

func editScript*(a, b: string): seq[EditOp] {.raises: [].} =
  ## A cheapest script from `a` to `b`. On ties the backtrack prefers keep/replace, then delete,
  ## then insert, so the result is deterministic (DP-EDIT-05).
  let w = b.len + 1
  var table = newSeq[int]((a.len + 1) * w)
  for j in 0 .. b.len:
    table[j] = j
  for i in 1 .. a.len:
    table[i * w] = i
    for j in 1 .. b.len:
      let sub = table[(i - 1) * w + j - 1] + (if a[i - 1] == b[j - 1]: 0 else: 1)
      table[i * w + j] = min(sub, min(table[(i - 1) * w + j] + 1, table[i * w + j - 1] + 1))
  var i = a.len
  var j = b.len
  var rev: seq[EditOp] = @[]
  while i > 0 or j > 0:
    if i > 0 and j > 0 and
        table[i * w + j] == table[(i - 1) * w + j - 1] + (if a[i - 1] == b[j - 1]: 0 else: 1):
      rev.add(if a[i - 1] == b[j - 1]: keep(a[i - 1]) else: replace(a[i - 1], b[j - 1]))
      dec i
      dec j
    elif i > 0 and table[i * w + j] == table[(i - 1) * w + j] + 1:
      rev.add delete(a[i - 1])
      dec i
    else:
      rev.add insert(b[j - 1])
      dec j
  result = newSeq[EditOp](rev.len)
  for k in 0 ..< rev.len:
    result[k] = rev[rev.len - 1 - k]

func applyScript*(a: string; script: openArray[EditOp]): Option[string] {.raises: [].} =
  ## Replays `script` on `a`. None when the script does not fit `a`: it names a character `a`
  ## does not have at that place, or leaves part of `a` unread (DP-EDIT-06).
  var at = 0
  var outStr = ""
  for op in script:
    case op.kind
    of ekKeep:
      if at >= a.len or a[at] != op.ch: return none(string)
      outStr.add op.ch
      inc at
    of ekReplace:
      if at >= a.len or a[at] != op.before: return none(string)
      outStr.add op.after
      inc at
    of ekDelete:
      if at >= a.len or a[at] != op.ch: return none(string)
      inc at
    of ekInsert:
      outStr.add op.ch
  if at != a.len: none(string) else: some(outStr)

## Selection sort and shellsort: two elementary sorts, and when `insertion_sort` is the better pick.
##
## Selection sort repeatedly picks the smallest remaining element and swaps it into place: always
## about n^2/2 comparisons, but at most n - 1 swaps, so it suits the rare case where writing an
## element is far costlier than comparing. It is NOT stable. Shellsort runs insertion sort over
## elements a gap apart, with shrinking gaps ending at 1, so far-apart elements travel quickly;
## it needs no extra memory and beats insertion sort on mid-sized unsorted input, but it is NOT
## stable either. For short or nearly sorted input, or whenever equal elements must keep their
## order, use `insertion_sort` (stable) or `merge_sort`. Inputs are never changed.

import nimcs/fp/result

type
  Less[T] = proc(a, b: T): bool {.noSideEffect, raises: [].}

  GapError* = enum
    gapNone          ## no gap at all
    gapNotPositive   ## a gap below one
    gapNotDescending ## a gap not smaller than the one before it
    gapNoFinalOne    ## the last gap is not 1, so the final pass would not finish the sort

func selectionPass[T](xs: openArray[T]; less: Less[T]): tuple[sorted: seq[T], swaps: int] =
  ## The whole sort, also counting swaps. Among equal minima the leftmost is picked.
  var a = @xs
  for i in 0 ..< max(0, a.len - 1):
    var smallest = i
    for j in i + 1 ..< a.len:
      if less(a[j], a[smallest]):
        smallest = j
    if smallest != i:
      swap(a[i], a[smallest])
      inc result.swaps
  result.sorted = a

func selectionSort*[T](xs: openArray[T]; less: Less[T]): seq[T] {.raises: [].} =
  ## Ascending by `less`. Not stable: the long-distance swap can carry an element past an equal one
  ## (ELEMSORT-SELECT-04).
  selectionPass(xs, less).sorted

func selectionSort*[T](xs: openArray[T]): seq[T] {.raises: [].} =
  ## Ascending by `<`.
  selectionSort(xs, proc(a, b: T): bool {.noSideEffect, raises: [].} = a < b)

func selectionSwaps*[T](xs: openArray[T]; less: Less[T]): int {.raises: [].} =
  ## How many swaps selection sort makes on `xs`: at most len - 1 (ELEMSORT-SELECT-03).
  selectionPass(xs, less).swaps

func shellGaps*(n: int): seq[int] {.raises: [].} =
  ## Knuth's gap sequence 1, 4, 13, 40, ... (each 3h + 1), the terms below n div 3, largest
  ## first, always ending in 1 (ELEMSORT-SHELL-04). `[1]` for n <= 3 and for n <= 0.
  var up = @[1]
  var h = 1
  while 3 * h + 1 < n div 3:
    h = 3 * h + 1
    up.add h
  for i in countdown(up.high, 0):
    result.add up[i]

func gapSorted[T](xs: openArray[T]; gaps: openArray[int]; less: Less[T]): seq[T] =
  var a = @xs
  for gap in gaps:
    for i in gap ..< a.len:
      let item = a[i]
      var j = i
      while j >= gap and less(item, a[j - gap]):
        a[j] = a[j - gap]
        j -= gap
      a[j] = item
  a

func shellSortWithGaps*[T](xs: openArray[T]; gaps: openArray[int];
    less: Less[T]): Result[seq[T], GapError] {.raises: [].} =
  ## Shellsort with the given gaps, which must be strictly descending, positive and end in 1
  ## (ELEMSORT-SHELL-05). The sort is correct for any such sequence (ELEMSORT-SHELL-02); only the
  ## speed depends on it. Not stable (ELEMSORT-SHELL-03).
  if gaps.len == 0:
    return err(seq[T], gapNone)
  for i, gap in gaps:
    if gap < 1:
      return err(seq[T], gapNotPositive)
    if i > 0 and gap >= gaps[i - 1]:
      return err(seq[T], gapNotDescending)
  if gaps[gaps.high] != 1:
    return err(seq[T], gapNoFinalOne)
  ok(gapSorted(xs, gaps, less), GapError)

func shellSort*[T](xs: openArray[T]; less: Less[T]): seq[T] {.raises: [].} =
  ## Ascending by `less`, with Knuth's gaps (ELEMSORT-SHELL-01). Not stable (ELEMSORT-SHELL-03).
  gapSorted(xs, shellGaps(xs.len), less)

func shellSort*[T](xs: openArray[T]): seq[T] {.raises: [].} =
  ## Ascending by `<`.
  shellSort(xs, proc(a, b: T): bool {.noSideEffect, raises: [].} = a < b)

## Eulerian trails by Hierholzer's algorithm: walk every edge of a graph exactly once.
##
## A trail that uses every edge once exists exactly when the edges form one connected piece and the
## degrees allow it. Undirected: zero or two vertices of odd degree (a self-loop adds 2). Directed:
## every vertex has out-degree equal to in-degree, except possibly one start vertex with one more
## out than in and one end vertex with one more in than out. Hierholzer's algorithm follows unused
## edges until it is stuck, which can only happen back at the start of a closed loop, and splices
## the loops it finds on the way back: an explicit stack of vertices, a pointer into each
## adjacency list, and the vertices written out in the order they are abandoned, reversed. Use it
## for route inspection, stroke-order puzzles and de Bruijn sequences.
##
## A trail is the list of vertices visited, so it has one more entry than the graph has edges; a
## graph with no edge has the empty trail. The answer is deterministic: the start is the
## unbalanced or odd-degree vertex when there is one, else the smallest vertex that has an edge,
## and edges are taken in the graph's neighbour order.

import std/options
import nimcs/algo/graph

type EulerPlan = object
  adjacency: seq[seq[(int, int)]]   ## per vertex: (neighbour, edge id), in neighbour order
  start: int
  edgeCount: int

func plan(g: Graph): Option[EulerPlan] {.raises: [].} =
  ## The adjacency with edge ids and a start vertex, or none when the degrees forbid a trail.
  let es = g.edges
  let n = g.vertexCount
  var adjacency = newSeq[seq[(int, int)]](n)
  var outDeg = newSeq[int](n)
  var inDeg = newSeq[int](n)
  for id, e in es:
    adjacency[e.source].add (e.target, id)
    inc outDeg[e.source]
    inc inDeg[e.target]
    if not g.isDirected:
      if e.source != e.target:
        adjacency[e.target].add (e.source, id)
      # An undirected edge is traversable both ways, so it counts at both ends.
      inc outDeg[e.target]
      inc inDeg[e.source]
  var first = -1        # smallest vertex that has an edge
  var startUp = -1      # vertex with one more out than in (directed) / smallest odd vertex (undirected)
  var endUp = -1
  var odd = 0
  for v in 0 ..< n:
    if outDeg[v] + inDeg[v] > 0 and first < 0:
      first = v
    if g.isDirected:
      let d = outDeg[v] - inDeg[v]
      if d == 1 and startUp < 0:
        startUp = v
      elif d == -1 and endUp < 0:
        endUp = v
      elif d != 0:
        return none(EulerPlan)
    elif outDeg[v] mod 2 == 1:
      inc odd
      if startUp < 0:
        startUp = v
  if g.isDirected and (startUp < 0) != (endUp < 0):
    return none(EulerPlan)
  if not g.isDirected and odd != 0 and odd != 2:
    return none(EulerPlan)
  some(EulerPlan(adjacency: adjacency, start: (if startUp >= 0: startUp else: first),
                 edgeCount: es.len))

func eulerianPath*(g: Graph): Option[seq[int]] {.raises: [].} =
  ## A trail using every edge exactly once, as the vertices visited; none when the degrees forbid
  ## one or the edges are not connected (GRAPH-EULER-01, GRAPH-EULER-02). A graph without edges
  ## has the empty trail (GRAPH-EULER-05).
  let p = plan(g)
  if p.isNone:
    return none(seq[int])
  let ctx = p.get
  if ctx.edgeCount == 0:
    return some(newSeq[int]())
  var used = newSeq[bool](ctx.edgeCount)
  var pointer = newSeq[int](g.vertexCount)
  var stack = @[ctx.start]
  var reverseTrail: seq[int]
  while stack.len > 0:
    let v = stack[^1]
    while pointer[v] < ctx.adjacency[v].len and used[ctx.adjacency[v][pointer[v]][1]]:
      inc pointer[v]
    if pointer[v] < ctx.adjacency[v].len:
      let (to, id) = ctx.adjacency[v][pointer[v]]
      used[id] = true
      stack.add to
    else:
      reverseTrail.add v
      stack.delete(stack.high)
  if reverseTrail.len != ctx.edgeCount + 1:
    return none(seq[int])        # some edges lie in a different component
  var trail = newSeq[int](reverseTrail.len)
  for i, v in reverseTrail:
    trail[reverseTrail.len - 1 - i] = v
  some(trail)

func eulerianCircuit*(g: Graph): Option[seq[int]] {.raises: [].} =
  ## A closed trail using every edge exactly once (first and last vertex equal), or none when the
  ## graph has no Eulerian trail or none that returns to its start (GRAPH-EULER-03).
  let trail = eulerianPath(g)
  if trail.isNone or (trail.get.len > 0 and trail.get[0] != trail.get[^1]):
    return none(seq[int])
  trail

## Fast Fibonacci by raising the matrix `[[1, 1], [1, 0]]` to the n-th power: its entries are
## F(n+1), F(n), F(n), F(n-1), and repeated squaring needs O(log n) multiplications.
##
## `fibMatrix` is exact and returns none beyond F(92), the last value that fits a signed 64-bit
## `int`; `fibMod` works modulo a validated modulus and accepts any n up to `high(int)`. Use the
## matrix form when n is huge and only a residue is needed, or as the first example of "a linear
## recurrence is a matrix power"; for small n a loop (`memoization.fibTable`) is simpler.

import std/options

type Mat = object
  a, b, c, d: uint64   # [[a, b], [c, d]]

const
  maxFibExact*: int = 92
    ## F(93) overflows a signed 64-bit integer.
  maxFibModulus*: int = 3_037_000_499
    ## Largest modulus whose residue products fit an `int`.

func mul(x, y: Mat): Mat {.raises: [].} =
  Mat(a: x.a * y.a + x.b * y.c, b: x.a * y.b + x.b * y.d,
      c: x.c * y.a + x.d * y.c, d: x.c * y.b + x.d * y.d)

func fibMatrix*(n: int): Option[int] {.raises: [].} =
  ## F(n) for 0 <= n <= `maxFibExact`, else none (NUM-FIBM-01, NUM-FIBM-03).
  ##
  ## Unsigned arithmetic wraps silently, so overflow is ruled out by bound: no power of the matrix
  ## beyond M^n is formed (the base is squared only while bits remain), and every entry of M^n is at
  ## most F(n+1) <= F(93) < 2^64.
  if n < 0 or n > maxFibExact:
    return none(int)
  var acc = Mat(a: 1, b: 0, c: 0, d: 1)
  var base = Mat(a: 1, b: 1, c: 1, d: 0)
  var e = n
  while e > 0:
    if (e and 1) == 1:
      acc = mul(acc, base)
    e = e shr 1
    if e > 0:
      base = mul(base, base)
  some(int(acc.b))

func fibMod*(n, m: int): Option[int] {.raises: [].} =
  ## F(n) mod m for n >= 0 and 1 <= m <= `maxFibModulus`, else none (NUM-FIBM-02, NUM-FIBM-04).
  if n < 0 or m < 1 or m > maxFibModulus:
    return none(int)
  func mulM(x, y: (int, int, int, int); m: int): (int, int, int, int) {.raises: [].} =
    ((x[0] * y[0] mod m + x[1] * y[2] mod m) mod m, (x[0] * y[1] mod m + x[1] * y[3] mod m) mod m,
     (x[2] * y[0] mod m + x[3] * y[2] mod m) mod m, (x[2] * y[1] mod m + x[3] * y[3] mod m) mod m)
  var acc = (1 mod m, 0, 0, 1 mod m)
  var base = (1 mod m, 1 mod m, 1 mod m, 0)
  var e = n
  while e > 0:
    if (e and 1) == 1:
      acc = mulM(acc, base, m)
    e = e shr 1
    if e > 0:
      base = mulM(base, base, m)
  some(acc[1])

## Floyd-Warshall: shortest paths between every pair, by allowing one more intermediate vertex at a time.
##
## Use it when you need distances between all pairs on a small dense graph (V up to a few hundred):
## O(V^3) time, O(V^2) space. Negative weights are fine; a negative cycle is reported as an error.
## For one source on a sparse graph, `dijkstra` or `bellman_ford` is cheaper. Distances are `int`.

import std/options
import nimcs/fp/result
import nimcs/algo/graph

type
  AllPairs* = object
    n: int
    dist: seq[Option[int]]    ## row-major n x n
    firstHop: seq[int]        ## row-major n x n: the vertex after u on a shortest u -> v path

  FloydError* = object
    ## The graph has a negative cycle; `vertex` lies on one.
    vertex*: int

func distance*(ap: AllPairs; u, v: int): Option[int] {.raises: [].} =
  ## Length of a shortest path u -> v, none when v is unreachable from u or either is not a vertex.
  if u < 0 or u >= ap.n or v < 0 or v >= ap.n: none(int) else: ap.dist[u * ap.n + v]

func pathBetween*(ap: AllPairs; u, v: int): Option[seq[int]] {.raises: [].} =
  ## The vertices of a shortest path u -> v, both ends included; none when unreachable
  ## (GRAPH-FLOYD-03).
  if ap.distance(u, v).isNone:
    return none(seq[int])
  var path = @[u]
  var current = u
  while current != v:
    current = ap.firstHop[current * ap.n + v]
    path.add current
    if path.len > ap.n:
      return none(seq[int])
  some(path)

func floydWarshall*(g: Graph): Result[AllPairs, FloydError] {.raises: [].} =
  ## All-pairs shortest distances (GRAPH-FLOYD-01), or a negative cycle (GRAPH-FLOYD-02).
  let n = g.vertexCount
  var dist = newSeq[Option[int]](n * n)
  var hop = newSeq[int](n * n)
  for v in 0 ..< n:
    dist[v * n + v] = some(0)
    hop[v * n + v] = v
  for u in 0 ..< n:
    for a in g.neighbors(u):
      let at = u * n + a.target
      if dist[at].isNone or a.weight < dist[at].get:
        dist[at] = some(a.weight)
        hop[at] = a.target
  for k in 0 ..< n:
    for i in 0 ..< n:
      let ik = dist[i * n + k]
      if ik.isNone: continue
      for j in 0 ..< n:
        let kj = dist[k * n + j]
        if kj.isNone: continue
        let through = ik.get + kj.get
        if dist[i * n + j].isNone or through < dist[i * n + j].get:
          dist[i * n + j] = some(through)
          hop[i * n + j] = hop[i * n + k]
    # A negative diagonal entry is a negative cycle; stopping here keeps the values from
    # doubling pass after pass on a graph that has one.
    for v in 0 ..< n:
      if dist[v * n + v].get < 0:
        return err(AllPairs, FloydError(vertex: v))
  ok(AllPairs(n: n, dist: dist, firstHop: hop), FloydError)

## An immutable graph value: vertices 0 ..< n and adjacency lists built from an edge list.
##
## Use it as the input of every graph algorithm in this package (`bfs`, `dfs`, `dijkstra`, ...).
## `buildGraph` is the only way to make one: it checks the edges and puts each neighbour list in
## ascending (target, weight) order, so the same set of edges gives equal graphs whatever order
## it arrived in, and every algorithm that visits neighbours in order is deterministic. An
## undirected edge is stored as two arcs (one for a self-loop). Parallel edges are kept.
## This module also holds the result types the algorithms share: `PathTree` and `SpanningForest`.

import std/[algorithm, options]
import nimcs/fp/result

type
  GraphKind* = enum
    gkDirected     ## an edge u -> v can be followed from u only
    gkUndirected   ## an edge u - v can be followed both ways

  GraphError* = enum
    geNegativeOrder      ## the vertex count is below zero
    geVertexOutOfRange   ## an endpoint (or a source) is not in 0 ..< n
    geNegativeWeight     ## the algorithm needs non-negative weights
    geNotUndirected      ## the algorithm is defined for undirected graphs only

  Edge* = object
    source*, target*, weight*: int

  Arc* = object
    ## One direction of an edge, as stored in a neighbour list.
    target*, weight*: int

  Graph* = object
    directed: bool
    adj: seq[seq[Arc]]

  PathTree* = object
    ## Shortest paths from one source: distance and predecessor of every vertex (none = unreached).
    source*: int
    dist*: seq[Option[int]]
    parent*: seq[Option[int]]

  SpanningForest* = object
    ## A minimum spanning tree of every connected component.
    edges*: seq[Edge]     ## in ascending (weight, source, target) order, source <= target
    totalWeight*: int
    components*: int

func `==`*(a, b: Edge): bool {.raises: [].} =
  a.source == b.source and a.target == b.target and a.weight == b.weight

func `==`*(a, b: Arc): bool {.raises: [].} =
  a.target == b.target and a.weight == b.weight

func `==`*(a, b: Graph): bool {.raises: [].} =
  a.directed == b.directed and a.adj == b.adj

func `==`*(a, b: PathTree): bool {.raises: [].} =
  a.source == b.source and a.dist == b.dist and a.parent == b.parent

func edge*(source, target: int; weight = 1): Edge {.raises: [].} =
  Edge(source: source, target: target, weight: weight)

func arcOrder(a, b: Arc): int =
  result = cmp(a.target, b.target)
  if result == 0:
    result = cmp(a.weight, b.weight)

func buildGraph*(order: int; edges: openArray[Edge]; kind: GraphKind): Result[Graph, GraphError] {.raises: [].} =
  ## A graph on vertices 0 ..< order. Fails when `order` is negative or an endpoint is outside
  ## that range (GRAPH-BUILD-02).
  if order < 0:
    return err(Graph, geNegativeOrder)
  var adj = newSeq[seq[Arc]](order)
  for e in edges:
    if e.source < 0 or e.source >= order or e.target < 0 or e.target >= order:
      return err(Graph, geVertexOutOfRange)
    adj[e.source].add Arc(target: e.target, weight: e.weight)
    if kind == gkUndirected and e.source != e.target:
      adj[e.target].add Arc(target: e.source, weight: e.weight)
  for v in 0 ..< order:
    adj[v] = sorted(adj[v], arcOrder)
  ok(Graph(directed: kind == gkDirected, adj: adj), GraphError)

func vertexCount*(g: Graph): int {.raises: [].} = g.adj.len

func isDirected*(g: Graph): bool {.raises: [].} = g.directed

func neighbors*(g: Graph; v: int): lent seq[Arc] {.raises: [].} =
  ## The arcs leaving `v`, ascending by (target, weight). `v` must be in 0 ..< vertexCount; an
  ## outside vertex is a caller bug and raises an `IndexDefect` (a Defect, not a failure value).
  g.adj[v]

func inRange*(g: Graph; v: int): bool {.raises: [].} = v >= 0 and v < g.adj.len

func arcCount*(g: Graph): int {.raises: [].} =
  for list in g.adj:
    result += list.len

func hasArc*(g: Graph; u, v: int): bool {.raises: [].} =
  ## Is there an arc u -> v? (Always symmetric for an undirected graph.)
  if not g.inRange(u) or not g.inRange(v):
    return false
  for a in g.adj[u]:
    if a.target == v:
      return true
  false

func edges*(g: Graph): seq[Edge] {.raises: [].} =
  ## Every edge once, in ascending (source, target, weight) order. For an undirected graph each
  ## edge is reported with source <= target (GRAPH-BUILD-03).
  for u in 0 ..< g.adj.len:
    for a in g.adj[u]:
      if g.directed or u <= a.target:
        result.add Edge(source: u, target: a.target, weight: a.weight)

func transpose*(g: Graph): Graph {.raises: [].} =
  ## Every arc reversed. An undirected graph is its own transpose (GRAPH-TRANSPOSE-01).
  if not g.directed:
    return g
  var adj = newSeq[seq[Arc]](g.adj.len)
  for u in 0 ..< g.adj.len:
    for a in g.adj[u]:
      adj[a.target].add Arc(target: u, weight: a.weight)
  for v in 0 ..< adj.len:
    adj[v] = sorted(adj[v], arcOrder)
  Graph(directed: true, adj: adj)

func distance*(t: PathTree; v: int): Option[int] {.raises: [].} =
  ## Length of a shortest path from the source to `v`; none when `v` is unreachable or not a vertex.
  if v < 0 or v >= t.dist.len: none(int) else: t.dist[v]

func pathTo*(t: PathTree; v: int): Option[seq[int]] {.raises: [].} =
  ## The vertices of a shortest path from the source to `v`, both ends included; none when
  ## `v` is unreachable (GRAPH-PATH-01).
  if v < 0 or v >= t.dist.len or t.dist[v].isNone:
    return none(seq[int])
  var path = @[v]
  var current = v
  while current != t.source:
    let p = t.parent[current]
    if p.isNone or path.len > t.dist.len:
      return none(seq[int])
    current = p.get
    path.add current
  path.reverse
  some(path)

## Heap sort: build a max-heap in an array, then repeatedly move the largest element to the end.
##
## Use it when you need an O(n log n) worst case with O(1) extra space beyond the result copy and
## do not need stability. It is not stable: equal elements may swap order. The input is never
## changed; the heap lives in a local copy.

type Less[T] = proc(a, b: T): bool {.noSideEffect, raises: [].}

func siftDown[T](heap: var seq[T]; root, size: int; less: Less[T]) {.raises: [].} =
  ## Restores the max-heap property below `root` within heap[0 ..< size].
  var parent = root
  while true:
    let left = 2 * parent + 1
    if left >= size:
      break
    var big = left
    if left + 1 < size and less(heap[left], heap[left + 1]):
      big = left + 1
    if not less(heap[parent], heap[big]):
      break
    swap(heap[parent], heap[big])
    parent = big

func heapSort*[T](xs: openArray[T]; less: Less[T]): seq[T] {.raises: [].} =
  ## Ascending by `less`. Not stable.
  var heap = @xs
  for root in countdown(heap.len div 2 - 1, 0):
    siftDown(heap, root, heap.len, less)
  for last in countdown(heap.len - 1, 1):
    swap(heap[0], heap[last])
    siftDown(heap, 0, last, less)
  heap

func heapSort*[T](xs: openArray[T]): seq[T] {.raises: [].} =
  ## Ascending by `<`.
  heapSort(xs, proc(a, b: T): bool {.noSideEffect, raises: [].} = a < b)

## Huffman coding: a prefix-free binary code that gives frequent symbols short code words.
##
## Use it to see how a greedy choice (always merge the two lightest subtrees) builds an optimal
## symbol-by-symbol code. The code words are returned as strings of '0' and '1' so that a reader
## can print and compare them; a real encoder would pack bits. Ties are broken by weight, then
## by the smallest symbol inside a subtree, and the first subtree taken becomes the 0 side, so the
## same frequencies give the same code whatever order they arrive in. Nothing is changed in place.

import std/[algorithm, heapqueue, options]
import nimcs/fp/result

type
  HuffmanError* = enum
    heEmptyInput       ## no symbol to build a code from
    heBadFrequency     ## a frequency below one
    heDuplicateSymbol  ## the same symbol listed twice
    heWeightOverflow   ## the total weight does not fit in an `int`
    heUnknownSymbol    ## `encode` met a symbol that has no code word
    heBadBits          ## `decode` met a character other than '0' or '1', a path that leads nowhere, or an unfinished code word

  Node = object
    weight, minSym: int
    sym: char
    left, right: int   ## indices into `nodes`; -1 for a leaf

  HuffmanCode* = object
    nodes: seq[Node]
    root: int
    words: seq[(char, string)]   ## ascending by symbol

func frequencies*(text: string): seq[(char, int)] {.raises: [].} =
  ## How often each character occurs, ascending by character; absent characters are left out.
  var counts: array[256, int]
  for c in text:
    inc counts[ord(c)]
  for i in 0 .. 255:
    if counts[i] > 0:
      result.add (char(i), counts[i])

func lookup(words: seq[(char, string)]; c: char): Option[string] =
  var lo = 0
  var hi = words.len - 1
  while lo <= hi:
    let mid = (lo + hi) div 2
    if words[mid][0] == c:
      return some(words[mid][1])
    if words[mid][0] < c: lo = mid + 1 else: hi = mid - 1
  none(string)

func wordsOf(nodes: seq[Node]; root: int): seq[(char, string)] =
  ## Walks the tree; a lone leaf gets the word "0" so that every symbol costs at least one bit.
  if nodes[root].left < 0:
    return @[(nodes[root].sym, "0")]
  var found: seq[(char, string)]
  var stack = @[(root, "")]
  while stack.len > 0:
    let (n, prefix) = stack.pop
    if nodes[n].left < 0:
      found.add (nodes[n].sym, prefix)
    else:
      stack.add (nodes[n].right, prefix & "1")
      stack.add (nodes[n].left, prefix & "0")
  sorted(found, proc(a, b: (char, string)): int = cmp(a[0], b[0]))

func buildCode*(freqs: openArray[(char, int)]): Result[HuffmanCode, HuffmanError] {.raises: [].} =
  ## The Huffman code of the given (symbol, frequency) pairs, in any order (CODING-HUFFMAN-01).
  ## Fails on an empty list, a frequency below one, a repeated symbol or a total that overflows
  ## (CODING-HUFFMAN-05).
  if freqs.len == 0:
    return err(HuffmanCode, heEmptyInput)
  let ordered = sorted(@freqs, proc(a, b: (char, int)): int = cmp(a[0], b[0]))
  var total = 0
  for i, (c, f) in ordered:
    if f < 1:
      return err(HuffmanCode, heBadFrequency)
    if i > 0 and ordered[i - 1][0] == c:
      return err(HuffmanCode, heDuplicateSymbol)
    if f > high(int) - total:
      return err(HuffmanCode, heWeightOverflow)
    total += f
  var nodes: seq[Node]
  var queue = initHeapQueue[(int, int, int)]()   # (weight, smallest symbol inside, node index)
  for (c, f) in ordered:
    nodes.add Node(weight: f, minSym: ord(c), sym: c, left: -1, right: -1)
    queue.push (f, ord(c), nodes.high)
  while queue.len > 1:
    let a = queue.pop
    let b = queue.pop
    nodes.add Node(weight: a[0] + b[0], minSym: min(a[1], b[1]), sym: '\0', left: a[2], right: b[2])
    queue.push (a[0] + b[0], min(a[1], b[1]), nodes.high)
  let root = queue.pop[2]
  ok(HuffmanCode(nodes: nodes, root: root, words: wordsOf(nodes, root)), HuffmanError)

func codeWords*(code: HuffmanCode): seq[(char, string)] {.raises: [].} =
  ## Every symbol with its code word, ascending by symbol.
  code.words

func wordOf*(code: HuffmanCode; c: char): Option[string] {.raises: [].} =
  ## The code word of `c`; none when `c` was not in the frequency list.
  lookup(code.words, c)

func isPrefixFree*(code: HuffmanCode): bool {.raises: [].} =
  ## True when no code word begins another. Always true for a built code (CODING-HUFFMAN-02); the check
  ## exists so a test can state the law instead of trusting the construction.
  for i in 0 ..< code.words.len:
    for j in 0 ..< code.words.len:
      if i != j:
        let a = code.words[i][1]
        let b = code.words[j][1]
        if a.len <= b.len and b[0 ..< a.len] == a:
          return false
  true

func encode*(code: HuffmanCode; text: string): Result[string, HuffmanError] {.raises: [].} =
  ## The concatenated code words of the characters of `text` (CODING-HUFFMAN-03). Fails with
  ## `heUnknownSymbol` on a character the code does not know (CODING-HUFFMAN-06).
  var bits = ""
  for c in text:
    let w = lookup(code.words, c)
    if w.isNone:
      return err(string, heUnknownSymbol)
    bits.add w.get
  ok(bits, HuffmanError)

func decode*(code: HuffmanCode; bits: string): Result[string, HuffmanError] {.raises: [].} =
  ## Reads `bits` back into text: `decode(encode(t)) == t` (CODING-HUFFMAN-03). Fails with `heBadBits`
  ## on a character other than '0' or '1', on a bit that has no branch (only possible for a
  ## one-symbol code, whose only word is "0"), and when the bits stop inside a code word (CODING-HUFFMAN-07).
  var text = ""
  var at = code.root
  let lone = code.nodes[code.root].left < 0
  for b in bits:
    if b != '0' and b != '1':
      return err(string, heBadBits)
    if lone:
      if b == '1':
        return err(string, heBadBits)
      text.add code.nodes[code.root].sym
    else:
      at = if b == '0': code.nodes[at].left else: code.nodes[at].right
      if code.nodes[at].left < 0:
        text.add code.nodes[at].sym
        at = code.root
  if at != code.root:
    return err(string, heBadBits)
  ok(text, HuffmanError)

## Knuth–Morris–Pratt substring search: never move backwards in the text.
##
## The failure table says, for each prefix of the pattern, how long its longest proper border is
## (a prefix that is also a suffix). After a mismatch the search resumes from that border instead of
## from scratch, so the work is linear in `text.len + pattern.len`. Use it for one pattern over
## streaming or adversarial text; `z_algorithm` gives the same answers by another route, and
## `rabin_karp` is the choice for many patterns of one length.
##
## Positions are 0-based start offsets of every occurrence, overlapping ones included. An empty
## pattern occurs at every offset 0 .. text.len (STR-KMP-04).

func kmpFailure*(pattern: string): seq[int] {.raises: [].} =
  ## `result[i]` is the length of the longest proper border of `pattern[0 .. i]` (STR-KMP-01).
  result = newSeq[int](pattern.len)
  var k = 0
  for i in 1 ..< pattern.len:
    while k > 0 and pattern[i] != pattern[k]:
      k = result[k - 1]
    if pattern[i] == pattern[k]:
      inc k
    result[i] = k

func kmpFindAll*(text, pattern: string): seq[int] {.raises: [].} =
  ## Start offsets of all occurrences of `pattern` in `text`, ascending (STR-KMP-02, STR-KMP-03).
  result = @[]
  if pattern.len == 0:
    for i in 0 .. text.len:
      result.add i
    return
  let fail = kmpFailure(pattern)
  var k = 0
  for i in 0 ..< text.len:
    while k > 0 and text[i] != pattern[k]:
      k = fail[k - 1]
    if text[i] == pattern[k]:
      inc k
    if k == pattern.len:
      result.add i - pattern.len + 1
      k = fail[k - 1]

## 0/1 knapsack: choose a subset of items, each at most once, to maximise total value without
## exceeding a weight capacity.
##
## Use it when items are indivisible and capacity is a small integer; the table has
## `items * (capacity + 1)` cells, so it is pseudo-polynomial (reach for branch and bound or an
## approximation scheme when the capacity is huge). When items may be split, the greedy
## value-per-weight rule is optimal instead (`fractionalKnapsack` in `greedy`). Totals are assumed not to overflow
## `int`: that is the caller's precondition, not checked here.

import std/options

const maxTableCells*: int = 100_000_000
  ## Largest `(items + 1) * (capacity + 1)` the table may have (800 MB of `int`); beyond it
  ## `knapsack` returns none instead of exhausting memory or overflowing the size.

type
  Item* = object
    weight*, value*: int

  Packing* = object
    ## `chosen` holds the indices of the picked items, ascending.
    value*: int
    weight*: int
    chosen*: seq[int]

func item*(weight, value: int): Option[Item] {.raises: [].} =
  ## An item needs a non-negative weight and a non-negative value (DP-KNAP-04).
  if weight < 0 or value < 0: none(Item)
  else: some(Item(weight: weight, value: value))

func knapsack*(items: openArray[Item]; capacity: int): Option[Packing] {.raises: [].} =
  ## Best packing. None when `capacity` < 0 or an item has a negative weight or value (DP-KNAP-04),
  ## or when the table would exceed `maxTableCells` (DP-KNAP-06).
  ## Among equally valuable packings it returns the one found by walking back from the last item
  ## and keeping an item only when leaving it out would be strictly worse (DP-KNAP-05).
  if capacity < 0 or capacity >= maxTableCells div (items.len + 1):
    return none(Packing)
  for it in items:
    if it.weight < 0 or it.value < 0:
      return none(Packing)
  let w = capacity + 1
  var table = newSeq[int]((items.len + 1) * w)
  for i in 1 .. items.len:
    let it = items[i - 1]
    for c in 0 .. capacity:
      let skip = table[(i - 1) * w + c]
      table[i * w + c] =
        if it.weight <= c: max(skip, table[(i - 1) * w + c - it.weight] + it.value)
        else: skip
  var c = capacity
  var picked: seq[int] = @[]
  var totalWeight = 0
  for i in countdown(items.len, 1):
    if table[i * w + c] != table[(i - 1) * w + c]:
      picked.add i - 1
      c -= items[i - 1].weight
      totalWeight += items[i - 1].weight
  var chosen = newSeq[int](picked.len)
  for k in 0 ..< picked.len:
    chosen[k] = picked[picked.len - 1 - k]
  some(Packing(value: table[items.len * w + capacity], weight: totalWeight, chosen: chosen))

## Kruskal's algorithm: take the cheapest edges first, skipping any that would close a cycle.
##
## Use it to connect all vertices of an undirected weighted graph at least total cost (cabling,
## clustering). Sorting the edges dominates: O(E log E); a union-find forest (union by size and
## path halving: inverse-Ackermann amortized) tells in near-constant time whether two vertices are already joined. On a disconnected graph the result is a spanning
## forest, one tree per component. A directed graph is refused. `prim` gives the same total weight.

import std/algorithm
import nimcs/fp/result
import nimcs/algo/graph

func root(parent: var seq[int]; x: int): int {.raises: [].} =
  ## Representative of x's set; halves the path as it climbs.
  var current = x
  while parent[current] != current:
    parent[current] = parent[parent[current]]
    current = parent[current]
  current

func byWeight(a, b: Edge): int =
  result = cmp(a.weight, b.weight)
  if result == 0:
    result = cmp(a.source, b.source)
  if result == 0:
    result = cmp(a.target, b.target)

func kruskal*(g: Graph): Result[SpanningForest, GraphError] {.raises: [].} =
  ## A minimum spanning forest (GRAPH-KRUSKAL-01). Fails with `geNotUndirected` for a directed graph.
  if g.isDirected:
    return err(SpanningForest, geNotUndirected)
  let n = g.vertexCount
  var parent = newSeq[int](n)
  var size = newSeq[int](n)
  for v in 0 ..< n:
    parent[v] = v
    size[v] = 1
  var forest = SpanningForest(components: n)
  for e in sorted(g.edges, byWeight):
    let a = root(parent, e.source)
    let b = root(parent, e.target)
    if a != b:
      let (big, small) = if size[a] >= size[b]: (a, b) else: (b, a)
      parent[small] = big          # the smaller tree hangs under the larger: depth stays O(log n)
      size[big] += size[small]
      forest.edges.add e
      forest.totalWeight += e.weight
      dec forest.components
  ok(forest, GraphError)

## Lowest common ancestor by binary lifting.
##
## A rooted tree is given as a parent array (the root's parent is -1). Preprocessing stores, for
## every vertex v and every k, the 2^k-th ancestor `up[k][v]`, in O(n log n) space; any ancestor
## k steps up is then reached by the set bits of k, and the LCA of u and v is found by lifting the
## deeper vertex to the other's depth and then lifting both together while their ancestors differ.
## Each query costs O(log n). Use it when a tree is fixed and many queries follow (distances,
## path queries); for a single query walking up the parent array is simpler, and an Euler tour
## with a sparse table gives O(1) queries at the same preprocessing cost.
##
## The structure is an immutable value; a query never changes it. A vertex outside the tree is
## answered with none rather than an error, since asking about it is an ordinary question.

import std/options
import nimcs/fp/result

type
  LcaError* = enum
    leEmpty             ## a tree needs at least one vertex
    leParentOutOfRange  ## a parent is neither -1 nor a vertex
    leRootCount         ## the number of vertices whose parent is -1 is not exactly one
    leNotConnected      ## some vertex cannot reach the root (a cycle among parents)

  LcaTree* = object
    depths: seq[int]
    up: seq[seq[int]]      ## up[k][v] = the 2^k-th ancestor of v, or -1 beyond the root

func buildLca*(parent: openArray[int]): Result[LcaTree, LcaError] {.raises: [].} =
  ## Prepares `parent` (parent[v] is the parent of v, -1 for the one root) for queries. Fails
  ## when it is empty, names a parent out of range, has no root or several, or contains a cycle
  ## (LCA-BUILD-01).
  let n = parent.len
  if n == 0:
    return err(LcaTree, leEmpty)
  var root = -1
  var rootCount = 0
  var children = newSeq[seq[int]](n)
  for v, p in parent:
    if p < -1 or p >= n:
      return err(LcaTree, leParentOutOfRange)
    if p == -1:
      root = v
      inc rootCount
    else:
      children[p].add v
  if rootCount != 1:
    return err(LcaTree, leRootCount)
  # Breadth first from the root: parents come before children, and every vertex is reached
  # exactly once unless the parent links contain a cycle.
  var depths = newSeq[int](n)
  var order = @[root]
  var head = 0
  while head < order.len:
    let v = order[head]
    inc head
    for c in children[v]:
      depths[c] = depths[v] + 1
      order.add c
  if order.len != n:
    return err(LcaTree, leNotConnected)
  var levels = 1
  while (1 shl levels) < n:
    inc levels
  var up = newSeq[seq[int]](levels)
  up[0] = @parent
  for k in 1 ..< levels:
    up[k] = newSeq[int](n)
    for v in 0 ..< n:
      let mid = up[k - 1][v]
      up[k][v] = if mid < 0: -1 else: up[k - 1][mid]
  ok(LcaTree(depths: depths, up: up), LcaError)

func size*(t: LcaTree): int {.raises: [].} = t.depths.len

func contains*(t: LcaTree; v: int): bool {.raises: [].} = v >= 0 and v < t.depths.len

func depth*(t: LcaTree; v: int): Option[int] {.raises: [].} =
  ## Number of edges from the root to `v`; none when `v` is not a vertex (LCA-DEPTH-01).
  if v in t: some(t.depths[v]) else: none(int)

func kthAncestor*(t: LcaTree; v, k: int): Option[int] {.raises: [].} =
  ## The vertex `k` steps above `v` (k = 0 is `v`); none when `v` is not a vertex, `k` is negative,
  ## or `k` goes past the root (LCA-ANCESTOR-01).
  if v notin t or k < 0 or k > t.depths[v]:
    return none(int)
  var current = v
  for bit in 0 ..< t.up.len:
    if ((k shr bit) and 1) == 1:
      current = t.up[bit][current]
  some(current)

func lca*(t: LcaTree; u, v: int): Option[int] {.raises: [].} =
  ## The deepest vertex that is an ancestor of both `u` and `v` (a vertex is its own ancestor);
  ## none when either is not a vertex (LCA-QUERY-01, LCA-QUERY-02).
  if u notin t or v notin t:
    return none(int)
  var a = u
  var b = v
  if t.depths[a] < t.depths[b]:
    swap(a, b)
  a = t.kthAncestor(a, t.depths[a] - t.depths[b]).get
  if a == b:
    return some(a)
  for bit in countdown(t.up.len - 1, 0):
    if t.up[bit][a] != t.up[bit][b]:
      a = t.up[bit][a]
      b = t.up[bit][b]
  some(t.up[0][a])

func distance*(t: LcaTree; u, v: int): Option[int] {.raises: [].} =
  ## Number of edges on the path between `u` and `v`; none when either is not a vertex
  ## (LCA-DISTANCE-01).
  let meet = t.lca(u, v)
  if meet.isNone:
    return none(int)
  some(t.depths[u] + t.depths[v] - 2 * t.depths[meet.get])

## Longest common subsequence: the longest sequence that can be obtained from both inputs by
## deleting elements (not necessarily contiguous ones).
##
## Use it to compare two sequences when order matters but gaps are allowed (diff tools, DNA
## similarity). The table is a local `var`; the public routines are pure. For contiguous
## matches use `kmp` or `suffix_array` instead.

func lcsLength*[T](a, b: openArray[T]): int {.raises: [].} =
  ## Length of a longest common subsequence (DP-LCS-01, DP-LCS-03).
  var prev = newSeq[int](b.len + 1)
  var cur = newSeq[int](b.len + 1)
  for i in 1 .. a.len:
    for j in 1 .. b.len:
      cur[j] =
        if a[i - 1] == b[j - 1]: prev[j - 1] + 1
        else: max(prev[j], cur[j - 1])
    swap(prev, cur)
  prev[b.len]

func lcs*[T](a, b: openArray[T]): seq[T] {.raises: [].} =
  ## One longest common subsequence. Among the longest ones it is the one the backtrack from the
  ## bottom-right corner finds, preferring to move up on a tie (deterministic, DP-LCS-05).
  let w = b.len + 1
  var table = newSeq[int]((a.len + 1) * w)
  for i in 1 .. a.len:
    for j in 1 .. b.len:
      table[i * w + j] =
        if a[i - 1] == b[j - 1]: table[(i - 1) * w + j - 1] + 1
        else: max(table[(i - 1) * w + j], table[i * w + j - 1])
  var i = a.len
  var j = b.len
  var rev: seq[T] = @[]
  while i > 0 and j > 0:
    if a[i - 1] == b[j - 1]:
      rev.add a[i - 1]
      dec i
      dec j
    elif table[(i - 1) * w + j] >= table[i * w + j - 1]:
      dec i
    else:
      dec j
  result = newSeq[T](rev.len)
  for k in 0 ..< rev.len:
    result[k] = rev[rev.len - 1 - k]

func lcs*(a, b: string): string {.raises: [].} =
  ## The string form of `lcs`.
  var chars: seq[char] = @[]
  for c in lcs(a.toOpenArray(0, a.high), b.toOpenArray(0, b.high)):
    chars.add c
  result = newString(chars.len)
  for k in 0 ..< chars.len:
    result[k] = chars[k]

func isSubsequence*[T](small, big: openArray[T]): bool {.raises: [].} =
  ## True when `small` can be read off `big` left to right with gaps (DP-LCS-02).
  var at = 0
  for x in big:
    if at < small.len and small[at] == x:
      inc at
  at == small.len

## Maximum flow (Edmonds-Karp) and, as an application, maximum bipartite matching.
##
## Use it to ask how much can be sent from a source to a sink through capacity-limited arcs (pipes,
## links, assignments). The weight of each arc of a `Graph` is its capacity. Edmonds-Karp
## repeatedly sends flow along a shortest (fewest-arcs) path in the residual graph, which bounds
## the number of augmentations by V * E / 2 whatever the capacities are. The answer carries the
## flow, and a minimum cut found from the last residual graph, so the max-flow = min-cut law can
## be checked on every result. An undirected graph gives each direction of an edge its full
## capacity. Sums of capacities must fit in an `int` (an overflow is a Defect, not a value).

import std/algorithm
import nimcs/fp/result
import nimcs/algo/graph

type
  FlowError* = enum
    feVertexOutOfRange   ## source, sink or a matching pair names a vertex that does not exist
    feNegativeCapacity   ## an arc has a negative capacity
    feSameEndpoints      ## source and sink are the same vertex
    feNegativeCount      ## a bipartite side has a negative size

  FlowSolution* = object
    value*: int              ## the amount of flow from source to sink
    flows*: seq[Edge]        ## per ordered pair (source, target) the flow it carries (weight > 0), ascending
    sourceSide*: seq[int]    ## vertices still reachable from the source in the last residual graph, ascending
    cut*: seq[Edge]          ## the arcs from `sourceSide` to the other vertices: a minimum cut

func maxFlow*(g: Graph; source, sink: int): Result[FlowSolution, FlowError] {.raises: [].} =
  ## Maximum flow from `source` to `sink` (GRAPH-MAXFLOW-01), with the minimum cut that proves
  ## it is maximum (GRAPH-MAXFLOW-02). The flow respects every capacity and conserves flow at every
  ## other vertex (GRAPH-MAXFLOW-03). Fails on a bad vertex, equal endpoints or a negative
  ## capacity (GRAPH-MAXFLOW-04).
  if not g.inRange(source) or not g.inRange(sink):
    return err(FlowSolution, feVertexOutOfRange)
  if source == sink:
    return err(FlowSolution, feSameEndpoints)
  let n = g.vertexCount
  # Edge 2k is an original arc, edge 2k + 1 its reverse; `residual` is what can still be sent.
  var head: seq[int]            # head[e]: where edge e leads
  var residual: seq[int]
  var original: seq[int]
  var adj = newSeq[seq[int]](n)
  for u in 0 ..< n:
    for a in g.neighbors(u):
      if a.weight < 0:
        return err(FlowSolution, feNegativeCapacity)
      if a.target == u:
        continue                # a self-loop can carry no flow from source to sink
      adj[u].add head.len
      head.add a.target
      residual.add a.weight
      original.add a.weight
      adj[a.target].add head.len
      head.add u
      residual.add 0
      original.add 0
  var total = 0
  while true:
    var via = newSeq[int](n)    # edge used to reach each vertex, -1 = not reached
    for v in 0 ..< n:
      via[v] = -1
    var queue = @[source]
    var next = 0
    var reached = newSeq[bool](n)
    reached[source] = true
    while next < queue.len and not reached[sink]:
      let u = queue[next]
      inc next
      for e in adj[u]:
        if residual[e] > 0 and not reached[head[e]]:
          reached[head[e]] = true
          via[head[e]] = e
          queue.add head[e]
    if not reached[sink]:
      var side: seq[int]
      for v in 0 ..< n:
        if reached[v]:
          side.add v
      var cut: seq[Edge]
      var carried: seq[Edge]
      for u in 0 ..< n:
        for e in adj[u]:
          if e mod 2 == 0:
            let f = original[e] - residual[e]
            if f > 0:
              carried.add Edge(source: u, target: head[e], weight: f)
            if reached[u] and not reached[head[e]]:
              cut.add Edge(source: u, target: head[e], weight: original[e])
      carried = sorted(carried, proc(a, b: Edge): int =
        result = cmp(a.source, b.source)
        if result == 0:
          result = cmp(a.target, b.target))
      var merged: seq[Edge]
      for f in carried:
        if merged.len > 0 and merged[^1].source == f.source and merged[^1].target == f.target:
          merged[^1].weight += f.weight
        else:
          merged.add f
      return ok(FlowSolution(value: total, flows: merged, sourceSide: side, cut: cut), FlowError)
    var bottleneck = high(int)
    var v = sink
    while v != source:
      let e = via[v]
      bottleneck = min(bottleneck, residual[e])
      v = head[e xor 1]
    v = sink
    while v != source:
      let e = via[v]
      residual[e] -= bottleneck
      residual[e xor 1] += bottleneck
      v = head[e xor 1]
    total += bottleneck

func bipartiteMatching*(leftCount, rightCount: int;
    pairs: openArray[(int, int)]): Result[seq[(int, int)], FlowError] {.raises: [].} =
  ## A maximum set of (left, right) pairs, drawn from `pairs`, in which no left and no right
  ## vertex repeats (GRAPH-MATCHING-01, GRAPH-MATCHING-02). Left vertices are 0 ..< leftCount,
  ## right vertices 0 ..< rightCount. Ascending by left vertex. It is max flow in a network with
  ## a source before every left vertex and a sink after every right vertex, all capacities 1.
  ## Fails on a negative count or a pair outside the sides (GRAPH-MATCHING-03).
  if leftCount < 0 or rightCount < 0:
    return err(seq[(int, int)], feNegativeCount)
  let s = leftCount + rightCount
  let t = s + 1
  var arcs: seq[Edge]
  for l in 0 ..< leftCount:
    arcs.add edge(s, l, 1)
  for r in 0 ..< rightCount:
    arcs.add edge(leftCount + r, t, 1)
  for (l, r) in pairs:
    if l < 0 or l >= leftCount or r < 0 or r >= rightCount:
      return err(seq[(int, int)], feVertexOutOfRange)
    arcs.add edge(l, leftCount + r, 1)
  let g = buildGraph(t + 1, arcs, gkDirected)
  if not g.isOk:
    return err(seq[(int, int)], feVertexOutOfRange)
  let solved = maxFlow(g.value, s, t)
  if not solved.isOk:
    return err(seq[(int, int)], solved.error)
  var matching: seq[(int, int)]
  for f in solved.value.flows:
    if f.source < leftCount and f.target >= leftCount and f.target < s:
      matching.add (f.source, f.target - leftCount)
  ok(matching, FlowError)

## Meet in the middle: subset sums in about 2^(n/2) work instead of 2^n.
##
## Split the items into two halves, list every subset sum of each half (at most 2^(n/2) sums), sort
## both lists, and combine them: a subset of the whole is one subset of each half, so a target is
## reached exactly when some left sum plus some right sum equals it, which a binary search on the
## sorted right list finds. Use it when n is too big for 2^n (n around 30 to 40) but too small for
## a pseudo-polynomial table because the values are large; when the values are small, `knapsack`
## style dynamic programming is cheaper.
##
## Subsets are counted by index: two equal items are distinct choices, and the empty subset has
## sum 0. Items may be negative. To keep every sum inside `int`, at most `MaxItems` items of
## absolute value at most `MaxItemValue` are accepted and the target must have absolute value at
## most `MaxTarget`.

import std/[algorithm, options]
import nimcs/fp/result

const
  MaxItems*: int = 40              ## at most this many items (two halves of at most 20)
  MaxItemValue*: int = 1_000_000_000_000   ## |item| <= this, so 40 items sum to at most 4e13
  MaxTarget*: int = 1_000_000_000_000_000  ## |target| <= this, so differences stay far below 2^63

type MitmError* = enum
  meTooManyItems   ## more than MaxItems items
  meItemTooLarge   ## an item has absolute value above MaxItemValue
  meTargetTooLarge ## the target has absolute value above MaxTarget

func halfSums(items: openArray[int]): seq[int] {.raises: [].} =
  ## All 2^len subset sums of `items`, ascending (duplicates kept).
  result = @[0]
  for x in items:
    var more = newSeq[int](result.len)
    for i, s in result:
      more[i] = s + x
    result = result & more
  result.sort

func violation(items: openArray[int]; target: int): Option[MitmError] {.raises: [].} =
  ## The first limit the input breaks, if any (MITM-LIMIT-01).
  if items.len > MaxItems:
    return some(meTooManyItems)
  for x in items:
    if abs(x) > MaxItemValue:
      return some(meItemTooLarge)
  if abs(target) > MaxTarget:
    return some(meTargetTooLarge)
  none(MitmError)

func halves(items: openArray[int]): (seq[int], seq[int]) {.raises: [].} =
  let mid = items.len div 2
  (halfSums(items[0 ..< mid]), halfSums(items[mid ..< items.len]))

func countSubsetSum*(items: openArray[int]; target: int): Result[int, MitmError] {.raises: [].} =
  ## The number of index-distinct subsets of `items` (the empty one included) whose sum is
  ## `target` (MITM-COUNT-01, MITM-COUNT-02).
  let broken = violation(items, target)
  if broken.isSome:
    return err(int, broken.get)
  let (left, right) = halves(items)
  var total = 0
  for l in left:
    let want = target - l
    total += right.upperBound(want) - right.lowerBound(want)
  ok(total, MitmError)

func subsetSumExists*(items: openArray[int]; target: int): Result[bool, MitmError] {.raises: [].} =
  ## Does some subset of `items` (possibly empty) sum to `target`? (MITM-EXISTS-01)
  let count = countSubsetSum(items, target)
  if count.isErr:
    return err(bool, count.error)
  ok(count.value > 0, MitmError)

func closestSubsetSum*(items: openArray[int]; target: int): Result[int, MitmError] {.raises: [].} =
  ## The subset sum nearest to `target`; on a tie the smaller sum (MITM-CLOSEST-01,
  ## MITM-CLOSEST-02).
  let broken = violation(items, target)
  if broken.isSome:
    return err(int, broken.get)
  let (left, right) = halves(items)
  var best = left[0] + right[0]
  for l in left:
    let want = target - l
    let at = right.lowerBound(want)     # first right sum >= want
    for i in [at - 1, at]:
      if i >= 0 and i < right.len:
        let s = l + right[i]
        let gap = abs(s - target)
        let bestGap = abs(best - target)
        if gap < bestGap or (gap == bestGap and s < best):
          best = s
  ok(best, MitmError)

## Memoization without hidden state: the table of already computed answers is a value that is
## passed in and handed back, so a call can be repeated, replayed or shared between callers.
##
## Use it when a recursive definition recomputes the same sub-problems (Fibonacci, paths in a
## grid). The top-down form (`fibMemo`, `gridPathsMemo`) threads a `Memo` through the recursion;
## the bottom-up form (`fibTable`, `gridPathsTable`) fills a local table in dependency order.
## Both give the same answers (DP-MEMO-02, DP-MEMO-05). Neither uses a global cache, so a
## function that looks "memoized" from the outside is still a pure function of its arguments.

import std/[options, tables]

type
  Memo*[K, V] = object
    ## Answers already known, keyed by the sub-problem. Never mutated in place by a caller:
    ## `put` returns a new memo.
    cells: Table[K, V]

  FibResult* = object
    ## The answer and the memo to pass to the next call.
    value*: int
    memo*: Memo[int, int]

  GridResult* = object
    paths*: int
    memo*: Memo[(int, int), int]

const
  maxFib* = 92
    ## `fib(93)` does not fit a signed 64-bit integer.
  maxGridSteps* = 64
    ## `rows + cols` up to this bound keeps the path count below `high(int)`.

func initMemo*[K, V](): Memo[K, V] {.raises: [].} =
  Memo[K, V](cells: initTable[K, V]())

func get*[K, V](m: Memo[K, V]; key: K): Option[V] {.raises: [].} =
  ## The stored answer, or none (DP-MEMO-03).
  if m.cells.hasKey(key): some(m.cells.getOrDefault(key)) else: none(V)

func put*[K, V](m: Memo[K, V]; key: K; value: V): Memo[K, V] {.raises: [].} =
  ## A memo that also knows `key`; `m` itself is unchanged (DP-MEMO-03).
  result = m
  result.cells[key] = value

func len*[K, V](m: Memo[K, V]): int {.raises: [].} =
  m.cells.len

func fibStep(n: int; memo: Memo[int, int]): FibResult {.raises: [].} =
  if n < 2:
    return FibResult(value: n, memo: memo)
  let known = memo.get(n)
  if known.isSome:
    return FibResult(value: known.get, memo: memo)
  let a = fibStep(n - 1, memo)
  let b = fibStep(n - 2, a.memo)
  let total = a.value + b.value
  FibResult(value: total, memo: b.memo.put(n, total))

func fibMemo*(n: int; memo: Memo[int, int]): Option[FibResult] {.raises: [].} =
  ## Fibonacci, top-down, threading `memo`. None unless 0 <= n <= `maxFib` (DP-MEMO-04).
  if n < 0 or n > maxFib: none(FibResult)
  else: some(fibStep(n, memo))

func fibTable*(n: int): Option[int] {.raises: [].} =
  ## Fibonacci, bottom-up with two rolling values. None unless 0 <= n <= `maxFib`.
  if n < 0 or n > maxFib:
    return none(int)
  if n == 0:
    return some(0)
  var prev = 0
  var cur = 1
  for _ in 1 ..< n:
    let next = prev + cur
    prev = cur
    cur = next
  some(cur)

func gridStep(r, c: int; memo: Memo[(int, int), int]): GridResult {.raises: [].} =
  if r == 0 or c == 0:
    return GridResult(paths: 1, memo: memo)
  let known = memo.get((r, c))
  if known.isSome:
    return GridResult(paths: known.get, memo: memo)
  let a = gridStep(r - 1, c, memo)
  let b = gridStep(r, c - 1, a.memo)
  let total = a.paths + b.paths
  GridResult(paths: total, memo: b.memo.put((r, c), total))

func gridPathsMemo*(rows, cols: int; memo: Memo[(int, int), int]): Option[GridResult] {.raises: [].} =
  ## Number of right/down paths from the top-left to the bottom-right cell of a `rows` x `cols`
  ## grid, top-down. None unless both are >= 1 and `rows + cols` <= `maxGridSteps`.
  if rows < 1 or cols < 1 or rows + cols > maxGridSteps: none(GridResult)
  else: some(gridStep(rows - 1, cols - 1, memo))

func gridPathsTable*(rows, cols: int): Option[int] {.raises: [].} =
  ## The same count, bottom-up with one rolling row.
  if rows < 1 or cols < 1 or rows + cols > maxGridSteps:
    return none(int)
  var row = newSeq[int](cols)
  for j in 0 ..< cols:
    row[j] = 1
  for _ in 1 ..< rows:
    for j in 1 ..< cols:
      row[j] += row[j - 1]
  some(row[cols - 1])

## Integer number theory: greatest common divisor, Bezout coefficients, modular exponentiation
## and modular inverses.
##
## Every routine that can fail says so in its type. `gcd`, `lcm` and `extGcd` return `Option`
## because `abs(low(int))` and some products are not representable; `powMod` and `modInverse`
## take a `Modulus`, a distinct type built by `modulus`, so a zero or negative modulus cannot reach
## them. The largest modulus is chosen so that the product of two residues fits an `int`
## (see `maxModulus`). Use these as the building blocks for RSA-style toy examples, hashing
## and the Chinese remainder theorem; for large moduli use a big-integer library.

import std/options

type
  Modulus* = distinct int
  Bezout* = object
    ## `a * x + b * y == g` with `g` the (non-negative) gcd.
    g*, x*, y*: int

const maxModulus*: int = 3_037_000_499
  ## floor(sqrt(2^63 - 1)): `(m - 1) * (m - 1)` still fits a 64-bit `int`.

func modulus*(m: int): Option[Modulus] {.raises: [].} =
  ## A modulus lies in 1 .. `maxModulus` (NUM-NT-06).
  if m < 1 or m > maxModulus: none(Modulus) else: some(Modulus(m))

func `==`*(a, b: Modulus): bool {.borrow.}
func `$`*(m: Modulus): string {.borrow.}

func toInt*(m: Modulus): int {.raises: [].} = int(m)

func residue*(a: int; m: Modulus): int {.raises: [].} =
  ## `a` reduced into 0 ..< m, also for negative `a`.
  let mi = int(m)
  ((a mod mi) + mi) mod mi

func gcd*(a, b: int): Option[int] {.raises: [].} =
  ## Greatest common divisor, never negative; `gcd(0, 0)` is 0. None when an argument is
  ## `low(int)`, whose magnitude does not fit (NUM-NT-01).
  if a == low(int) or b == low(int):
    return none(int)
  var x = abs(a)
  var y = abs(b)
  while y != 0:
    (x, y) = (y, x mod y)
  some(x)

func lcm*(a, b: int): Option[int] {.raises: [].} =
  ## Least common multiple, never negative; zero if either argument is zero. None on overflow
  ## or `low(int)` (NUM-NT-02).
  let g = gcd(a, b)
  if g.isNone:
    return none(int)
  if a == 0 or b == 0:
    return some(0)
  let q = abs(a) div g.get
  let m = abs(b)
  if q > high(int) div m: none(int) else: some(q * m)

func extGcd*(a, b: int): Option[Bezout] {.raises: [].} =
  ## The gcd with Bezout coefficients: `a * x + b * y == g` (NUM-NT-03). None when an argument is
  ## `low(int)`.
  if a == low(int) or b == low(int):
    return none(Bezout)
  var oldR = abs(a)
  var r = abs(b)
  var oldS = 1
  var s = 0
  var oldT = 0
  var t = 1
  while r != 0:
    let q = oldR div r
    (oldR, r) = (r, oldR - q * r)
    (oldS, s) = (s, oldS - q * s)
    (oldT, t) = (t, oldT - q * t)
  some(Bezout(g: oldR, x: (if a < 0: -oldS else: oldS), y: (if b < 0: -oldT else: oldT)))

func powMod*(base, exp: int; m: Modulus): Option[int] {.raises: [].} =
  ## `base ^ exp mod m` by repeated squaring, in 0 ..< m. None for a negative exponent
  ## (NUM-NT-04). `powMod(x, 0, m)` is 1 mod m, so 0 when `m` is 1.
  if exp < 0:
    return none(int)
  let mi = int(m)
  var acc = 1 mod mi
  var b = residue(base, m)
  var e = exp
  while e > 0:
    if (e and 1) == 1:
      acc = acc * b mod mi
    e = e shr 1
    if e > 0:
      b = b * b mod mi
  some(acc)

func modInverse*(a: int; m: Modulus): Option[int] {.raises: [].} =
  ## The `x` in 0 ..< m with `a * x ≡ 1 (mod m)`, or none when `a` and `m` are not coprime
  ## (NUM-NT-05).
  let r = extGcd(residue(a, m), int(m))
  if r.isNone or r.get.g != 1:
    return none(int)
  some(residue(r.get.x, m))

## Prefix sums, difference arrays and two-dimensional prefix sums.
##
## Use a prefix-sum table when many range-sum questions are asked of data that does not change:
## one O(n) pass pays for O(1) per question (sum of xs[l ..< r] is prefix[r] - prefix[l]). Use a
## difference array for the opposite job, many "add d to every element of l ..< r" updates followed
## by one read: store only the changes between neighbours, then a running sum restores the values.
## The two are inverses of each other. The 2-D table answers rectangle sums in O(1) by
## inclusion-exclusion. All ranges are half-open (`l ..< r`). Sums are `int`; the caller keeps them
## from overflowing. Nothing is changed in place, and an update returns a new value.

import nimcs/fp/result

type
  SpanError* = enum
    reOutOfBounds   ## an index outside 0 .. length (rows or columns for a rectangle)
    reReversed      ## the start of a range is after its end
    reRagged        ## the rows of a grid do not all have the same length

  PrefixSums* = object
    ## `sums[i]` is the sum of the first i elements, so `sums.len` is the element count plus one.
    sums: seq[int]

  PrefixSums2D* = object
    ## `sums[i * (cols + 1) + j]` is the sum of the rectangle of the first i rows and first j columns.
    rows, cols: int
    sums: seq[int]

func prefixOf*(xs: openArray[int]): PrefixSums {.raises: [].} =
  ## The table of running sums: entry 0 is 0 and entry i + 1 is entry i plus `xs[i]`
  ## (TECH-PREFIX-01).
  var sums = newSeq[int](xs.len + 1)
  for i, x in xs:
    sums[i + 1] = sums[i] + x
  PrefixSums(sums: sums)

func count*(p: PrefixSums): int {.raises: [].} =
  ## How many elements the table covers.
  p.sums.len - 1

func rangeSum*(p: PrefixSums; l, r: int): Result[int, SpanError] {.raises: [].} =
  ## The sum of the elements l ..< r, in O(1) (TECH-PREFIX-02). Fails with `reOutOfBounds` unless
  ## 0 <= l and r <= count, and with `reReversed` when l > r (TECH-PREFIX-03). `l == r` is the
  ## empty range, whose sum is 0.
  if l < 0 or r > p.count:
    return err(int, reOutOfBounds)
  if l > r:
    return err(int, reReversed)
  ok(p.sums[r] - p.sums[l], SpanError)

func differences*(xs: openArray[int]): seq[int] {.raises: [].} =
  ## The first element, then each element minus the one before: the changes between neighbours
  ## (TECH-PREFIX-04). The inverse of `fromDifferences`.
  for i, x in xs:
    result.add (if i == 0: x else: x - xs[i - 1])

func fromDifferences*(diffs: openArray[int]): seq[int] {.raises: [].} =
  ## The running sum of the changes: the values they describe (TECH-PREFIX-04).
  var running = 0
  for d in diffs:
    running += d
    result.add running

func applyRangeAdds*(n: int; adds: openArray[(int, int, int)]): Result[seq[int], SpanError] {.raises: [].} =
  ## Start from n zeros and add `delta` to every element of l ..< r for each (l, r, delta); the
  ## result is built from a difference array, so k updates cost O(n + k) and not O(n * k)
  ## (TECH-PREFIX-05). An update with a bad range fails the whole call with `reOutOfBounds`
  ## (outside 0 .. n; a negative `n` counts as outside) or `reReversed` (TECH-PREFIX-06).
  if n < 0:
    return err(seq[int], reOutOfBounds)
  var marks = newSeq[int](n + 1)         # one spare cell for a range that ends at n
  for (l, r, delta) in adds:
    if l < 0 or r > n:
      return err(seq[int], reOutOfBounds)
    if l > r:
      return err(seq[int], reReversed)
    marks[l] += delta
    marks[r] -= delta
  ok(fromDifferences(marks[0 ..< n]), SpanError)

func prefixOf2D*(grid: openArray[seq[int]]): Result[PrefixSums2D, SpanError] {.raises: [].} =
  ## The table of rectangle sums of a grid given as rows. Fails with `reRagged` when the rows differ
  ## in length (TECH-PREFIX-09). An empty grid, or a grid of empty rows, is fine.
  let cols = if grid.len == 0: 0 else: grid[0].len
  for row in grid:
    if row.len != cols:
      return err(PrefixSums2D, reRagged)
  let stride = cols + 1
  var sums = newSeq[int]((grid.len + 1) * stride)
  for i in 0 ..< grid.len:
    for j in 0 ..< cols:
      sums[(i + 1) * stride + j + 1] = grid[i][j] + sums[i * stride + j + 1] + sums[(i + 1) * stride + j] -
        sums[i * stride + j]
  ok(PrefixSums2D(rows: grid.len, cols: cols, sums: sums), SpanError)

func rowCount*(p: PrefixSums2D): int {.raises: [].} = p.rows

func columnCount*(p: PrefixSums2D): int {.raises: [].} = p.cols

func rectSum*(p: PrefixSums2D; row0, col0, row1, col1: int): Result[int, SpanError] {.raises: [].} =
  ## The sum of the cells in rows row0 ..< row1 and columns col0 ..< col1, from four table
  ## entries: whole block minus the two strips plus the corner counted twice (TECH-PREFIX-07).
  ## Fails like `rangeSum`, on either axis (TECH-PREFIX-08).
  if row0 < 0 or col0 < 0 or row1 > p.rows or col1 > p.cols:
    return err(int, reOutOfBounds)
  if row0 > row1 or col0 > col1:
    return err(int, reReversed)
  let stride = p.cols + 1
  ok(p.sums[row1 * stride + col1] - p.sums[row0 * stride + col1] - p.sums[row1 * stride + col0] +
    p.sums[row0 * stride + col0], SpanError)

## Prim's algorithm: grow one tree from a start vertex, always adding the cheapest edge that leaves it.
##
## Use it for the same job as `kruskal` (minimum spanning tree of an undirected weighted graph),
## typically when the graph is dense or given as adjacency lists. A binary heap of candidate edges
## gives O(E log V). When the graph is disconnected a new tree is started from the smallest
## unvisited vertex, so the result is a spanning forest. A directed graph is refused.

import std/[algorithm, heapqueue]
import nimcs/fp/result
import nimcs/algo/graph

func byWeight(a, b: Edge): int =
  result = cmp(a.weight, b.weight)
  if result == 0:
    result = cmp(a.source, b.source)
  if result == 0:
    result = cmp(a.target, b.target)

func prim*(g: Graph): Result[SpanningForest, GraphError] {.raises: [].} =
  ## A minimum spanning forest (GRAPH-PRIM-01). Fails with `geNotUndirected` for a directed graph.
  if g.isDirected:
    return err(SpanningForest, geNotUndirected)
  let n = g.vertexCount
  var inTree = newSeq[bool](n)
  var forest = SpanningForest()
  for start in 0 ..< n:
    if inTree[start]: continue
    inc forest.components
    inTree[start] = true
    var candidates = initHeapQueue[(int, int, int)]()    # (weight, from, to)
    for a in g.neighbors(start):
      candidates.push (a.weight, start, a.target)
    while candidates.len > 0:
      let (w, u, v) = candidates.pop
      if inTree[v]: continue
      inTree[v] = true
      forest.edges.add edge(min(u, v), max(u, v), w)
      forest.totalWeight += w
      for a in g.neighbors(v):
        if not inTree[a.target]:
          candidates.push (a.weight, v, a.target)
  forest.edges = sorted(forest.edges, byWeight)
  ok(forest, GraphError)

## Rabin–Karp search: slide a window over the text, keeping a polynomial hash of the window
## that is updated in O(1) when the window moves, and compare characters only where the hash of
## the window equals the hash of the pattern.
##
## The modulus is explicit and validated (`HashModulus` is a distinct type built by `hashModulus`; the name differs from `number_theory.Modulus` so both modules can be imported together). A hash
## match is only a candidate: every candidate is verified against the text, so the result never
## contains a false positive whatever the modulus (STR-RK-03); a small modulus only makes the
## search slower, never wrong. Use it for many same-length patterns (hash them once) or when a
## rolling fingerprint is wanted; for one pattern with guaranteed linear time use `kmp`.

import std/options

type
  HashModulus* = distinct int
  HashParams* = object
    base*: int
    modulus*: HashModulus

const maxHashModulus*: int = 2_147_483_647
  ## 2^31 - 1: `hash * base + c` stays below 2^62, so no step overflows a 64-bit `int`.

func hashModulus*(m: int): Option[HashModulus] {.raises: [].} =
  ## A modulus must lie in 2 .. `maxHashModulus` (STR-RK-05).
  if m < 2 or m > maxHashModulus: none(HashModulus) else: some(HashModulus(m))

func `==`*(a, b: HashModulus): bool {.borrow.}
func `$`*(m: HashModulus): string {.borrow.}

func hashModulusValue*(m: HashModulus): int {.raises: [].} = int(m)

func params*(base: int; m: HashModulus): Option[HashParams] {.raises: [].} =
  ## The base must be at least 2 and below the modulus (STR-RK-05).
  if base < 2 or base >= int(m): none(HashParams)
  else: some(HashParams(base: base, modulus: m))

func hashOf*(s: openArray[char]; p: HashParams): int {.raises: [].} =
  ## Polynomial hash of `s` (STR-RK-01).
  let m = int(p.modulus)
  for c in s:
    result = (result * p.base + ord(c)) mod m

func rollingHashes*(text: string; width: int; p: HashParams): seq[int] {.raises: [].} =
  ## The hash of every window `text[i ..< i + width]`, each obtained from the previous one in
  ## O(1) (STR-RK-01). Empty when `width` < 1 or larger than the text.
  result = @[]
  if width < 1 or width > text.len:
    return
  let m = int(p.modulus)
  var lead = 1                      # base^(width-1) mod m
  for _ in 1 ..< width:
    lead = lead * p.base mod m
  var h = hashOf(text.toOpenArray(0, width - 1), p)
  result.add h
  for i in width ..< text.len:
    let drop = ord(text[i - width]) * lead mod m
    h = ((h - drop + m) mod m * p.base + ord(text[i])) mod m
    result.add h

func rkFindAll*(text, pattern: string; p: HashParams): seq[int] {.raises: [].} =
  ## Start offsets of all occurrences of `pattern`, ascending; every hash candidate is verified
  ## (STR-RK-02, STR-RK-03). An empty pattern occurs at every offset 0 .. text.len (STR-RK-04).
  result = @[]
  let w = pattern.len
  if w == 0:
    for i in 0 .. text.len:
      result.add i
    return
  if w > text.len:
    return
  let target = hashOf(pattern, p)
  let hashes = rollingHashes(text, w, p)
  for i in 0 ..< hashes.len:
    if hashes[i] == target:
      var same = true
      for j in 0 ..< w:
        if text[i + j] != pattern[j]:
          same = false
          break
      if same:
        result.add i

func rkCandidates*(text, pattern: string; p: HashParams): seq[int] {.raises: [].} =
  ## Offsets whose window hash equals the pattern hash, before verification. A superset of
  ## `rkFindAll` (STR-RK-03); exposed so a test can show that collisions are filtered out.
  result = @[]
  let w = pattern.len
  if w == 0 or w > text.len:
    return
  let target = hashOf(pattern, p)
  let hashes = rollingHashes(text, w, p)
  for i in 0 ..< hashes.len:
    if hashes[i] == target:
      result.add i

## Radix sort and counting sort: sort by integer keys without comparing elements.
##
## Use them when keys are non-negative integers (or map to a small range): counting sort is
## O(n + k) for keys below k; LSD radix sort (least significant byte first, one stable counting
## pass per byte) is O(n * bytes). Both are stable and report bad keys as a `Result` error
## instead of guessing. Prefer a comparison sort for arbitrary keys. Inputs are never changed.

import nimcs/fp/result

const maxCountingBound* = 1 shl 24
  ## Largest `bound` that counting sort accepts: it allocates one counter per key value, so a
  ## caller-chosen bound would otherwise decide how much memory the routine takes.

type SortKeyError* = enum
  skNegative    ## a key below zero
  skOutOfRange  ## a key at or above the stated bound
  skBadBound    ## the bound is not positive
  skBoundTooLarge  ## the bound exceeds `maxCountingBound`

func countingSortBy*[T](xs: openArray[T]; bound: int;
    key: proc(x: T): int {.noSideEffect, raises: [].}): Result[seq[T], SortKeyError] {.raises: [].} =
  ## Stable sort by `key(x)`, which must lie in 0 ..< bound (SORT-RADIX-03, SORT-RADIX-04);
  ## a bound above `maxCountingBound` is refused (SORT-RADIX-06).
  if bound < 1:
    return err(seq[T], skBadBound)
  if bound > maxCountingBound:
    return err(seq[T], skBoundTooLarge)
  var counts = newSeq[int](bound + 1)
  for x in xs:
    let k = key(x)
    if k < 0:
      return err(seq[T], skNegative)
    if k >= bound:
      return err(seq[T], skOutOfRange)
    inc counts[k + 1]
  for k in 1 .. bound:
    counts[k] += counts[k - 1]            # counts[k] = number of elements with a smaller key
  var placed = newSeq[T](xs.len)
  for x in xs:
    let k = key(x)
    placed[counts[k]] = x
    inc counts[k]
  ok(placed, SortKeyError)

func countingSort*(xs: openArray[int]; bound: int): Result[seq[int], SortKeyError] {.raises: [].} =
  ## Sorts integers that lie in 0 ..< bound.
  countingSortBy(xs, bound, proc(x: int): int {.noSideEffect, raises: [].} = x)

func radixSort*(xs: openArray[int]): Result[seq[int], SortKeyError] {.raises: [].} =
  ## LSD radix sort, base 256, for non-negative integers (SORT-RADIX-01, SORT-RADIX-02).
  var biggest = 0
  for x in xs:
    if x < 0:
      return err(seq[int], skNegative)
    biggest = max(biggest, x)
  var current = @xs
  var shift = 0
  while shift < 63 and (biggest shr shift) > 0:
    var counts: array[257, int]
    for x in current:
      inc counts[((x shr shift) and 255) + 1]
    for d in 1 .. 256:
      counts[d] += counts[d - 1]
    var next = newSeq[int](current.len)
    for x in current:
      let d = (x shr shift) and 255
      next[counts[d]] = x
      inc counts[d]
    current = next
    shift += 8
  ok(current, SortKeyError)

## Sieve of Eratosthenes: all primes up to a limit by crossing off the multiples of each prime.
##
## Use it when many primality answers are needed below a known bound: O(n log log n) time and
## O(n) space for every prime up to n, against O(sqrt n) per query for trial division
## (`isPrimeTrial`). For a single huge number use a probabilistic test instead of either.
## A limit below 2 has no primes, so the answer is simply empty.

import std/options

const maxSieveLimit*: int = 100_000_000
  ## Largest limit accepted; the flag table has `limit + 1` bytes.

func sieveFlags*(limit: int): Option[seq[bool]] {.raises: [].} =
  ## `result[i]` is true exactly when `i` is prime, for 0 <= i <= limit (NUM-SIEVE-01). The table is
  ## empty when `limit` is negative; none when `limit` exceeds `maxSieveLimit` (NUM-SIEVE-04).
  if limit > maxSieveLimit:
    return none(seq[bool])
  if limit < 0:
    return some(newSeq[bool]())
  var flags = newSeq[bool](limit + 1)
  for i in 2 .. limit:
    flags[i] = true
  var p = 2
  while p <= limit div p:
    if flags[p]:
      var multiple = p * p
      while multiple <= limit:
        flags[multiple] = false
        multiple += p
    inc p
  some(flags)

func primesUpTo*(limit: int): Option[seq[int]] {.raises: [].} =
  ## All primes <= `limit`, ascending (NUM-SIEVE-02, NUM-SIEVE-03); none beyond `maxSieveLimit`.
  let flags = sieveFlags(limit)
  if flags.isNone:
    return none(seq[int])
  var primes: seq[int] = @[]
  for i in 0 ..< flags.get.len:
    if flags.get[i]:
      primes.add i
  some(primes)

func isPrimeTrial*(n: int): bool {.raises: [].} =
  ## Primality by trial division up to the square root; the reference the sieve is checked
  ## against (NUM-SIEVE-01).
  if n < 2:
    return false
  var d = 2
  while d <= n div d:
    if n mod d == 0:
      return false
    inc d
  true

## Suffix array by prefix doubling, and the LCP array by Kasai's method.
##
## The suffix array lists the start offsets of all suffixes of a string in sorted order. Prefix
## doubling ranks suffixes by their first 1, 2, 4, ... characters, sorting pairs of ranks until all
## ranks differ: O(n log^2 n) with a comparison sort. The LCP array stores, next to each suffix, the
## length of the prefix it shares with the previous suffix in sorted order; Kasai computes it in O(n)
## by never letting the shared length drop by more than one between neighbouring text positions.
##
## Use it for substring search by binary search, counting distinct substrings and longest
## repeated substring. For a single search `kmp` or `z_algorithm` is simpler; a suffix tree
## answers the same questions with a larger structure.

import std/[algorithm, options]

func suffixArray*(s: string): seq[int] {.raises: [].} =
  ## Offsets of the suffixes of `s` in ascending lexicographic order (STR-SA-01, STR-SA-02).
  let n = s.len
  result = newSeq[int](n)
  if n == 0:
    return
  var rank = newSeq[int](n)
  var next = newSeq[int](n)
  for i in 0 ..< n:
    result[i] = i
    rank[i] = ord(s[i])
  var k = 1
  while true:
    let width = k
    let ranks = rank
    func key(i: int): (int, int) {.raises: [].} =
      (ranks[i], if i + width < n: ranks[i + width] else: -1)
    result.sort(proc(a, b: int): int {.raises: [].} = cmp(key(a), key(b)))
    next[result[0]] = 0
    for i in 1 ..< n:
      next[result[i]] = next[result[i - 1]] + (if key(result[i - 1]) < key(result[i]): 1 else: 0)
    rank = next
    if rank[result[n - 1]] == n - 1:
      break
    k *= 2

func isSuffixArrayOf*(sa: openArray[int]; s: string): bool {.raises: [].} =
  ## True when `sa` is a permutation of 0 ..< s.len whose suffixes are strictly ascending
  ## (STR-SA-01). O(n): after the permutation check, the suffix at `sa[i-1]` is smaller than the
  ## one at `sa[i]` exactly when its first character is smaller, or the first characters are equal
  ## and the rest of the first suffix sits earlier in `sa` (an empty rest sits before everything).
  ## Used by `lcpArray` to reject a bad array, and by tests as the law.
  if sa.len != s.len:
    return false
  var rankOf = newSeq[int](s.len + 1)   # rankOf[s.len] = -1: the empty suffix
  rankOf[s.len] = -1
  var seen = newSeq[bool](s.len)
  for i, at in sa:
    if at < 0 or at >= s.len or seen[at]:
      return false
    seen[at] = true
    rankOf[at] = i
  for i in 1 ..< sa.len:
    let a = sa[i - 1]
    let b = sa[i]
    if s[a] > s[b] or (s[a] == s[b] and rankOf[a + 1] > rankOf[b + 1]):
      return false
  true

func lcpArray*(s: string; sa: openArray[int]): Option[seq[int]] {.raises: [].} =
  ## `result[i]` is the length of the longest common prefix of the suffixes at `sa[i - 1]` and
  ## `sa[i]`; `result[0]` is 0 (STR-SA-03). None when `sa` is not the suffix array of `s`
  ## (STR-SA-04).
  if not isSuffixArrayOf(sa, s):
    return none(seq[int])
  let n = s.len
  var rankOf = newSeq[int](n)
  for i in 0 ..< n:
    rankOf[sa[i]] = i
  var lcp = newSeq[int](n)
  var h = 0
  for i in 0 ..< n:
    if rankOf[i] > 0:
      let j = sa[rankOf[i] - 1]
      while i + h < n and j + h < n and s[i + h] == s[j + h]:
        inc h
      lcp[rankOf[i]] = h
      if h > 0:
        dec h
    else:
      h = 0
  some(lcp)

func countDistinctSubstrings*(s: string): int {.raises: [].} =
  ## Number of different non-empty substrings: all `n(n+1)/2` of them minus the repeated
  ## prefixes the LCP array counts (STR-SA-05).
  let n = s.len
  if n == 0:
    return 0
  let sa = suffixArray(s)
  let lcp = lcpArray(s, sa).get
  result = n * (n + 1) div 2
  for h in lcp:
    result -= h

## Topological sort (Kahn's algorithm): repeatedly take a vertex with no remaining incoming arc.
##
## Use it to order tasks, build steps or modules so that every dependency comes before what needs
## it. It runs in O((V + E) log V) because the ready vertices sit in a small priority queue; that
## makes the answer the lexicographically smallest valid order, which is deterministic. A cycle has
## no valid order: the error carries one cycle, so the caller can report it.

import std/heapqueue
import nimcs/fp/result
import nimcs/algo/graph

type TopoCycle* = object
  ## A directed cycle v0 -> v1 -> ... -> vk -> v0, listed once around (no repeated first vertex), starting at its smallest vertex.
  vertices*: seq[int]

func findCycle(g: Graph; removed: seq[bool]): seq[int] {.raises: [].} =
  ## Every vertex still present has an incoming arc from another present vertex; following those
  ## arcs backwards from any vertex must therefore close a loop.
  let n = g.vertexCount
  var pred = newSeq[int](n)
  for v in 0 ..< n:
    pred[v] = -1
  var start = -1
  for u in 0 ..< n:
    if removed[u]: continue
    if start < 0: start = u
    for a in g.neighbors(u):
      if not removed[a.target] and pred[a.target] < 0:
        pred[a.target] = u
  var seenAt = newSeq[int](n)
  for v in 0 ..< n:
    seenAt[v] = -1
  var walk: seq[int]
  var current = start
  while seenAt[current] < 0:
    seenAt[current] = walk.len
    walk.add current
    current = pred[current]
  for i in countdown(walk.len - 1, seenAt[current]):
    result.add walk[i]
  var at = 0
  for i, v in result:
    if v < result[at]: at = i
  # Start at the smallest vertex, so the report does not depend on where the walk began.
  result = result[at .. ^1] & result[0 ..< at]

func topoSort*(g: Graph): Result[seq[int], TopoCycle] {.raises: [].} =
  ## All vertices, each before every vertex it has an arc to (GRAPH-TOPO-01), the smallest
  ## vertex first whenever there is a choice (GRAPH-TOPO-03). If the graph has a cycle, the error
  ## holds a real cycle of the graph (GRAPH-TOPO-02). An undirected edge counts as a cycle of two.
  let n = g.vertexCount
  var indegree = newSeq[int](n)
  for u in 0 ..< n:
    for a in g.neighbors(u):
      inc indegree[a.target]
  var ready = initHeapQueue[int]()
  for v in 0 ..< n:
    if indegree[v] == 0:
      ready.push v
  var order: seq[int]
  var removed = newSeq[bool](n)
  while ready.len > 0:
    let u = ready.pop
    order.add u
    removed[u] = true
    for a in g.neighbors(u):
      dec indegree[a.target]
      if indegree[a.target] == 0:
        ready.push a.target
  if order.len == n:
    ok(order, TopoCycle)
  else:
    err(seq[int], TopoCycle(vertices: findCycle(g, removed)))

## Two pointers and sliding window: scan a sequence once with two moving indices.
##
## Use them when a property can only improve (or only worsen) as an index moves, so each index
## needs to move one way only and the total work is O(n) instead of O(n^2). Here: finding a pair
## of a sorted sequence that adds to a target (pointers from both ends), the longest window of
## non-negative numbers whose sum stays within a bound (window grows right, shrinks left), and the
## sums of all windows of one fixed size. Sums are `int`; the caller keeps them from overflowing.

import nimcs/fp/result

type
  PairError* = enum
    peNotSorted   ## the input is not in ascending order, so the method would give wrong answers
    peNoPair      ## no two elements add up to the target

  Window* = object
    ## `len` consecutive elements from index `start`; `len == 0` is the empty window.
    start*, len*: int

  WindowError* = enum
    weNegativeElement   ## the window method needs non-negative numbers: a negative one breaks "shrinking never raises the sum"
    weNegativeBound     ## no window, not even the empty one, has a sum below zero
    weBadSize           ## a fixed window size below one

func `==`*(a, b: Window): bool {.raises: [].} =
  a.start == b.start and a.len == b.len

func pairWithSum*(sortedXs: openArray[int]; target: int): Result[(int, int), PairError] {.raises: [].} =
  ## Indices (i, j), i < j, with `sortedXs[i] + sortedXs[j] == target`. When several pairs exist
  ## it is the one with the smallest i and, for that i, the largest j (TECH-TWOPTR-01).
  ## Fails with `peNotSorted` on an input that is not ascending (TECH-TWOPTR-03) and with
  ## `peNoPair` when there is none (TECH-TWOPTR-02).
  for k in 1 ..< sortedXs.len:
    if sortedXs[k - 1] > sortedXs[k]:
      return err((int, int), peNotSorted)
  var lo = 0
  var hi = sortedXs.len - 1
  while lo < hi:
    let sum = sortedXs[lo] + sortedXs[hi]
    if sum == target:
      return ok((lo, hi), PairError)
    if sum < target:
      inc lo               # no pair with this lo can be larger: even the biggest partner is too small
    else:
      dec hi               # no pair with this hi can be smaller: even the smallest partner is too big
  err((int, int), peNoPair)

func longestWindowAtMost*(xs: openArray[int]; bound: int): Result[Window, WindowError] {.raises: [].} =
  ## The longest run of consecutive elements whose sum is at most `bound`; the earliest one when
  ## several have the longest length (TECH-WINDOW-01). `xs` must be non-negative
  ## (TECH-WINDOW-03) and `bound` at least zero (TECH-WINDOW-04), so the empty window always
  ## qualifies and a result always exists.
  if bound < 0:
    return err(Window, weNegativeBound)
  for x in xs:
    if x < 0:
      return err(Window, weNegativeElement)
  var best = Window(start: 0, len: 0)
  var left = 0
  var sum = 0
  for right in 0 ..< xs.len:
    sum += xs[right]
    while sum > bound:
      sum -= xs[left]
      inc left
    if right - left + 1 > best.len:
      best = Window(start: left, len: right - left + 1)
  ok(best, WindowError)

func windowSums*(xs: openArray[int]; size: int): Result[seq[int], WindowError] {.raises: [].} =
  ## The sum of every run of `size` consecutive elements, left to right: `xs.len - size + 1` sums,
  ## none when `size` exceeds the length. Each step adds the entering element and drops the
  ## leaving one instead of re-adding the window (TECH-WINDOW-02). Fails when `size` < 1 (TECH-WINDOW-05).
  if size < 1:
    return err(seq[int], weBadSize)
  var sums: seq[int]
  var current = 0
  for i in 0 ..< xs.len:
    current += xs[i]
    if i >= size:
      current -= xs[i - size]
    if i >= size - 1:
      sums.add current
  ok(sums, WindowError)

## Persistent AVL tree: a self-balancing ordered set.
##
## A binary search tree in which, at every node, the heights of the two subtrees differ by at most
## one. Each node stores its height; after an insert or delete, `balance` restores the rule on the
## way back up the path with one single or double rotation. The rule keeps the height below
## 1.4405 log2(n + 2), so `insert`, `delete` and `contains` are O(log n) worst case. Nodes are
## immutable `ref`s, so an update copies only the path it walks and the old tree stays valid.
## Use it when lookups dominate (AVL trees are a little more rigidly balanced than red-black
## trees); use `rb_tree` for a map with the same guarantees. The item type needs `<`; two items
## are equal when neither is smaller.

import std/options

type
  Node[T] = ref object
    elem: T
    height: int
    left, right: Node[T]
  AvlTree*[T] = object
    root: Node[T]
    size: int

func emptyAvl*[T](): AvlTree[T] {.raises: [].} =
  AvlTree[T]()

func len*[T](t: AvlTree[T]): int {.raises: [].} =
  t.size

func isEmpty*[T](t: AvlTree[T]): bool {.raises: [].} =
  t.root.isNil

func heightOf[T](n: Node[T]): int =
  if n.isNil: 0 else: n.height

func mk[T](x: T; l, r: Node[T]): Node[T] =
  Node[T](elem: x, height: max(heightOf(l), heightOf(r)) + 1, left: l, right: r)

func balance[T](x: T; l, r: Node[T]): Node[T] =
  ## A node with item `x` and subtrees `l`, `r` that differ in height by at most two (what one
  ## insert or delete can cause); rotates when they differ by two.
  if heightOf(l) > heightOf(r) + 1:
    if heightOf(l.left) >= heightOf(l.right):
      mk(l.elem, l.left, mk(x, l.right, r))                              # single right rotation
    else:
      let m = l.right
      mk(m.elem, mk(l.elem, l.left, m.left), mk(x, m.right, r))          # left-right double rotation
  elif heightOf(r) > heightOf(l) + 1:
    if heightOf(r.right) >= heightOf(r.left):
      mk(r.elem, mk(x, l, r.left), r.right)                              # single left rotation
    else:
      let m = r.left
      mk(m.elem, mk(x, l, m.left), mk(r.elem, m.right, r.right))         # right-left double rotation
  else:
    mk(x, l, r)

func contains*[T](t: AvlTree[T]; x: T): bool {.raises: [].} =
  var n = t.root
  while not n.isNil:
    if x < n.elem: n = n.left
    elif n.elem < x: n = n.right
    else: return true
  false

func insertNode[T](n: Node[T]; x: T): Node[T] =
  if n.isNil: mk(x, nil, nil)
  elif x < n.elem: balance(n.elem, insertNode(n.left, x), n.right)
  elif n.elem < x: balance(n.elem, n.left, insertNode(n.right, x))
  else: n

func insert*[T](t: AvlTree[T]; x: T): AvlTree[T] {.raises: [].} =
  ## The tree with `x`; inserting an item that is already there returns the same tree.
  if t.contains(x): t
  else: AvlTree[T](root: insertNode(t.root, x), size: t.size + 1)

func removeMin[T](n: Node[T]): tuple[smallest: T, rest: Node[T]] =
  if n.left.isNil: (n.elem, n.right)
  else:
    let (m, l) = removeMin(n.left)
    (m, balance(n.elem, l, n.right))

func deleteNode[T](n: Node[T]; x: T): Node[T] =
  if n.isNil: n
  elif x < n.elem: balance(n.elem, deleteNode(n.left, x), n.right)
  elif n.elem < x: balance(n.elem, n.left, deleteNode(n.right, x))
  elif n.left.isNil: n.right
  elif n.right.isNil: n.left
  else:
    let (m, r) = removeMin(n.right)
    balance(m, n.left, r)

func delete*[T](t: AvlTree[T]; x: T): AvlTree[T] {.raises: [].} =
  ## The tree without `x`; a missing item leaves the tree as it was.
  if not t.contains(x): t
  else: AvlTree[T](root: deleteNode(t.root, x), size: t.size - 1)

func height*[T](t: AvlTree[T]): int {.raises: [].} =
  ## Number of nodes on the longest root-to-leaf path; 0 for the empty tree.
  heightOf(t.root)

func smallest*[T](t: AvlTree[T]): Option[T] {.raises: [].} =
  var n = t.root
  if n.isNil: return none(T)
  while not n.left.isNil:
    n = n.left
  some(n.elem)

func toSeq*[T](t: AvlTree[T]): seq[T] {.raises: [].} =
  ## The items in ascending order.
  func walk(n: Node[T]; acc: var seq[T]) =
    if not n.isNil:
      walk(n.left, acc)
      acc.add n.elem
      walk(n.right, acc)
  walk(t.root, result)

func fromSeq*[T](items: openArray[T]): AvlTree[T] {.raises: [].} =
  result = emptyAvl[T]()
  for x in items:
    result = result.insert(x)

func invariantsHold*[T](t: AvlTree[T]): bool {.raises: [].} =
  ## Search order, correct stored heights, and the AVL rule (subtree heights differ by at most
  ## one) at every node; `len` counts the nodes.
  func ok(n: Node[T]; lo, hi: Option[T]): bool =
    if n.isNil: true
    else:
      (lo.isNone or lo.get < n.elem) and (hi.isNone or n.elem < hi.get) and
        n.height == max(heightOf(n.left), heightOf(n.right)) + 1 and
        abs(heightOf(n.left) - heightOf(n.right)) <= 1 and
        ok(n.left, lo, some(n.elem)) and ok(n.right, some(n.elem), hi)
  func count(n: Node[T]): int =
    if n.isNil: 0 else: 1 + count(n.left) + count(n.right)
  ok(t.root, none(T), none(T)) and count(t.root) == t.size

## B-tree: a persistent ordered set whose nodes hold many keys.
##
## Every node stores between `t - 1` and `2t - 1` sorted keys (`t` is the minimum degree; the root
## may hold fewer), an internal node has one more child than keys, and all leaves are at the same
## depth. A search therefore reads O(log_t n) nodes, and each node is a contiguous run of keys:
## that is what pays off when a node is a disk page or a few cache lines. Insertion splits a
## node that grows past `2t - 1` keys and pushes the median up; only the nodes on one
## root-to-leaf path are copied, so the old tree stays valid. The set is insert-only here
## (deletion needs borrow and merge cases that add length without adding a new idea); use
## `rb_tree` for a binary balanced set, `std/sets` when order does not matter.

import std/options

type
  Node[T] = ref object
    ## Immutable once built. `kids` is empty in a leaf, otherwise `keys.len + 1` long.
    keys: seq[T]
    kids: seq[Node[T]]
  BTree*[T] = object
    degree: int
    root: Node[T]
    size: int
  Grown[T] = object
    ## What inserting into a subtree produced: one node, or two nodes and the key between them.
    case split: bool
    of false:
      node: Node[T]
    of true:
      left, right: Node[T]
      mid: T

func newBTree*[T](minDegree: int): Option[BTree[T]] {.raises: [].} =
  ## An empty tree; none when `minDegree` is below 2 (degree 1 would allow empty nodes).
  if minDegree < 2: none(BTree[T])
  else: some(BTree[T](degree: minDegree))

func minDegree*[T](t: BTree[T]): int {.raises: [].} =
  t.degree

func len*[T](t: BTree[T]): int {.raises: [].} =
  t.size

func isEmpty*[T](t: BTree[T]): bool {.raises: [].} =
  t.size == 0

func slot[T](keys: seq[T]; x: T): int =
  ## Number of keys that are smaller than `x` (binary search).
  var lo = 0
  var hi = keys.len
  while lo < hi:
    let mid = (lo + hi) div 2
    if keys[mid] < x: lo = mid + 1
    else: hi = mid
  lo

func isKeyAt[T](keys: seq[T]; i: int; x: T): bool =
  ## True when `keys[i]` exists and equals `x` (equality from `<` only).
  i < keys.len and not (x < keys[i])

func containsNode[T](n: Node[T]; x: T): bool =
  var cur = n
  while not cur.isNil:
    let i = slot(cur.keys, x)
    if isKeyAt(cur.keys, i, x): return true
    cur = if cur.kids.len == 0: nil else: cur.kids[i]
  false

func contains*[T](t: BTree[T]; x: T): bool {.raises: [].} =
  containsNode(t.root, x)

func settle[T](keys: seq[T]; kids: seq[Node[T]]; degree: int): Grown[T] =
  ## A node from `keys` and `kids`, split at the median when it holds more than 2t - 1 keys.
  if keys.len <= 2 * degree - 1:
    Grown[T](split: false, node: Node[T](keys: keys, kids: kids))
  else:
    let m = degree - 1
    let leftKids = if kids.len == 0: newSeq[Node[T]]() else: kids[0 .. m]
    let rightKids = if kids.len == 0: newSeq[Node[T]]() else: kids[m + 1 .. ^1]
    Grown[T](split: true,
      left: Node[T](keys: keys[0 ..< m], kids: leftKids),
      mid: keys[m],
      right: Node[T](keys: keys[m + 1 .. ^1], kids: rightKids))

func insertNode[T](n: Node[T]; x: T; degree: int): Grown[T] =
  ## `x` is known to be absent from the subtree.
  let i = slot(n.keys, x)
  if n.kids.len == 0:
    var keys = n.keys
    keys.insert(x, i)
    settle(keys, n.kids, degree)
  else:
    let g = insertNode(n.kids[i], x, degree)
    var keys = n.keys
    var kids = n.kids
    if g.split:
      keys.insert(g.mid, i)
      kids[i] = g.left
      kids.insert(g.right, i + 1)
    else:
      kids[i] = g.node
    settle(keys, kids, degree)

func insert*[T](t: BTree[T]; x: T): BTree[T] {.raises: [].} =
  ## The tree with `x` added; the same tree when `x` is already a member (idempotent).
  if t.contains(x): return t
  if t.root.isNil:
    return BTree[T](degree: t.degree, root: Node[T](keys: @[x]), size: 1)
  let g = insertNode(t.root, x, t.degree)
  let root =
    if g.split: Node[T](keys: @[g.mid], kids: @[g.left, g.right])
    else: g.node
  BTree[T](degree: t.degree, root: root, size: t.size + 1)

func fromSeq*[T](minDegree: int; items: openArray[T]): Option[BTree[T]] {.raises: [].} =
  ## A tree of the distinct items; none when `minDegree` is below 2.
  let empty = newBTree[T](minDegree)
  if empty.isNone: return empty
  var t = empty.get
  for x in items:
    t = t.insert(x)
  some(t)

func collect[T](n: Node[T]; acc: var seq[T]) =
  if n.isNil: return
  for i in 0 ..< n.keys.len:
    if n.kids.len > 0: collect(n.kids[i], acc)
    acc.add n.keys[i]
  if n.kids.len > 0: collect(n.kids[n.keys.len], acc)

func toSortedSeq*[T](t: BTree[T]): seq[T] {.raises: [].} =
  ## The members in ascending order.
  collect(t.root, result)

iterator items*[T](t: BTree[T]): T {.raises: [].} =
  ## Members in ascending order.
  for x in t.toSortedSeq:
    yield x

func height*[T](t: BTree[T]): int {.raises: [].} =
  ## Number of levels (0 for the empty tree, 1 for a single leaf).
  var n = t.root
  while not n.isNil:
    inc result
    n = if n.kids.len == 0: nil else: n.kids[0]

func invariantsHold*[T](t: BTree[T]): bool {.raises: [].} =
  ## Key counts per node, child counts, equal leaf depth and strictly ascending in-order keys.
  let maxKeys = 2 * t.degree - 1
  let minKeys = t.degree - 1
  var leafDepth = -1
  func ok(n: Node[T]; depth: int; isRoot: bool; leafDepth: var int): bool =
    if n.keys.len > maxKeys or n.keys.len < (if isRoot: 1 else: minKeys): return false
    if n.kids.len == 0:
      if leafDepth < 0: leafDepth = depth
      return leafDepth == depth
    if n.kids.len != n.keys.len + 1: return false
    for k in n.kids:
      if not ok(k, depth + 1, false, leafDepth): return false
    true
  if t.root.isNil: return t.size == 0
  let order = t.toSortedSeq
  if order.len != t.size: return false
  for i in 1 ..< order.len:
    if not (order[i - 1] < order[i]): return false
  ok(t.root, 1, true, leafDepth)

## Binomial heap: a persistent min-heap whose merge works like binary addition.
##
## A heap is a list of binomial trees in increasing rank, at most one tree per rank, exactly like
## the set bits of n. A tree of rank r has 2^r nodes; linking two trees of rank r gives one of
## rank r+1 (a carry). `insert`, `merge` and `deleteMin` are O(log n) worst case; `insert` is O(1)
## amortized only for ephemeral use (a run of inserts where each version is used once), because
## a persistent program can repeat the longest carry chain from one old version. Use it when you
## want the arithmetic analogy to guide the reasoning and a worst-case O(log n) bound for all
## three operations.

import std/options
import nimcs/ds/cons_list

type
  Tree[T] = ref object
    rank: int
    elem: T
    children: ConsList[Tree[T]]   ## ranks decreasing: rank-1 first, rank 0 last
  BinomialHeap*[T] = object
    trees: ConsList[Tree[T]]      ## ranks increasing, all different
    size: int

func emptyHeap*[T](): BinomialHeap[T] {.raises: [].} =
  BinomialHeap[T]()

func len*[T](h: BinomialHeap[T]): int {.raises: [].} =
  h.size

func isEmpty*[T](h: BinomialHeap[T]): bool {.raises: [].} =
  h.trees.isEmpty

func link[T](a, b: Tree[T]): Tree[T] =
  ## Same rank in, rank + 1 out; the smaller root stays on top.
  if b.elem < a.elem: Tree[T](rank: b.rank + 1, elem: b.elem, children: b.children.cons(a))
  else: Tree[T](rank: a.rank + 1, elem: a.elem, children: a.children.cons(b))

func rankOf[T](ts: ConsList[Tree[T]]): int =
  ts.head.get.rank

func insertTree[T](t: Tree[T]; ts: ConsList[Tree[T]]): ConsList[Tree[T]] =
  if ts.isEmpty or t.rank < rankOf(ts): ts.cons(t)
  else: insertTree(link(t, ts.head.get), ts.tail)

func mergeTrees[T](a, b: ConsList[Tree[T]]): ConsList[Tree[T]] =
  if a.isEmpty: b
  elif b.isEmpty: a
  else:
    let ta = a.head.get
    let tb = b.head.get
    if ta.rank < tb.rank: mergeTrees(a.tail, b).cons(ta)
    elif tb.rank < ta.rank: mergeTrees(a, b.tail).cons(tb)
    else: insertTree(link(ta, tb), mergeTrees(a.tail, b.tail))

func merge*[T](a, b: BinomialHeap[T]): BinomialHeap[T] {.raises: [].} =
  BinomialHeap[T](trees: mergeTrees(a.trees, b.trees), size: a.size + b.size)

func insert*[T](h: BinomialHeap[T]; x: T): BinomialHeap[T] {.raises: [].} =
  BinomialHeap[T](trees: insertTree(Tree[T](rank: 0, elem: x), h.trees), size: h.size + 1)

func minTree[T](ts: ConsList[Tree[T]]): Tree[T] =
  ## `ts` is not empty.
  var best = ts.head.get
  for t in items(ts):
    if t.elem < best.elem: best = t
  best

func findMin*[T](h: BinomialHeap[T]): Option[T] {.raises: [].} =
  if h.isEmpty: none(T) else: some(minTree(h.trees).elem)

func deleteMin*[T](h: BinomialHeap[T]): BinomialHeap[T] {.raises: [].} =
  if h.isEmpty: h
  else:
    let best = minTree(h.trees)
    var others = emptyList[Tree[T]]()
    var removed = false
    for t in items(h.trees):
      if not removed and t == best:   # reference identity: remove exactly this tree
        removed = true
      else:
        others = others.cons(t)
    BinomialHeap[T](trees: mergeTrees(others.reverse, best.children.reverse), size: h.size - 1)

func fromSeq*[T](items: openArray[T]): BinomialHeap[T] {.raises: [].} =
  var h = emptyHeap[T]()
  for x in items:
    h = h.insert(x)
  h

func toSortedSeq*[T](h: BinomialHeap[T]): seq[T] {.raises: [].} =
  var cur = h
  while not cur.isEmpty:
    result.add minTree(cur.trees).elem
    cur = cur.deleteMin

func rankProfile*[T](h: BinomialHeap[T]): seq[int] {.raises: [].} =
  ## The ranks present, increasing. They are the positions of the 1 bits of `len`.
  for t in items(h.trees):
    result.add t.rank

func invariantsHold*[T](h: BinomialHeap[T]): bool {.raises: [].} =
  ## Strictly increasing ranks, each tree heap-ordered with 2^rank nodes.
  func count(t: Tree[T]): int =
    result = 1
    for c in items(t.children):
      result += count(c)
  func ordered(t: Tree[T]): bool =
    result = true
    for c in items(t.children):
      if c.elem < t.elem or not ordered(c): return false
  var prev = -1
  for t in items(h.trees):
    if t.rank <= prev or count(t) != (1 shl t.rank) or not ordered(t): return false
    prev = t.rank
  true

## Bit vector: a fixed-size set of the integers 0 ..< n, one bit each, packed into 64-bit words.
##
## The size is part of the value and never changes. Membership, `count` (population count),
## `rank` (how many members are below an index) and `select` (the index of the k-th member) are
## word operations, so a set of n small integers takes n/8 bytes and set algebra (union,
## intersection, difference, complement) runs 64 elements at a time. A `BitVector` is a value:
## `withBit` and `withoutBit` return a new vector and copy n/64 words. Use it when the universe is
## a known range of small integers (flags, visited marks, sieve results, dense id sets). Use
## `std/sets` for sparse or non-integer members, and `bloom_filter` when memory must stay below
## one bit per possible member and a false positive is acceptable (a bit vector never lies).

import std/[options, bitops]

type
  BitVector* = object
    words: seq[uint64]
    nbits: int           ## bits at index >= nbits in the last word are always 0

func wordCount(n: int): int =
  (n + 63) div 64

func bitVector*(size: int): Option[BitVector] {.raises: [].} =
  ## A vector of `size` zero bits; none when `size` is negative.
  if size < 0: none(BitVector)
  else: some(BitVector(words: newSeq[uint64](wordCount(size)), nbits: size))

func len*(v: BitVector): int {.raises: [].} =
  ## Number of bits (the universe size), not the number of set bits; see `count`.
  v.nbits

func test*(v: BitVector; i: int): bool {.raises: [].} =
  ## True when bit `i` is set. An index outside 0 ..< len is not a member, as in a set.
  if i < 0 or i >= v.nbits: false
  else: ((v.words[i div 64] shr (i mod 64)) and 1'u64) == 1'u64

func withBit*(v: BitVector; i: int): Option[BitVector] {.raises: [].} =
  ## `v` with bit `i` set (idempotent); none when `i` is outside 0 ..< len.
  if i < 0 or i >= v.nbits: return none(BitVector)
  var words = v.words
  words[i div 64] = words[i div 64] or (1'u64 shl (i mod 64))
  some(BitVector(words: words, nbits: v.nbits))

func withoutBit*(v: BitVector; i: int): Option[BitVector] {.raises: [].} =
  ## `v` with bit `i` cleared (idempotent); none when `i` is outside 0 ..< len.
  if i < 0 or i >= v.nbits: return none(BitVector)
  var words = v.words
  words[i div 64] = words[i div 64] and not (1'u64 shl (i mod 64))
  some(BitVector(words: words, nbits: v.nbits))

func fromIndices*(size: int; indices: openArray[int]): Option[BitVector] {.raises: [].} =
  ## The vector of `size` bits with exactly `indices` set (duplicates allowed); none when `size` is
  ## negative or an index is out of range.
  let empty = bitVector(size)
  if empty.isNone: return empty
  var words = empty.get.words
  for i in indices:
    if i < 0 or i >= size: return none(BitVector)
    words[i div 64] = words[i div 64] or (1'u64 shl (i mod 64))
  some(BitVector(words: words, nbits: size))

func count*(v: BitVector): int {.raises: [].} =
  ## Number of set bits (population count).
  for w in v.words:
    result += popcount(w)

func rank*(v: BitVector; i: int): Option[int] {.raises: [].} =
  ## Number of set bits among indices 0 ..< i; none unless 0 <= i <= len.
  if i < 0 or i > v.nbits: return none(int)
  var total = 0
  for w in 0 ..< i div 64:
    total += popcount(v.words[w])
  let rest = i mod 64
  if rest > 0:
    total += popcount(v.words[i div 64] and ((1'u64 shl rest) - 1'u64))
  some(total)

func select*(v: BitVector; k: int): Option[int] {.raises: [].} =
  ## Index of the set bit with `k` set bits below it (k = 0 is the smallest member); none when
  ## `k` is negative or at least `count`. `rank(select(k)) == k`.
  if k < 0: return none(int)
  var remaining = k
  for wi in 0 ..< v.words.len:
    let c = popcount(v.words[wi])
    if remaining < c:
      var w = v.words[wi]
      for _ in 0 ..< remaining:
        w = w and (w - 1'u64)           # clear the lowest set bit
      return some(wi * 64 + countTrailingZeroBits(w))
    remaining -= c
  none(int)

func toIndices*(v: BitVector): seq[int] {.raises: [].} =
  ## The set bits as ascending indices.
  for wi in 0 ..< v.words.len:
    var w = v.words[wi]
    while w != 0'u64:
      result.add wi * 64 + countTrailingZeroBits(w)
      w = w and (w - 1'u64)

func combine(a, b: BitVector; f: proc(x, y: uint64): uint64 {.noSideEffect, raises: [].}): Option[BitVector] =
  if a.nbits != b.nbits: return none(BitVector)
  var words = newSeq[uint64](a.words.len)
  for i in 0 ..< words.len:
    words[i] = f(a.words[i], b.words[i])
  some(BitVector(words: words, nbits: a.nbits))

func union*(a, b: BitVector): Option[BitVector] {.raises: [].} =
  ## Bits set in `a` or `b`; none when the sizes differ.
  combine(a, b, proc(x, y: uint64): uint64 = x or y)

func intersection*(a, b: BitVector): Option[BitVector] {.raises: [].} =
  ## Bits set in both; none when the sizes differ.
  combine(a, b, proc(x, y: uint64): uint64 = x and y)

func difference*(a, b: BitVector): Option[BitVector] {.raises: [].} =
  ## Bits set in `a` and not in `b`; none when the sizes differ.
  combine(a, b, proc(x, y: uint64): uint64 = x and not y)

func complement*(v: BitVector): BitVector {.raises: [].} =
  ## Every bit flipped within 0 ..< len (bits past the end stay 0).
  var words = newSeq[uint64](v.words.len)
  for i in 0 ..< words.len:
    words[i] = not v.words[i]
  let rest = v.nbits mod 64
  if rest > 0:
    words[^1] = words[^1] and ((1'u64 shl rest) - 1'u64)
  BitVector(words: words, nbits: v.nbits)

func invariantsHold*(v: BitVector): bool {.raises: [].} =
  ## Word count matches the size and no bit past the end is set.
  if v.nbits < 0 or v.words.len != wordCount(v.nbits): return false
  let rest = v.nbits mod 64
  rest == 0 or (v.words[^1] shr rest) == 0'u64

## Bloom filter with value semantics: a compact set that may say "yes" for an absent key but never
## says "no" for a present one.
##
## `add` returns a new filter (the bit array is copied, O(bits / 64)); the old filter is unchanged.
## The `k` bit positions of a key come from two base hashes as `h1 + i * h2` (double hashing), so
## only two hash computations are needed however large `k` is. Both hashes come from `std/hashes`
## on `(salt, key)` pairs and are deterministic; the stride is chosen coprime to the bit count so a
## key sets `min(hashCount, bits)` distinct bits for every bit count. Use it to skip expensive
## lookups for keys that are certainly absent; do not use it when a false positive is unacceptable
## or when you must delete.

import std/[hashes, math, bitops]
import nimcs/fp/result

type
  BloomError* = enum
    beNoBits, beNoHashes, beShapeMismatch
  BloomFilter* = object
    words: seq[uint64]
    bitCount: int
    hashCount: int
    adds: int

func bloomFilter*(bitCount, hashCount: int): Result[BloomFilter, BloomError] {.raises: [].} =
  ## An empty filter of `bitCount` bits using `hashCount` positions per key.
  if bitCount < 1: err(BloomFilter, beNoBits)
  elif hashCount < 1: err(BloomFilter, beNoHashes)
  else:
    ok(BloomFilter(words: newSeq[uint64]((bitCount + 63) div 64), bitCount: bitCount,
      hashCount: hashCount), BloomError)

func bits*(f: BloomFilter): int {.raises: [].} =
  f.bitCount

func hashes*(f: BloomFilter): int {.raises: [].} =
  f.hashCount

func added*(f: BloomFilter): int {.raises: [].} =
  ## Number of `add` calls (repeated keys count each time).
  f.adds

func setBits*(f: BloomFilter): int {.raises: [].} =
  ## Number of bits that are 1.
  for w in f.words:
    result += countSetBits(w)

type Probe = object
  start, stride: int      ## position i is (start + i * stride) mod bitCount

func probeOf[K](f: BloomFilter; key: K): Probe =
  ## The stride is made coprime to the bit count, so the first min(hashCount, bitCount) positions
  ## of a key are distinct for any bit count (an odd stride only guarantees that for powers of two).
  let m = f.bitCount
  var stride = int(uint64(hash((2, key))) mod uint64(m))
  if stride == 0: stride = 1
  while gcd(stride, m) != 1:
    stride = stride mod m + 1          # m > 1 here: gcd(x, 1) is 1, so the loop never runs for m == 1
  Probe(start: int(uint64(hash((1, key))) mod uint64(m)), stride: stride)

func position(f: BloomFilter; p: Probe; i: int): int =
  (p.start + i * p.stride) mod f.bitCount

func add*[K](f: BloomFilter; key: K): BloomFilter {.raises: [].} =
  var words = f.words
  let probe = f.probeOf(key)
  for i in 0 ..< f.hashCount:
    let p = f.position(probe, i)
    words[p div 64] = words[p div 64] or (1'u64 shl (p mod 64))
  BloomFilter(words: words, bitCount: f.bitCount, hashCount: f.hashCount, adds: f.adds + 1)

func mightContain*[K](f: BloomFilter; key: K): bool {.raises: [].} =
  ## False means certainly absent; true means present or a false positive.
  let probe = f.probeOf(key)
  for i in 0 ..< f.hashCount:
    let p = f.position(probe, i)
    if (f.words[p div 64] and (1'u64 shl (p mod 64))) == 0: return false
  true

func merge*(a, b: BloomFilter): Result[BloomFilter, BloomError] {.raises: [].} =
  ## The filter of the union of both key sets; the shapes (bits and hashes) must be equal.
  if a.bitCount != b.bitCount or a.hashCount != b.hashCount:
    err(BloomFilter, beShapeMismatch)
  else:
    var words = a.words
    for i in 0 ..< words.len:
      words[i] = words[i] or b.words[i]
    ok(BloomFilter(words: words, bitCount: a.bitCount, hashCount: a.hashCount,
      adds: a.adds + b.adds), BloomError)

func sameBits*(a, b: BloomFilter): bool {.raises: [].} =
  ## Equal shape and equal bit array (the `added` counters are ignored).
  a.bitCount == b.bitCount and a.hashCount == b.hashCount and a.words == b.words

## Unbalanced binary search tree, persistent: a set of ordered items.
##
## Every node holds one item, with smaller items in the left subtree and larger ones in the right.
## Nodes are immutable `ref`s; `insert` and `delete` copy only the path they walk and share the rest
## with the old tree, which stays valid. There is no rebalancing, so the cost of an operation is
## the depth of the tree: O(log n) for items that arrive in random order, O(n) when they arrive
## sorted (the tree degenerates into a list). Use it to learn the ordered-tree operations and the
## three depth-first traversals; use `rb_tree` or `avl_tree` when the input order is not under
## your control. The item type needs `<`; two items are equal when neither is smaller.

import std/options

type
  NodeObj[T] = object
    elem: T
    left, right: Node[T]
  Node[T] = ref NodeObj[T]
  Bst*[T] = object
    root: Node[T]
    size: int

proc `=destroy`[T](n: var NodeObj[T]) =
  ## A degenerate tree is as deep as it has items, so the default destructor would recurse once
  ## per node. A work list frees the nodes this tree owns alone; a node still reachable from
  ## another tree (`isUniqueRef` is false) is left to its last owner.
  var pending: seq[Node[T]]
  if not n.left.isNil: pending.add move(n.left)
  if not n.right.isNil: pending.add move(n.right)
  while pending.len > 0:
    let c = pending.pop
    if isUniqueRef(c):
      if not c.left.isNil: pending.add move(c.left)
      if not c.right.isNil: pending.add move(c.right)
  reset(n.elem)

func emptyBst*[T](): Bst[T] {.raises: [].} =
  Bst[T]()

func len*[T](t: Bst[T]): int {.raises: [].} =
  t.size

func isEmpty*[T](t: Bst[T]): bool {.raises: [].} =
  t.root.isNil

func contains*[T](t: Bst[T]; x: T): bool {.raises: [].} =
  var n = t.root
  while not n.isNil:
    if x < n.elem: n = n.left
    elif n.elem < x: n = n.right
    else: return true
  false

func insertNode[T](n: Node[T]; x: T): Node[T] =
  if n.isNil: Node[T](elem: x)
  elif x < n.elem: Node[T](elem: n.elem, left: insertNode(n.left, x), right: n.right)
  elif n.elem < x: Node[T](elem: n.elem, left: n.left, right: insertNode(n.right, x))
  else: n

func insert*[T](t: Bst[T]; x: T): Bst[T] {.raises: [].} =
  ## The tree with `x`; inserting an item that is already there returns the same tree.
  if t.contains(x): t
  else: Bst[T](root: insertNode(t.root, x), size: t.size + 1)

func removeMin[T](n: Node[T]): tuple[smallest: T, rest: Node[T]] =
  ## The smallest item of a non-empty subtree and the subtree without it.
  if n.left.isNil: (n.elem, n.right)
  else:
    let (m, l) = removeMin(n.left)
    (m, Node[T](elem: n.elem, left: l, right: n.right))

func deleteNode[T](n: Node[T]; x: T): Node[T] =
  if n.isNil: n
  elif x < n.elem: Node[T](elem: n.elem, left: deleteNode(n.left, x), right: n.right)
  elif n.elem < x: Node[T](elem: n.elem, left: n.left, right: deleteNode(n.right, x))
  elif n.left.isNil: n.right
  elif n.right.isNil: n.left
  else:
    let (m, r) = removeMin(n.right)       # the in-order successor takes the deleted node's place
    Node[T](elem: m, left: n.left, right: r)

func delete*[T](t: Bst[T]; x: T): Bst[T] {.raises: [].} =
  ## The tree without `x`; a missing item leaves the tree as it was.
  if not t.contains(x): t
  else: Bst[T](root: deleteNode(t.root, x), size: t.size - 1)

func smallest*[T](t: Bst[T]): Option[T] {.raises: [].} =
  var n = t.root
  if n.isNil: return none(T)
  while not n.left.isNil:
    n = n.left
  some(n.elem)

func largest*[T](t: Bst[T]): Option[T] {.raises: [].} =
  var n = t.root
  if n.isNil: return none(T)
  while not n.right.isNil:
    n = n.right
  some(n.elem)

func height*[T](t: Bst[T]): int {.raises: [].} =
  ## Number of nodes on the longest root-to-leaf path; 0 for the empty tree.
  func go(n: Node[T]): int =
    if n.isNil: 0 else: 1 + max(go(n.left), go(n.right))
  go(t.root)

func inOrder*[T](t: Bst[T]): seq[T] {.raises: [].} =
  ## Left subtree, node, right subtree: the items in ascending order.
  func walk(n: Node[T]; acc: var seq[T]) =
    if not n.isNil:
      walk(n.left, acc)
      acc.add n.elem
      walk(n.right, acc)
  walk(t.root, result)

func preOrder*[T](t: Bst[T]): seq[T] {.raises: [].} =
  ## Node, left subtree, right subtree: re-inserting this list in order rebuilds the same shape.
  func walk(n: Node[T]; acc: var seq[T]) =
    if not n.isNil:
      acc.add n.elem
      walk(n.left, acc)
      walk(n.right, acc)
  walk(t.root, result)

func postOrder*[T](t: Bst[T]): seq[T] {.raises: [].} =
  ## Left subtree, right subtree, node: every node comes after its descendants.
  func walk(n: Node[T]; acc: var seq[T]) =
    if not n.isNil:
      walk(n.left, acc)
      walk(n.right, acc)
      acc.add n.elem
  walk(t.root, result)

func ascendingChain*[T](items: openArray[T]): Option[Bst[T]] {.raises: [].} =
  ## The degenerate tree of strictly ascending items (every node has only a right child), built
  ## iteratively in O(n) from the largest item down; `none` when the items are not strictly
  ## ascending. It is the worst case of an unbalanced tree, made on purpose for tests and demos.
  for i in 1 ..< items.len:
    if not (items[i - 1] < items[i]): return none(Bst[T])
  var root: Node[T]
  for i in countdown(items.len - 1, 0):
    root = Node[T](elem: items[i], right: root)
  some(Bst[T](root: root, size: items.len))

func fromSeq*[T](items: openArray[T]): Bst[T] {.raises: [].} =
  ## Inserts the items left to right; the shape depends on that order.
  result = emptyBst[T]()
  for x in items:
    result = result.insert(x)

func invariantsHold*[T](t: Bst[T]): bool {.raises: [].} =
  ## Every item lies strictly between the bounds set by its ancestors, and `len` counts the nodes.
  func ok(n: Node[T]; lo, hi: Option[T]): bool =
    if n.isNil: true
    else:
      (lo.isNone or lo.get < n.elem) and (hi.isNone or n.elem < hi.get) and
        ok(n.left, lo, some(n.elem)) and ok(n.right, some(n.elem), hi)
  func count(n: Node[T]): int =
    if n.isNil: 0 else: 1 + count(n.left) + count(n.right)
  ok(t.root, none(T), none(T)) and count(t.root) == t.size

## Persistent singly linked list (a "cons list").
##
## Every update returns a new list and leaves the old one valid; lists share their tails through
## `ref` to immutable nodes, so `xs.cons(x)` is O(1) in time and space and two lists built from the
## same `xs` share all of `xs`. Use it as a stack, as the spine of recursive algorithms, or as the
## building block of the queues and heaps in this package; reach for `seq` when you need indexed
## access or cache-friendly scans.

import std/options

type
  NodeObj[T] = object
    head: T
    tail: ConsList[T]
  Node[T] = ref NodeObj[T]
  ConsList*[T] = object
    ## The empty list is `default(ConsList[T])`; there is no nil to check at the call site.
    node: Node[T]

proc `=destroy`[T](n: var NodeObj[T]) =
  ## Frees a long chain in a loop. The default destructor would recurse once per node and
  ## overflow the stack on a list of a few hundred thousand nodes. A node that another list still
  ## reaches (`isUniqueRef` is false) is left alone: its last owner frees it.
  var next = move(n.tail.node)
  while not next.isNil and isUniqueRef(next):
    let following = move(next.tail.node)   # `next` now has no tail, so freeing it is O(1)
    next = following
  reset(n.head)

func emptyList*[T](): ConsList[T] {.raises: [].} =
  ConsList[T]()

func isEmpty*[T](xs: ConsList[T]): bool {.raises: [].} =
  xs.node.isNil

func cons*[T](xs: ConsList[T]; x: T): ConsList[T] {.raises: [].} =
  ## New list with `x` in front; `xs` is untouched and shared.
  ConsList[T](node: Node[T](head: x, tail: xs))

func head*[T](xs: ConsList[T]): Option[T] {.raises: [].} =
  if xs.isEmpty: none(T) else: some(xs.node.head)

func tail*[T](xs: ConsList[T]): ConsList[T] {.raises: [].} =
  ## The list without its first element; the tail of the empty list is the empty list.
  if xs.isEmpty: xs else: xs.node.tail

func isUnshared*[T](xs: ConsList[T]): bool {.raises: [].} =
  ## True when no other list or variable reaches the first cell of `xs`, so that dropping `xs`
  ## frees it. Structures that tear themselves down iteratively use this to stop at shared cells.
  xs.isEmpty or isUniqueRef(xs.node)

func sharesNode*[T](a, b: ConsList[T]): bool {.raises: [].} =
  ## True when both lists start at the same node in memory (reference identity).
  a.node == b.node

iterator items*[T](xs: ConsList[T]): T {.raises: [].} =
  var cur = xs
  while not cur.isEmpty:
    yield cur.node.head
    cur = cur.node.tail

func foldLeft*[T, A](xs: ConsList[T]; init: A; f: proc(acc: A; x: T): A {.noSideEffect, raises: [].}): A {.raises: [].} =
  ## Left fold: `foldLeft([1,2,3], z, f) == f(f(f(z,1),2),3)`.
  var acc = init
  for x in items(xs):
    acc = f(acc, x)
  acc

func len*[T](xs: ConsList[T]): int {.raises: [].} =
  var n = 0
  for _ in items(xs):
    inc n
  n

func toSeq*[T](xs: ConsList[T]): seq[T] {.raises: [].} =
  for x in items(xs):
    result.add x

func reverse*[T](xs: ConsList[T]): ConsList[T] {.raises: [].} =
  var acc = emptyList[T]()
  for x in items(xs):
    acc = acc.cons(x)
  acc

func fromSeq*[T](items: openArray[T]): ConsList[T] {.raises: [].} =
  var acc = emptyList[T]()
  for i in countdown(items.high, 0):
    acc = acc.cons(items[i])
  acc

func append*[T](a, b: ConsList[T]): ConsList[T] {.raises: [].} =
  ## `a ++ b`: copies the spine of `a` (O(len a)) and shares all of `b`.
  var acc = b
  for x in items(a.reverse):
    acc = acc.cons(x)
  acc

func map*[T, U](xs: ConsList[T]; f: proc(x: T): U {.noSideEffect, raises: [].}): ConsList[U] {.raises: [].} =
  var acc = emptyList[U]()
  for x in items(xs):
    acc = acc.cons(f(x))
  acc.reverse

func `==`*[T](a, b: ConsList[T]): bool {.raises: [].} =
  a.toSeq == b.toSeq

## Persistent double-ended queue from two lists with rebalancing.
##
## The front list holds the left end in order, the rear list the right end reversed. Pushing and
## popping at either end is O(1) except when one list becomes more than twice as long as the other
## (plus one): then the elements are split evenly again at O(n). Every operation is O(1) amortized
## when each version of the deque is used once (the ephemeral use). A persistent program that
## keeps pushing onto the same old version, just short of a rebalance, pays O(n) every time;
## there is no worst-case O(1) bound here (a real-time deque needs lazy rotations). Use it when
## elements enter or leave at both ends (sliding windows, undo/redo buffers); use
## `bankers_queue` when only one end pops.

import std/options
import nimcs/ds/cons_list

type
  Deque*[T] = object
    front: ConsList[T]
    rear: ConsList[T]
    lenFront: int
    lenRear: int

const balanceFactor = 2

func emptyDeque*[T](): Deque[T] {.raises: [].} =
  Deque[T]()

func len*[T](d: Deque[T]): int {.raises: [].} =
  d.lenFront + d.lenRear

func isEmpty*[T](d: Deque[T]): bool {.raises: [].} =
  d.len == 0

func rebuilt[T](all: seq[T]; frontCount: int): Deque[T] =
  ## `all` is the whole deque left to right; the first `frontCount` go to the front list.
  var rearItems: seq[T]
  for i in countdown(all.high, frontCount):
    rearItems.add all[i]
  Deque[T](front: fromSeq(all[0 ..< frontCount]), rear: fromSeq(rearItems),
    lenFront: frontCount, lenRear: all.len - frontCount)

func toSeq*[T](d: Deque[T]): seq[T] {.raises: [].} =
  ## Elements from left to right.
  d.front.toSeq & d.rear.reverse.toSeq

func balanced[T](d: Deque[T]): Deque[T] =
  ## Invariant: each list has at most `balanceFactor * other + 1` elements.
  if d.lenFront > balanceFactor * d.lenRear + 1 or d.lenRear > balanceFactor * d.lenFront + 1:
    rebuilt(d.toSeq, d.len div 2)
  else: d

func pushFront*[T](d: Deque[T]; x: T): Deque[T] {.raises: [].} =
  Deque[T](front: d.front.cons(x), rear: d.rear, lenFront: d.lenFront + 1,
    lenRear: d.lenRear).balanced

func pushBack*[T](d: Deque[T]; x: T): Deque[T] {.raises: [].} =
  Deque[T](front: d.front, rear: d.rear.cons(x), lenFront: d.lenFront,
    lenRear: d.lenRear + 1).balanced

func peekFront*[T](d: Deque[T]): Option[T] {.raises: [].} =
  if d.front.isEmpty: d.rear.reverse.head  # only possible with one element in `rear`
  else: d.front.head

func peekBack*[T](d: Deque[T]): Option[T] {.raises: [].} =
  if d.rear.isEmpty: d.front.reverse.head
  else: d.rear.head

func popFront*[T](d: Deque[T]): Deque[T] {.raises: [].} =
  ## The deque without its leftmost element; the empty deque stays empty.
  if d.isEmpty: d
  elif d.front.isEmpty: emptyDeque[T]()  # invariant: then `rear` has exactly one element
  else:
    Deque[T](front: d.front.tail, rear: d.rear, lenFront: d.lenFront - 1,
      lenRear: d.lenRear).balanced

func popBack*[T](d: Deque[T]): Deque[T] {.raises: [].} =
  if d.isEmpty: d
  elif d.rear.isEmpty: emptyDeque[T]()
  else:
    Deque[T](front: d.front, rear: d.rear.tail, lenFront: d.lenFront,
      lenRear: d.lenRear - 1).balanced

func fromSeq*[T](items: openArray[T]): Deque[T] {.raises: [].} =
  var d = emptyDeque[T]()
  for x in items:
    d = d.pushBack(x)
  d

## Fenwick tree (binary indexed tree): prefix sums with point updates over integers.
##
## Slot `i` (1-based) of a flat array stores the sum of the `lowbit(i)` elements that end at `i`,
## where `lowbit(i)` is the largest power of two dividing `i`. A prefix sum adds O(log n) slots
## (strip the lowest set bit each step); a point update adds to O(log n) slots (add the lowest set
## bit each step). Because a range sum is the difference of two prefix sums, the element type
## must have an inverse: this is the integers under `+`. Use it for running totals, rank counting
## and inversion counting; use `segment_tree` when the operation is only associative (min, gcd,
## string concatenation). A `FenwickTree` is a value: every update returns a new tree, so the
## copy of the flat array costs O(n); `addAll` applies many updates with one copy.
##
## Precondition for all sums: every prefix sum fits in `int`.

import std/options

type
  FenwickTree* = object
    slots: seq[int]    ## slots[0] is unused; slots[i] covers elements i - lowbit(i) ..< i (0-based)

func lowbit(i: int): int =
  i and -i

func len*(f: FenwickTree): int {.raises: [].} =
  ## Number of elements.
  f.slots.len - 1

func zeros*(n: int): Option[FenwickTree] {.raises: [].} =
  ## A tree of `n` zeros; none when `n` is negative.
  if n < 0: none(FenwickTree)
  else: some(FenwickTree(slots: newSeq[int](n + 1)))

func fromSeq*(items: openArray[int]): FenwickTree {.raises: [].} =
  ## Builds the tree in O(n): each slot is pushed once into the slot that also covers it.
  var slots = newSeq[int](items.len + 1)
  for i in 1 .. items.len:
    slots[i] += items[i - 1]
    let parent = i + lowbit(i)
    if parent <= items.len:
      slots[parent] += slots[i]
  FenwickTree(slots: slots)

func prefixSum*(f: FenwickTree; r: int): Option[int] {.raises: [].} =
  ## Sum of elements 0 ..< r; none unless 0 <= r <= len. `prefixSum(0)` is 0.
  if r < 0 or r > f.len: return none(int)
  var total = 0
  var i = r
  while i > 0:
    total += f.slots[i]
    i -= lowbit(i)
  some(total)

func rangeSum*(f: FenwickTree; l, r: int): Option[int] {.raises: [].} =
  ## Sum of elements l ..< r (half-open, like `segment_tree.query`); none unless 0 <= l <= r <= len.
  if l < 0 or l > r or r > f.len: return none(int)
  some(f.prefixSum(r).get - f.prefixSum(l).get)

func get*(f: FenwickTree; i: int): Option[int] {.raises: [].} =
  ## Element `i`; none when out of range.
  f.rangeSum(i, i + 1)

func add*(f: FenwickTree; i, delta: int): Option[FenwickTree] {.raises: [].} =
  ## A tree whose element `i` is increased by `delta`; none when `i` is out of range.
  if i < 0 or i >= f.len: return none(FenwickTree)
  var slots = f.slots
  var j = i + 1
  while j < slots.len:
    slots[j] += delta
    j += lowbit(j)
  some(FenwickTree(slots: slots))

func addAll*(f: FenwickTree; updates: openArray[(int, int)]): Option[FenwickTree] {.raises: [].} =
  ## Applies `(index, delta)` pairs with a single copy of the array. None, and no change, when any
  ## index is out of range.
  for (i, _) in updates:
    if i < 0 or i >= f.len: return none(FenwickTree)
  var slots = f.slots
  for (i, delta) in updates:
    var j = i + 1
    while j < slots.len:
      slots[j] += delta
      j += lowbit(j)
  some(FenwickTree(slots: slots))

func values*(f: FenwickTree): seq[int] {.raises: [].} =
  ## The elements in index order.
  for i in 0 ..< f.len:
    result.add f.get(i).get

## Hash array mapped trie (HAMT): a persistent unordered map with O(log32 n) operations.
##
## The hash of a key is read five bits at a time; each trie node stores a 32-bit bitmap saying
## which of its 32 slots are used and keeps only the used slots in a compact `seq`. A slot holds
## a single pair, a child node, or (when all 60+ hash bits agree) a bucket of colliding pairs.
## `put` and `remove` copy one root-to-leaf path and share the rest. The hash comes from
## `std/hashes` (`hash(key)`), which is deterministic for ints and strings; iteration order
## follows hash bits, so it is never exposed: the only way to list entries is `toSortedSeq`.
## Use it for large maps that are updated functionally and need no key order; use `rb_tree` when
## you need ordered traversal.

import std/[hashes, options, algorithm, bitops]

const
  bits = 5
  mask = 31'u64
  maxLevel = 12     ## levels 0..12 consume 65 bits; deeper than that means identical hashes

type
  SlotKind = enum
    skPair, skNode, skBucket
  Node[K, V] = ref object
    bitmap: uint32
    slots: seq[Slot[K, V]]
  Slot[K, V] = object
    case kind: SlotKind
    of skPair:
      key: K
      val: V
    of skNode:
      child: Node[K, V]
    of skBucket:
      pairs: seq[(K, V)]
  Hamt*[K, V] = object
    root: Node[K, V]
    size: int

func emptyHamt*[K, V](): Hamt[K, V] {.raises: [].} =
  Hamt[K, V](root: Node[K, V]())

func len*[K, V](m: Hamt[K, V]): int {.raises: [].} =
  m.size

func chunk(h: uint64; level: int): int =
  int((h shr (level * bits)) and mask)

func positionOf(bitmap: uint32; idx: int): int =
  ## Index into `slots` of the slot for chunk `idx`.
  countSetBits(bitmap and ((1'u32 shl idx) - 1))

func hashOf[K](key: K): uint64 =
  uint64(hash(key))

func pairSlot[K, V](key: K; val: V): Slot[K, V] =
  Slot[K, V](kind: skPair, key: key, val: val)

func joinPairs[K, V](k1: K; v1: V; k2: K; v2: V; level: int): Slot[K, V] =
  ## A slot holding two pairs with different keys, as seen from a node at `level - 1`.
  if level > maxLevel:
    Slot[K, V](kind: skBucket, pairs: @[(k1, v1), (k2, v2)])
  else:
    let i1 = chunk(hashOf(k1), level)
    let i2 = chunk(hashOf(k2), level)
    if i1 == i2:
      Slot[K, V](kind: skNode, child: Node[K, V](bitmap: 1'u32 shl i1,
        slots: @[joinPairs(k1, v1, k2, v2, level + 1)]))
    elif i1 < i2:
      Slot[K, V](kind: skNode, child: Node[K, V](bitmap: (1'u32 shl i1) or (1'u32 shl i2),
        slots: @[pairSlot(k1, v1), pairSlot(k2, v2)]))
    else:
      Slot[K, V](kind: skNode, child: Node[K, V](bitmap: (1'u32 shl i1) or (1'u32 shl i2),
        slots: @[pairSlot(k2, v2), pairSlot(k1, v1)]))

func putInto[K, V](n: Node[K, V]; key: K; h: uint64; val: V; level: int): Node[K, V] =
  let idx = chunk(h, level)
  let bit = 1'u32 shl idx
  let pos = positionOf(n.bitmap, idx)
  var slots = n.slots
  if (n.bitmap and bit) == 0:
    slots.insert(pairSlot(key, val), pos)
    return Node[K, V](bitmap: n.bitmap or bit, slots: slots)
  let slot = n.slots[pos]
  case slot.kind
  of skPair:
    slots[pos] =
      if slot.key == key: pairSlot(key, val)
      else: joinPairs(slot.key, slot.val, key, val, level + 1)
  of skNode:
    slots[pos] = Slot[K, V](kind: skNode, child: putInto(slot.child, key, h, val, level + 1))
  of skBucket:
    var pairs = slot.pairs
    var found = false
    for p in pairs.mitems:
      if p[0] == key:
        p[1] = val
        found = true
    if not found: pairs.add (key, val)
    slots[pos] = Slot[K, V](kind: skBucket, pairs: pairs)
  Node[K, V](bitmap: n.bitmap, slots: slots)

func get*[K, V](m: Hamt[K, V]; key: K): Option[V] {.raises: [].} =
  if m.root.isNil: return none(V)
  let h = hashOf(key)
  var n = m.root
  var level = 0
  while true:
    let idx = chunk(h, level)
    if (n.bitmap and (1'u32 shl idx)) == 0: return none(V)
    let slot = n.slots[positionOf(n.bitmap, idx)]
    case slot.kind
    of skPair:
      return if slot.key == key: some(slot.val) else: none(V)
    of skNode:
      n = slot.child
      inc level
    of skBucket:
      for p in slot.pairs:
        if p[0] == key: return some(p[1])
      return none(V)

func contains*[K, V](m: Hamt[K, V]; key: K): bool {.raises: [].} =
  m.get(key).isSome

func put*[K, V](m: Hamt[K, V]; key: K; val: V): Hamt[K, V] {.raises: [].} =
  ## Inserts or replaces the value of `key`.
  let root = if m.root.isNil: Node[K, V]() else: m.root
  Hamt[K, V](root: putInto(root, key, hashOf(key), val, 0),
    size: if m.contains(key): m.size else: m.size + 1)

func removeFrom[K, V](n: Node[K, V]; key: K; h: uint64; level: int): Node[K, V] =
  ## Returns nil when the node becomes empty. Singleton nodes are not collapsed into their parent.
  let idx = chunk(h, level)
  let bit = 1'u32 shl idx
  if (n.bitmap and bit) == 0: return n
  let pos = positionOf(n.bitmap, idx)
  let slot = n.slots[pos]
  var slots = n.slots
  var bitmap = n.bitmap
  case slot.kind
  of skPair:
    if slot.key != key: return n
    slots.delete(pos)
    bitmap = bitmap and not bit
  of skNode:
    let child = removeFrom(slot.child, key, h, level + 1)
    if child == slot.child: return n
    if child.isNil:
      slots.delete(pos)
      bitmap = bitmap and not bit
    else:
      slots[pos] = Slot[K, V](kind: skNode, child: child)
  of skBucket:
    var pairs: seq[(K, V)]
    for p in slot.pairs:
      if p[0] != key: pairs.add p
    if pairs.len == slot.pairs.len: return n
    if pairs.len == 0:
      slots.delete(pos)
      bitmap = bitmap and not bit
    else:
      slots[pos] = Slot[K, V](kind: skBucket, pairs: pairs)
  if slots.len == 0: nil
  else: Node[K, V](bitmap: bitmap, slots: slots)

func remove*[K, V](m: Hamt[K, V]; key: K): Hamt[K, V] {.raises: [].} =
  ## The map without `key`; unchanged (and the same value) when the key is absent.
  if not m.contains(key): return m
  let root = removeFrom(m.root, key, hashOf(key), 0)
  Hamt[K, V](root: if root.isNil: Node[K, V]() else: root, size: m.size - 1)

func collect[K, V](n: Node[K, V]; into: var seq[(K, V)]) =
  for slot in n.slots:
    case slot.kind
    of skPair: into.add (slot.key, slot.val)
    of skNode: collect(slot.child, into)
    of skBucket:
      for p in slot.pairs:
        into.add p

func toSortedSeq*[K, V](m: Hamt[K, V]): seq[(K, V)] {.raises: [].} =
  ## All entries ordered by key. The trie's own order depends on the hash and is never exposed.
  if m.root.isNil: return
  collect(m.root, result)
  result.sort(proc(a, b: (K, V)): int = cmp(a[0], b[0]))

func fromPairs*[K, V](pairs: openArray[(K, V)]): Hamt[K, V] {.raises: [].} =
  ## Later pairs replace earlier ones with the same key.
  var m = emptyHamt[K, V]()
  for (k, v) in pairs:
    m = m.put(k, v)
  m

## Hash table with open addressing and linear probing, as a value type.
##
## All entries live in one flat `seq` of slots. A key starts at the slot its hash selects and, when
## that slot is taken, moves one slot forward (wrapping around) until it finds its key or an empty
## slot. `del` shifts the following entries of the probe run backwards instead of leaving
## tombstones, so a lookup never walks over dead slots. The capacity is a power of two and the load
## stays at or below three quarters, so a probe run always ends at an empty slot.
##
## The type is a value (ADR-NCK-0002): `put` and `del` return a new table and the old one stays
## valid. That costs a copy of the slot array per update, O(n), so the cheap way to build a table
## is `fromPairs` (one local table, O(1) amortized per entry) and the cheap way to update a table
## in a loop is to keep a `var` local to one routine. Inside one routine, `std/tables` is the better
## tool; reach for this module to see how a hash table works or when an immutable snapshot with
## a deterministic `sortedPairs` view is wanted, and for `hamt` when old versions must stay cheap.
## The key type needs `hash` and `==`; `sortedPairs` also needs `<`.

import std/[hashes, options, algorithm]

type
  Slot[K, V] = object
    used: bool
    key: K
    val: V
  HashTable*[K, V] = object
    slots: seq[Slot[K, V]]
    count: int

const
  minCapacity = 8

func emptyTable*[K, V](): HashTable[K, V] {.raises: [].} =
  HashTable[K, V]()

func len*[K, V](t: HashTable[K, V]): int {.raises: [].} =
  t.count

func isEmpty*[K, V](t: HashTable[K, V]): bool {.raises: [].} =
  t.count == 0

func homeOf[K](key: K; capacity: int): int =
  ## The slot where a key's probe run starts; `capacity` is a power of two.
  int(hash(key)) and (capacity - 1)

func locate[K, V](slots: seq[Slot[K, V]]; key: K): tuple[found: bool, index: int] =
  ## Follows the probe run of `key`: the slot holding it, or the empty slot that ends the run.
  ## The caller guarantees `slots` is non-empty and not full.
  var i = homeOf(key, slots.len)
  while slots[i].used and slots[i].key != key:
    i = (i + 1) and (slots.len - 1)
  (slots[i].used, i)

func rehashed[K, V](slots: seq[Slot[K, V]]; capacity: int): seq[Slot[K, V]] =
  result = newSeq[Slot[K, V]](capacity)
  for s in slots:
    if s.used:
      var i = homeOf(s.key, capacity)
      while result[i].used:
        i = (i + 1) and (capacity - 1)
      result[i] = s

func put*[K, V](t: HashTable[K, V]; key: K; val: V): HashTable[K, V] {.raises: [].} =
  ## The table with `key` bound to `val`; an existing binding is replaced. O(n) because the slot
  ## array is copied; use `fromPairs` to add many entries.
  var slots = if t.slots.len == 0: newSeq[Slot[K, V]](minCapacity) else: t.slots
  let at = locate(slots, key)
  if at.found:
    slots[at.index].val = val
    HashTable[K, V](slots: slots, count: t.count)
  else:
    if (t.count + 1) * 4 > slots.len * 3:
      slots = rehashed(slots, slots.len * 2)
    let i = locate(slots, key).index
    slots[i] = Slot[K, V](used: true, key: key, val: val)
    HashTable[K, V](slots: slots, count: t.count + 1)

func get*[K, V](t: HashTable[K, V]; key: K): Option[V] {.raises: [].} =
  if t.count == 0: none(V)
  else:
    let at = locate(t.slots, key)
    if at.found: some(t.slots[at.index].val) else: none(V)

func contains*[K, V](t: HashTable[K, V]; key: K): bool {.raises: [].} =
  t.get(key).isSome

func shiftBack[K, V](slots: var seq[Slot[K, V]]; hole: int) =
  ## Closes the hole left by a deleted entry: a later entry of the same run moves into it when
  ## its home slot is not strictly between the hole and the entry (cyclically).
  let mask = slots.len - 1
  var hole = hole
  var j = hole
  while true:
    j = (j + 1) and mask
    if not slots[j].used: break
    let home = homeOf(slots[j].key, slots.len)
    let distHome = (j - home) and mask      # how far the entry sits from its home slot
    let distHole = (j - hole) and mask      # how far the hole is behind the entry
    if distHome >= distHole:
      slots[hole] = slots[j]
      slots[j] = Slot[K, V]()
      hole = j
  slots[hole] = Slot[K, V]()

func del*[K, V](t: HashTable[K, V]; key: K): HashTable[K, V] {.raises: [].} =
  ## The table without `key`; a missing key leaves the table as it was. O(n): the slot array is copied.
  if t.count == 0: t
  else:
    var slots = t.slots
    let at = locate(slots, key)
    if not at.found: t
    else:
      slots.shiftBack(at.index)
      HashTable[K, V](slots: slots, count: t.count - 1)

func fromPairs*[K, V](pairs: openArray[(K, V)]): HashTable[K, V] {.raises: [].} =
  ## Builds a table in one pass over a local slot array; for a repeated key the last pair wins.
  var slots = newSeq[Slot[K, V]](minCapacity)
  var count = 0
  for (k, v) in pairs:
    let at = locate(slots, k)
    if at.found:
      slots[at.index].val = v
    else:
      if (count + 1) * 4 > slots.len * 3:
        slots = rehashed(slots, slots.len * 2)
      let i = locate(slots, k).index
      slots[i] = Slot[K, V](used: true, key: k, val: v)
      inc count
  HashTable[K, V](slots: slots, count: count)

func sortedPairs*[K, V](t: HashTable[K, V]): seq[(K, V)] {.raises: [].} =
  ## All entries ordered by key. The slot order depends on the hash function and the history of the
  ## table, so it is never exposed; this view is the deterministic one (ADR-NCK-0002 S7).
  for s in t.slots:
    if s.used:
      result.add (s.key, s.val)
  result.sort(func(a, b: (K, V)): int = cmp(a[0], b[0]))

func invariantsHold*[K, V](t: HashTable[K, V]): bool {.raises: [].} =
  ## The capacity is zero or a power of two, `count` matches the used slots, the load is at most
  ## three quarters, and every entry is reachable from its home slot without crossing an empty slot.
  if t.slots.len == 0: return t.count == 0
  let cap = t.slots.len
  if (cap and (cap - 1)) != 0 or t.count * 4 > cap * 3: return false
  var used = 0
  for i in 0 ..< cap:
    if t.slots[i].used:
      inc used
      var j = homeOf(t.slots[i].key, cap)
      while j != i:
        if not t.slots[j].used: return false
        j = (j + 1) and (cap - 1)
  used == t.count

## Static 2-d tree: nearest neighbour and rectangle queries over a fixed set of points.
##
## The tree is built once from a sequence of points. At each level the points are sorted along one
## axis (x at the root, then y, then x again), the median becomes the node, and the two halves
## become its subtrees, so the tree is balanced with height about log2 n. Nothing is updated
## afterwards: the tree is an immutable value, safe to share. `nearest` descends towards the query
## point and visits the far side only when the splitting line is at least as close as the best
## point found so far; `inRect` visits only subtrees that can overlap the rectangle. Results are
## deterministic: a tie in distance goes to the lexicographically smaller point, and `inRect`
## returns points in lexicographic order. Use it for repeated spatial queries over points that do
## not change; for a set that changes, rebuild, or use a structure with updates (`treap` on one
## coordinate when one axis is enough).

import std/[algorithm, options]
import nimcs/fp/result

const maxCoord* = 1e150
  ## Coordinates must satisfy `abs(c) <= maxCoord`, so that a squared distance cannot overflow.

type
  Point* = object
    x*, y*: float
  Rect* = object
    ## The closed rectangle `[xLo, xHi] x [yLo, yHi]`; empty when a low bound exceeds its high one.
    xLo*, xHi*, yLo*, yHi*: float
  KdError* = enum
    badCoordinate   ## a coordinate is NaN, infinite or larger than `maxCoord` in magnitude
  Node = ref object
    pt: Point
    left, right: Node
  KdTree* = object
    root: Node
    size: int

func point*(x, y: float): Point {.raises: [].} =
  Point(x: x, y: y)

func rect*(xLo, xHi, yLo, yHi: float): Rect {.raises: [].} =
  Rect(xLo: xLo, xHi: xHi, yLo: yLo, yHi: yHi)

func `==`*(a, b: Point): bool {.raises: [].} =
  a.x == b.x and a.y == b.y

func `<`*(a, b: Point): bool {.raises: [].} =
  ## Lexicographic order: by x, then by y.
  a.x < b.x or (a.x == b.x and a.y < b.y)

func dist2*(a, b: Point): float {.raises: [].} =
  ## Squared Euclidean distance (exact comparison without a square root).
  let dx = a.x - b.x
  let dy = a.y - b.y
  dx * dx + dy * dy

func validCoord(c: float): bool =
  abs(c) <= maxCoord               # false for NaN and for the infinities

func coord(p: Point; axis: int): float =
  if axis == 0: p.x else: p.y

func cmpOnAxis(a, b: Point; axis: int): int =
  ## Order by the axis coordinate, with the full lexicographic order as a deterministic tie-break.
  let ca = coord(a, axis)
  let cb = coord(b, axis)
  if ca < cb: -1
  elif cb < ca: 1
  elif a < b: -1
  elif b < a: 1
  else: 0

func build(pts: seq[Point]; axis: int): Node =
  if pts.len == 0: return nil
  var sorted = pts
  sorted.sort(proc(a, b: Point): int = cmpOnAxis(a, b, axis))
  let mid = sorted.len div 2
  Node(pt: sorted[mid], left: build(sorted[0 ..< mid], 1 - axis),
    right: build(sorted[mid + 1 ..< sorted.len], 1 - axis))

func buildKdTree*(points: openArray[Point]): Result[KdTree, KdError] {.raises: [].} =
  ## Builds the tree. Duplicate points are kept. A point with a coordinate that is NaN, infinite or
  ## beyond `maxCoord` makes the whole build fail with `badCoordinate`.
  for p in points:
    if not validCoord(p.x) or not validCoord(p.y):
      return err(KdTree, badCoordinate)
  ok(KdTree(root: build(@points, 0), size: points.len), KdError)

func len*(t: KdTree): int {.raises: [].} =
  t.size

func isEmpty*(t: KdTree): bool {.raises: [].} =
  t.root.isNil

func better(cand, best: Point; q: Point): bool =
  let dc = dist2(cand, q)
  let db = dist2(best, q)
  dc < db or (dc == db and cand < best)

func nearestIn(n: Node; q: Point; axis: int; best: Option[Point]): Option[Point] =
  if n.isNil: return best
  var cur = best
  if cur.isNone or better(n.pt, cur.get, q):
    cur = some(n.pt)
  let diff = coord(q, axis) - coord(n.pt, axis)
  let (near, far) = if diff < 0: (n.left, n.right) else: (n.right, n.left)
  cur = nearestIn(near, q, 1 - axis, cur)
  # The far side can hold an equally close point, so the test is `<=`, not `<`.
  if diff * diff <= dist2(cur.get, q):
    cur = nearestIn(far, q, 1 - axis, cur)
  cur

func nearest*(t: KdTree; q: Point): Option[Point] {.raises: [].} =
  ## The stored point closest to `q`; among equally close points the lexicographically smallest.
  ## None for an empty tree. `q` must have coordinates within `maxCoord` in magnitude.
  nearestIn(t.root, q, 0, none(Point))

func inside(r: Rect; p: Point): bool =
  r.xLo <= p.x and p.x <= r.xHi and r.yLo <= p.y and p.y <= r.yHi

func collectIn(n: Node; r: Rect; axis: int; acc: var seq[Point]) =
  if n.isNil: return
  let c = coord(n.pt, axis)
  let lo = if axis == 0: r.xLo else: r.yLo
  let hi = if axis == 0: r.xHi else: r.yHi
  if lo <= c: collectIn(n.left, r, 1 - axis, acc)      # the left side holds coordinates <= c
  if inside(r, n.pt): acc.add n.pt
  if c <= hi: collectIn(n.right, r, 1 - axis, acc)     # the right side holds coordinates >= c

func inRect*(t: KdTree; r: Rect): seq[Point] {.raises: [].} =
  ## All stored points inside the closed rectangle `r` (duplicates repeated), in lexicographic order.
  collectIn(t.root, r, 0, result)
  result.sort(proc(a, b: Point): int =
    if a < b: -1 elif b < a: 1 else: 0)

func toSeq*(t: KdTree): seq[Point] {.raises: [].} =
  ## Every stored point, in lexicographic order.
  collectIn(t.root, Rect(xLo: -maxCoord, xHi: maxCoord, yLo: -maxCoord, yHi: maxCoord), 0, result)
  result.sort(proc(a, b: Point): int =
    if a < b: -1 elif b < a: 1 else: 0)

func heightOf(n: Node): int =
  if n.isNil: 0 else: 1 + max(heightOf(n.left), heightOf(n.right))

func height*(t: KdTree): int {.raises: [].} =
  heightOf(t.root)

func invariantsHold*(t: KdTree): bool {.raises: [].} =
  ## At every node, the left subtree has axis coordinates <= the node's and the right subtree has
  ## coordinates >= the node's; subtree sizes differ by at most one; the node count is `len`.
  func count(n: Node): int =
    if n.isNil: 0 else: 1 + count(n.left) + count(n.right)
  func within(n: Node; axis: int; bound: float; below: bool): bool =
    if n.isNil: true
    else:
      let c = coord(n.pt, axis)
      (if below: c <= bound else: c >= bound) and within(n.left, axis, bound, below) and
        within(n.right, axis, bound, below)
  func ok(n: Node; axis: int): bool =
    if n.isNil: true
    else:
      let c = coord(n.pt, axis)
      within(n.left, axis, c, true) and within(n.right, axis, c, false) and
        abs(count(n.left) - count(n.right)) <= 1 and ok(n.left, 1 - axis) and ok(n.right, 1 - axis)
  count(t.root) == t.size and ok(t.root, 0)

## Leftist heap: a mergeable persistent min-heap.
##
## A binary tree with the heap order (a parent is not larger than its children) and the leftist
## property: the right spine is never longer than the left one. All work follows the right spine,
## so `merge`, `insert` and `deleteMin` are O(log n) worst case. Use it when two priority queues
## must be combined often; use `pairing_heap` for lower constants in practice.

import std/options

type
  NodeObj[T] = object
    rank: int          ## length of the right spine
    elem: T
    left, right: Node[T]
  Node[T] = ref NodeObj[T]
  LeftistHeap*[T] = object
    root: Node[T]
    size: int

proc `=destroy`[T](n: var NodeObj[T]) =
  ## The left spine can be as long as the heap (descending inserts), so the default destructor
  ## would recurse once per node. A work list frees the nodes this heap owns alone; a node still
  ## reachable from another heap (`isUniqueRef` is false) is left to its last owner.
  var pending: seq[Node[T]]
  if not n.left.isNil: pending.add move(n.left)
  if not n.right.isNil: pending.add move(n.right)
  while pending.len > 0:
    let c = pending.pop
    if isUniqueRef(c):
      if not c.left.isNil: pending.add move(c.left)
      if not c.right.isNil: pending.add move(c.right)
  reset(n.elem)

func emptyHeap*[T](): LeftistHeap[T] {.raises: [].} =
  LeftistHeap[T]()

func len*[T](h: LeftistHeap[T]): int {.raises: [].} =
  h.size

func isEmpty*[T](h: LeftistHeap[T]): bool {.raises: [].} =
  h.root.isNil

func rankOf[T](n: Node[T]): int =
  if n.isNil: 0 else: n.rank

func make[T](x: T; a, b: Node[T]): Node[T] =
  ## Puts the node with the larger rank on the left.
  if rankOf(a) >= rankOf(b): Node[T](rank: rankOf(b) + 1, elem: x, left: a, right: b)
  else: Node[T](rank: rankOf(a) + 1, elem: x, left: b, right: a)

func mergeNodes[T](a, b: Node[T]): Node[T] =
  if a.isNil: b
  elif b.isNil: a
  elif b.elem < a.elem: make(b.elem, b.left, mergeNodes(a, b.right))
  else: make(a.elem, a.left, mergeNodes(a.right, b))

func merge*[T](a, b: LeftistHeap[T]): LeftistHeap[T] {.raises: [].} =
  LeftistHeap[T](root: mergeNodes(a.root, b.root), size: a.size + b.size)

func insert*[T](h: LeftistHeap[T]; x: T): LeftistHeap[T] {.raises: [].} =
  h.merge(LeftistHeap[T](root: Node[T](rank: 1, elem: x), size: 1))

func findMin*[T](h: LeftistHeap[T]): Option[T] {.raises: [].} =
  if h.isEmpty: none(T) else: some(h.root.elem)

func deleteMin*[T](h: LeftistHeap[T]): LeftistHeap[T] {.raises: [].} =
  ## The heap without its minimum; the empty heap stays empty.
  if h.isEmpty: h
  else: LeftistHeap[T](root: mergeNodes(h.root.left, h.root.right), size: h.size - 1)

func fromSeq*[T](items: openArray[T]): LeftistHeap[T] {.raises: [].} =
  var h = emptyHeap[T]()
  for x in items:
    h = h.insert(x)
  h

func toSortedSeq*[T](h: LeftistHeap[T]): seq[T] {.raises: [].} =
  ## Heap sort: repeatedly take the minimum.
  var cur = h
  while not cur.isEmpty:
    result.add cur.root.elem
    cur = cur.deleteMin

func invariantsHold*[T](h: LeftistHeap[T]): bool {.raises: [].} =
  ## Heap order, leftist property and correct stored ranks, checked over the whole tree.
  func ok(n: Node[T]): bool =
    if n.isNil: true
    else:
      (n.left.isNil or not (n.left.elem < n.elem)) and
        (n.right.isNil or not (n.right.elem < n.elem)) and
        rankOf(n.left) >= rankOf(n.right) and n.rank == rankOf(n.right) + 1 and
        ok(n.left) and ok(n.right)
  ok(h.root)

## Content addressing and the Merkle tree: persistent values whose names are their hashes.
##
## `CasStore` is a content-addressed store: the name of a blob is the hash of its bytes, `put` returns
## a new store and that name, the same bytes put twice keep one copy, and `get` hashes what it found
## again, so a copy that rotted on disk is reported (`ceCorrupt`) instead of returned. `MerkleTree`
## is a tree of digests over a sequence of blocks: its root covers every leaf, an audit path
## proves one leaf against the root, and an update or an append rebuilds one path of O(log n) nodes
## and shares every other node with the old tree.
##
## The hash is a parameter (`Hasher`). The module ships one hash only, `insecureFnv1a64`, whose name
## says what it is: it has no resistance to collisions, so anyone can build two blocks with one
## digest and substitute one for the other. A store or tree that faces untrusted data needs a
## collision-resistant hash such as SHA-256, passed in through `newHasher`.
##
## Leaves and inner nodes are hashed under different prefix bytes (domain separation), so an inner
## node's two digests can never pass as a leaf block. The shape of the tree depends only on the
## number of leaves (the left subtree is the largest power of two below n), so no leaf is ever
## duplicated to fill a level.

import std/[hashes, options]
import nimcs/fp/result
import nimcs/ds/hamt
export result

type
  Digest* = distinct string
    ## The raw bytes of a hash result. The length is the hasher's.
  HashProc* = proc(data: string): string {.noSideEffect, raises: [].}
  HasherError* = enum
    heNoProc, heNoName
  Hasher* {.requiresInit.} = object
    hname: string
    fn: HashProc

  CasError* = enum
    ceMissing, ceCorrupt
  CasStore* {.requiresInit.} = object
    hasher: Hasher
    blobs: Hamt[Digest, string]
  Stored* = tuple[store: CasStore, digest: Digest]

  Node = ref object
    digest: Digest
    count: int            ## leaves below this node
    left, right: Node     ## both nil for a leaf, both set for an inner node
  MerkleTree* {.requiresInit.} = object
    hasher: Hasher
    top: Node             ## nil when there are no leaves
  AuditPath* = seq[Digest]
    ## The digests of the siblings met on the way from a leaf up to the root, bottom first.

# --- digests and hashers -------------------------------------------------------------------------

func `==`*(a, b: Digest): bool {.borrow.}
func `<`*(a, b: Digest): bool {.borrow.}
func hash*(d: Digest): Hash {.borrow.}

func asDigest*(raw: string): Digest {.raises: [].} =
  ## Wraps the raw bytes a hash function returned.
  Digest(raw)

func toBytes*(d: Digest): string {.raises: [].} =
  string(d)

func toHex*(d: Digest): string {.raises: [].} =
  const hexDigits = "0123456789abcdef"
  for c in string(d):
    result.add hexDigits[ord(c) shr 4]
    result.add hexDigits[ord(c) and 15]

func `$`*(d: Digest): string {.raises: [].} =
  toHex(d)

func newHasher*(name: string; digest: HashProc): Result[Hasher, HasherError] {.raises: [].} =
  ## A hasher from a hash function over bytes (for example SHA-256 returning its 32 raw bytes) and
  ## the name that identifies it in logs.
  if digest.isNil: err(Hasher, heNoProc)
  elif name.len == 0: err(Hasher, heNoName)
  else: ok(Hasher(hname: name, fn: digest), HasherError)

func name*(h: Hasher): string {.raises: [].} =
  h.hname

func fnv1a64Bytes(data: string): string {.raises: [].} =
  var h = 0xcbf29ce484222325'u64
  for c in data:
    h = (h xor uint64(ord(c))) * 0x100000001b3'u64
  for i in countdown(7, 0):
    result.add char((h shr (i * 8)) and 0xff'u64)

func insecureFnv1a64*(): Hasher {.raises: [].} =
  ## FNV-1a with 64 bits, big-endian. Fast and well spread, and trivial to attack: use it for
  ## tests and examples only, never where someone can choose the content.
  Hasher(hname: "insecure-fnv1a64", fn: fnv1a64Bytes)

func addressOf*(h: Hasher; data: string): Digest {.raises: [].} =
  ## The content address of `data`: its hash, with no prefix.
  Digest(h.fn(data))

func hashLeaf*(h: Hasher; blk: string): Digest {.raises: [].} =
  ## A leaf digest: the hash of a 0x00 byte followed by the block.
  Digest(h.fn("\x00" & blk))

func hashInner*(h: Hasher; left, right: Digest): Digest {.raises: [].} =
  ## An inner digest: the hash of a 0x01 byte followed by the two child digests.
  Digest(h.fn("\x01" & string(left) & string(right)))

func emptyRoot*(h: Hasher): Digest {.raises: [].} =
  ## The root of a tree with no leaves: the hash of the empty input, which no prefixed input equals.
  addressOf(h, "")

# --- content-addressed store -----------------------------------------------------------------------

func newCasStore*(h: Hasher): CasStore {.raises: [].} =
  CasStore(hasher: h, blobs: emptyHamt[Digest, string]())

func loadUnverified*(h: Hasher; entries: openArray[(Digest, string)]): CasStore {.raises: [].} =
  ## A store holding the given name and bytes pairs as read from outside (a disk, a network) without
  ## checking them; `get` checks on every read.
  var blobs = emptyHamt[Digest, string]()
  for (d, bytes) in entries:
    blobs = blobs.put(d, bytes)
  CasStore(hasher: h, blobs: blobs)

func len*(s: CasStore): int {.raises: [].} =
  ## Number of names held (one per distinct content).
  s.blobs.len

func contains*(s: CasStore; d: Digest): bool {.raises: [].} =
  ## Whether a copy is held under the name `d`; it does not check that the copy is intact.
  s.blobs.contains(d)

func put*(s: CasStore; data: string): Stored {.raises: [].} =
  ## The store holding `data` and the name it is held under. Putting equal bytes again changes nothing.
  let d = addressOf(s.hasher, data)
  (store: CasStore(hasher: s.hasher, blobs: s.blobs.put(d, data)), digest: d)

func get*(s: CasStore; d: Digest): Result[string, CasError] {.raises: [].} =
  ## The bytes named `d`, only if they still hash to `d`.
  let found = s.blobs.get(d)
  if found.isNone: err(string, ceMissing)
  elif addressOf(s.hasher, found.get) != d: err(string, ceCorrupt)
  else: ok(found.get, CasError)

# --- Merkle tree -----------------------------------------------------------------------------------

func splitPoint(n: int): int =
  ## The largest power of two below `n`, for n >= 2: the size of the left subtree.
  result = 1
  while result * 2 < n: result *= 2

func leafNode(h: Hasher; blk: string): Node =
  Node(digest: hashLeaf(h, blk), count: 1)

func joinNodes(h: Hasher; l, r: Node): Node =
  Node(digest: hashInner(h, l.digest, r.digest), count: l.count + r.count, left: l, right: r)

func buildNode(h: Hasher; blocks: openArray[string]; lo, n: int): Node =
  if n == 1: leafNode(h, blocks[lo])
  else:
    let k = splitPoint(n)
    joinNodes(h, buildNode(h, blocks, lo, k), buildNode(h, blocks, lo + k, n - k))

func merkleTree*(h: Hasher; blocks: openArray[string]): MerkleTree {.raises: [].} =
  ## The tree over `blocks` in order; O(n) hashes.
  MerkleTree(hasher: h, top: if blocks.len == 0: nil else: buildNode(h, blocks, 0, blocks.len))

func len*(t: MerkleTree): int {.raises: [].} =
  ## Number of leaves.
  if t.top.isNil: 0 else: t.top.count

func root*(t: MerkleTree): Digest {.raises: [].} =
  ## The digest that covers every leaf; `emptyRoot` for a tree with no leaves.
  if t.top.isNil: emptyRoot(t.hasher) else: t.top.digest

func nodeCount*(t: MerkleTree): int {.raises: [].} =
  ## Leaves plus inner nodes: 2n - 1 for n >= 1.
  if t.top.isNil: 0 else: 2 * t.top.count - 1

func leafDigest*(t: MerkleTree; i: int): Option[Digest] {.raises: [].} =
  if i < 0 or i >= t.len: return none(Digest)
  var n = t.top
  var at = i
  while not n.left.isNil:
    let k = n.left.count
    if at < k: n = n.left
    else:
      at -= k
      n = n.right
  some(n.digest)

func updateNode(h: Hasher; n: Node; i: int; blk: string): Node =
  if n.left.isNil: leafNode(h, blk)
  else:
    let k = n.left.count
    if i < k: joinNodes(h, updateNode(h, n.left, i, blk), n.right)
    else: joinNodes(h, n.left, updateNode(h, n.right, i - k, blk))

func update*(t: MerkleTree; i: int; blk: string): Option[MerkleTree] {.raises: [].} =
  ## The tree with leaf `i` replaced, rebuilding the path from that leaf to the root; none when `i`
  ## is out of range.
  if i < 0 or i >= t.len: none(MerkleTree)
  else: some(MerkleTree(hasher: t.hasher, top: updateNode(t.hasher, t.top, i, blk)))

func appendNode(h: Hasher; n: Node; blk: string): Node =
  if n.isNil: leafNode(h, blk)
  elif n.left.isNil: joinNodes(h, n, leafNode(h, blk))
  elif n.count == 2 * n.left.count: joinNodes(h, n, leafNode(h, blk))    # full: the old tree becomes the left child
  else: joinNodes(h, n.left, appendNode(h, n.right, blk))

func append*(t: MerkleTree; blk: string): MerkleTree {.raises: [].} =
  ## The tree with one more leaf at the end; rebuilds the right edge only.
  MerkleTree(hasher: t.hasher, top: appendNode(t.hasher, t.top, blk))

func proveNode(n: Node; i: int; topDown: var seq[Digest]) =
  if n.left.isNil: return
  let k = n.left.count
  if i < k:
    topDown.add n.right.digest
    proveNode(n.left, i, topDown)
  else:
    topDown.add n.left.digest
    proveNode(n.right, i - k, topDown)

func prove*(t: MerkleTree; i: int): Option[AuditPath] {.raises: [].} =
  ## The audit path of leaf `i`, bottom first; none when `i` is out of range.
  if i < 0 or i >= t.len: return none(AuditPath)
  var topDown: seq[Digest]
  proveNode(t.top, i, topDown)
  var path: AuditPath
  for j in countdown(topDown.len - 1, 0):
    path.add topDown[j]
  some(path)

func verifyInclusion*(h: Hasher; root: Digest; count, index: int; blk: string;
    path: AuditPath): bool {.raises: [].} =
  ## Whether `blk` is leaf `index` of a tree of `count` leaves whose root is `root`. The verifier
  ## needs only the root (from a source it trusts), the leaf count and the path.
  if index < 0 or index >= count: return false
  var siblingLeft: seq[bool]      # top down: is the sibling at this level the left child?
  var at = index
  var n = count
  while n > 1:
    let k = splitPoint(n)
    if at < k:
      siblingLeft.add false
      n = k
    else:
      siblingLeft.add true
      at -= k
      n -= k
  if siblingLeft.len != path.len: return false
  var cur = hashLeaf(h, blk)
  for j in 0 ..< path.len:
    cur =
      if siblingLeft[siblingLeft.len - 1 - j]: hashInner(h, path[j], cur)
      else: hashInner(h, cur, path[j])
  cur == root

func sameNodes(a, b: Node): bool =
  if a == b: true             # the same node, or both nil
  elif a.isNil or b.isNil: false
  elif a.count != b.count or a.digest != b.digest: false
  elif a.left.isNil: b.left.isNil
  else: not b.left.isNil and sameNodes(a.left, b.left) and sameNodes(a.right, b.right)

func `==`*(a, b: MerkleTree): bool {.raises: [].} =
  ## Same shape and same digest at every node. The hashers are not compared (a closure has no equality).
  sameNodes(a.top, b.top)

func collectNodes(n: Node; into: var seq[Node]) =
  if n.isNil: return
  into.add n
  collectNodes(n.left, into)
  collectNodes(n.right, into)

func isMember(n: Node; nodes: seq[Node]): bool =
  ## Identity, not equality of content: a ref has no `hash` in the standard library, so a set of
  ## nodes is not available and a scan does the job.
  for m in nodes:
    if m == n: return true
  false

func countUnseen(n: Node; seen: seq[Node]): int =
  if n.isNil or n.isMember(seen): 0
  else: 1 + countUnseen(n.left, seen) + countUnseen(n.right, seen)

func rebuiltNodes*(before, after: MerkleTree): int {.raises: [].} =
  ## Number of nodes of `after` that are not nodes of `before` (the other nodes are the same memory
  ## in both). An update of one leaf of n leaves gives at most ceil(log2 n) + 1. O(n log n): a
  ## measuring tool, not for hot paths.
  var seen: seq[Node]
  collectNodes(before.top, seen)
  countUnseen(after.top, seen)

## Pairing heap: a mergeable persistent min-heap with a very simple shape.
##
## A node holds its element and a list of child heaps. `merge` makes the larger root a child of the
## smaller one in O(1); `deleteMin` merges the children pairwise from left to right and then
## folds the results from right to left, which is O(log n) amortized (ephemeral use). Use it as a
## default priority queue in functional code; see `leftist_heap` for a worst-case bound.

import std/options
import nimcs/ds/cons_list

type
  NodeObj[T] = object
    elem: T
    children: ConsList[Node[T]]
  Node[T] = ref NodeObj[T]
  PairingHeap*[T] = object
    root: Node[T]
    size: int

proc `=destroy`[T](n: var NodeObj[T]) =
  ## Dismantles a deep heap with a work list instead of one recursive call per level (descending
  ## inserts build a chain as deep as the heap is large). A node still reachable from another
  ## heap (`isUniqueRef` is false) is left to its last owner.
  var pending = @[move(n.children)]
  while pending.len > 0:
    var level = pending.pop
    while not level.isEmpty and level.isUnshared:
      var kid: Node[T]
      for k in items(level):    # `head` would leave an Option temporary holding a second reference
        kid = k
        break
      level = level.tail     # frees the first cell, leaving `kid` as the only owner if it was alone
      if isUniqueRef(kid):
        pending.add move(kid.children)
  reset(n.elem)

func emptyHeap*[T](): PairingHeap[T] {.raises: [].} =
  PairingHeap[T]()

func len*[T](h: PairingHeap[T]): int {.raises: [].} =
  h.size

func isEmpty*[T](h: PairingHeap[T]): bool {.raises: [].} =
  h.root.isNil

func link[T](a, b: Node[T]): Node[T] =
  if b.elem < a.elem: Node[T](elem: b.elem, children: b.children.cons(a))
  else: Node[T](elem: a.elem, children: a.children.cons(b))

func merge*[T](a, b: PairingHeap[T]): PairingHeap[T] {.raises: [].} =
  if a.isEmpty: b
  elif b.isEmpty: a
  else: PairingHeap[T](root: link(a.root, b.root), size: a.size + b.size)

func insert*[T](h: PairingHeap[T]; x: T): PairingHeap[T] {.raises: [].} =
  h.merge(PairingHeap[T](root: Node[T](elem: x), size: 1))

func findMin*[T](h: PairingHeap[T]): Option[T] {.raises: [].} =
  if h.isEmpty: none(T) else: some(h.root.elem)

func mergePairs[T](children: ConsList[Node[T]]): Node[T] =
  ## Two passes, iterative so that a wide node cannot overflow the stack.
  var paired: seq[Node[T]]
  var cur = children
  while not cur.isEmpty:
    let first = cur.head.get
    let rest = cur.tail
    if rest.isEmpty:
      paired.add first
      cur = rest
    else:
      paired.add link(first, rest.head.get)
      cur = rest.tail
  var acc: Node[T] = nil
  for i in countdown(paired.high, 0):
    acc = if acc.isNil: paired[i] else: link(paired[i], acc)
  acc

func deleteMin*[T](h: PairingHeap[T]): PairingHeap[T] {.raises: [].} =
  if h.isEmpty: h
  else: PairingHeap[T](root: mergePairs(h.root.children), size: h.size - 1)

func fromSeq*[T](items: openArray[T]): PairingHeap[T] {.raises: [].} =
  var h = emptyHeap[T]()
  for x in items:
    h = h.insert(x)
  h

func toSortedSeq*[T](h: PairingHeap[T]): seq[T] {.raises: [].} =
  var cur = h
  while not cur.isEmpty:
    result.add cur.root.elem
    cur = cur.deleteMin

## Persistent vector: a 32-way trie giving O(log32 n) indexed `get`, `updated` and `push`.
##
## Elements live in leaves of up to 32 items; interior nodes hold up to 32 children; the index is
## read five bits at a time from the top. An update copies the one path from the root to the
## leaf (at most 7 nodes for 2^32 elements) and shares everything else, so the old vector stays
## valid. Use it for large indexed collections that are updated functionally; use `skew_list`
## when you push and pop at the front. The tail optimisation that real implementations add (an
## unshared buffer at the end) is left out so the shape stays easy to read.

import std/options

const
  bits = 5
  width = 1 shl bits
  mask = width - 1

type
  Node[T] = ref object
    items: seq[T]            ## filled in leaves only
    kids: seq[Node[T]]       ## filled in interior nodes only
  PVector*[T] = object
    root: Node[T]
    shift: int               ## 0 when the root is a leaf, else 5 * (levels above the leaves)
    size: int

func emptyVector*[T](): PVector[T] {.raises: [].} =
  PVector[T](root: Node[T]())

func len*[T](v: PVector[T]): int {.raises: [].} =
  v.size

func isEmpty*[T](v: PVector[T]): bool {.raises: [].} =
  v.size == 0

func capacity[T](v: PVector[T]): int =
  1 shl (v.shift + bits)

func newPath[T](level: int; x: T): Node[T] =
  ## A chain of nodes from `level` down to a leaf holding only `x`.
  if level == 0: Node[T](items: @[x])
  else: Node[T](kids: @[newPath(level - bits, x)])

func pushInto[T](n: Node[T]; level, index: int; x: T): Node[T] =
  if level == 0:
    Node[T](items: n.items & @[x])
  else:
    let slot = (index shr level) and mask
    if slot < n.kids.len:
      var kids = n.kids
      kids[slot] = pushInto(n.kids[slot], level - bits, index, x)
      Node[T](kids: kids)
    else:
      Node[T](kids: n.kids & @[newPath(level - bits, x)])

func push*[T](v: PVector[T]; x: T): PVector[T] {.raises: [].} =
  ## Appends `x` at index `len`.
  let base = if v.root.isNil: emptyVector[T]() else: v
  if base.size == base.capacity:
    PVector[T](root: Node[T](kids: @[base.root, newPath(base.shift, x)]),
      shift: base.shift + bits, size: base.size + 1)
  else:
    PVector[T](root: pushInto(base.root, base.shift, base.size, x), shift: base.shift,
      size: base.size + 1)

func get*[T](v: PVector[T]; i: int): Option[T] {.raises: [].} =
  if i < 0 or i >= v.size: return none(T)
  var n = v.root
  var level = v.shift
  while level > 0:
    n = n.kids[(i shr level) and mask]
    level -= bits
  some(n.items[i and mask])

func setInto[T](n: Node[T]; level, i: int; x: T): Node[T] =
  if level == 0:
    var items = n.items
    items[i and mask] = x
    Node[T](items: items)
  else:
    var kids = n.kids
    let slot = (i shr level) and mask
    kids[slot] = setInto(n.kids[slot], level - bits, i, x)
    Node[T](kids: kids)

func updated*[T](v: PVector[T]; i: int; x: T): Option[PVector[T]] {.raises: [].} =
  ## A copy with index `i` replaced; none when out of range.
  if i < 0 or i >= v.size: none(PVector[T])
  else: some(PVector[T](root: setInto(v.root, v.shift, i, x), shift: v.shift, size: v.size))

func toSeq*[T](v: PVector[T]): seq[T] {.raises: [].} =
  for i in 0 ..< v.size:
    result.add v.get(i).get

func fromSeq*[T](items: openArray[T]): PVector[T] {.raises: [].} =
  var v = emptyVector[T]()
  for x in items:
    v = v.push(x)
  v

func depth*[T](v: PVector[T]): int {.raises: [].} =
  ## Number of nodes on a root-to-leaf path.
  v.shift div bits + 1

## Persistent red-black tree: an ordered map (`RbMap`) and an ordered set (`RbSet`).
##
## A binary search tree whose nodes are coloured so that the root is black, no red node has a red
## child, and every path from a node to a leaf holds the same number of black nodes. Those rules
## keep the height at most 2 log2(n + 1), so `put`, `get` and `contains` are O(log n) worst case.
## `put` copies only the path it walks (O(log n) new nodes) and shares the rest with the old tree,
## which stays valid. Use it for ordered iteration, range-like queries and a deterministic order;
## use `hamt` for unordered lookup. Deletion is not provided: its case analysis is longer than is worth showing here;
## rebuild from `toSeq` without the key, or use `hamt` when you need `remove`.

import std/options

type
  Color = enum
    cRed, cBlack
  Node[K, V] = ref object
    red: bool
    key: K
    val: V
    left, right: Node[K, V]
  RbMap*[K, V] = object
    root: Node[K, V]
    size: int
  Unit = object        ## the value type of a set: no payload
  RbSet*[K] = object
    items: RbMap[K, Unit]

func emptyMap*[K, V](): RbMap[K, V] {.raises: [].} =
  RbMap[K, V]()

func len*[K, V](m: RbMap[K, V]): int {.raises: [].} =
  m.size

func isRed[K, V](n: Node[K, V]): bool =
  not n.isNil and n.red

func mk[K, V](red: bool; key: K; val: V; l, r: Node[K, V]): Node[K, V] =
  Node[K, V](red: red, key: key, val: val, left: l, right: r)

func balance[K, V](key: K; val: V; l, r: Node[K, V]): Node[K, V] =
  ## Builds a black node and repairs a red-red violation among its two upper levels (Okasaki).
  if isRed(l) and isRed(l.left):
    mk(true, l.key, l.val, mk(false, l.left.key, l.left.val, l.left.left, l.left.right),
      mk(false, key, val, l.right, r))
  elif isRed(l) and isRed(l.right):
    let m = l.right
    mk(true, m.key, m.val, mk(false, l.key, l.val, l.left, m.left), mk(false, key, val, m.right, r))
  elif isRed(r) and isRed(r.left):
    let m = r.left
    mk(true, m.key, m.val, mk(false, key, val, l, m.left), mk(false, r.key, r.val, m.right, r.right))
  elif isRed(r) and isRed(r.right):
    mk(true, r.key, r.val, mk(false, key, val, l, r.left),
      mk(false, r.right.key, r.right.val, r.right.left, r.right.right))
  else:
    mk(false, key, val, l, r)

func ins[K, V](n: Node[K, V]; key: K; val: V): Node[K, V] =
  if n.isNil: mk(true, key, val, nil, nil)
  elif key < n.key:
    if n.red: mk(true, n.key, n.val, ins(n.left, key, val), n.right)
    else: balance(n.key, n.val, ins(n.left, key, val), n.right)
  elif n.key < key:
    if n.red: mk(true, n.key, n.val, n.left, ins(n.right, key, val))
    else: balance(n.key, n.val, n.left, ins(n.right, key, val))
  else:
    mk(n.red, key, val, n.left, n.right)

func find[K, V](n: Node[K, V]; key: K): Node[K, V] =
  var cur = n
  while not cur.isNil:
    if key < cur.key: cur = cur.left
    elif cur.key < key: cur = cur.right
    else: return cur
  nil

func get*[K, V](m: RbMap[K, V]; key: K): Option[V] {.raises: [].} =
  let n = find(m.root, key)
  if n.isNil: none(V) else: some(n.val)

func contains*[K, V](m: RbMap[K, V]; key: K): bool {.raises: [].} =
  not find(m.root, key).isNil

func put*[K, V](m: RbMap[K, V]; key: K; val: V): RbMap[K, V] {.raises: [].} =
  ## Inserts or replaces the value of `key`.
  let grown = ins(m.root, key, val)
  let root = mk(false, grown.key, grown.val, grown.left, grown.right)  # the root is always black
  RbMap[K, V](root: root, size: if m.contains(key): m.size else: m.size + 1)

func graft[K, V](color: Color; key: K; val: V; left, right: RbMap[K, V]): RbMap[K, V] {.raises: [].} =
  ## Test-only: a node of the given colour over two subtrees, with no rebalancing and no check that
  ## the result is a valid red-black tree. Not exported, so no caller can build an invalid map; the
  ## tests reach it through `import nimcs/ds/rb_tree {.all.}` to show `invariantsHold` saying no.
  RbMap[K, V](root: mk(color == cRed, key, val, left.root, right.root),
    size: left.size + right.size + 1)

func toSeq*[K, V](m: RbMap[K, V]): seq[(K, V)] {.raises: [].} =
  ## Key/value pairs in increasing key order (in-order walk, explicit stack).
  var stack: seq[Node[K, V]]
  var cur = m.root
  while not cur.isNil or stack.len > 0:
    while not cur.isNil:
      stack.add cur
      cur = cur.left
    let n = stack.pop
    result.add (n.key, n.val)
    cur = n.right

func fromPairs*[K, V](pairs: openArray[(K, V)]): RbMap[K, V] {.raises: [].} =
  ## Later pairs replace earlier ones with the same key.
  var m = emptyMap[K, V]()
  for (k, v) in pairs:
    m = m.put(k, v)
  m

func height*[K, V](m: RbMap[K, V]): int {.raises: [].} =
  func h(n: Node[K, V]): int =
    if n.isNil: 0 else: 1 + max(h(n.left), h(n.right))
  h(m.root)

func invariantsHold*[K, V](m: RbMap[K, V]): bool {.raises: [].} =
  ## Black root, no red node with a red child, equal black height on all paths, every key strictly
  ## between the keys of the nearest ancestors on each side (so `get` finds it), and a stored size
  ## that matches the node count.
  func blackHeight(n, lo, hi: Node[K, V]): int =   # -1 when a rule is broken below `n`
    if n.isNil: return 1
    if not lo.isNil and not (lo.key < n.key): return -1
    if not hi.isNil and not (n.key < hi.key): return -1
    let l = blackHeight(n.left, lo, n)
    let r = blackHeight(n.right, n, hi)
    if l < 0 or r < 0 or l != r: return -1
    if n.red and (isRed(n.left) or isRed(n.right)): return -1
    l + (if n.red: 0 else: 1)
  not isRed(m.root) and blackHeight(m.root, nil, nil) > 0 and m.toSeq.len == m.size

func emptySet*[K](): RbSet[K] {.raises: [].} =
  RbSet[K]()

func len*[K](s: RbSet[K]): int {.raises: [].} =
  s.items.len

func incl*[K](s: RbSet[K]; key: K): RbSet[K] {.raises: [].} =
  RbSet[K](items: s.items.put(key, Unit()))

func contains*[K](s: RbSet[K]; key: K): bool {.raises: [].} =
  s.items.contains(key)

func toSeq*[K](s: RbSet[K]): seq[K] {.raises: [].} =
  for (k, _) in s.items.toSeq:
    result.add k

func fromSeq*[K](keys: openArray[K]): RbSet[K] {.raises: [].} =
  var s = emptySet[K]()
  for k in keys:
    s = s.incl(k)
  s

func invariantsHold*[K](s: RbSet[K]): bool {.raises: [].} =
  s.items.invariantsHold

## Immutable segment tree over a monoid: range queries and point updates in O(log n).
##
## A monoid is an associative `combine` with an `identity`. The tree stores, in every node, the
## combination of the elements below it, so a query over a half-open range [l, r) combines at most
## about 2 log2(n) stored values. A point update copies one root-to-leaf path and shares the rest,
## so the old tree stays valid. Because only associativity is required (not commutativity), the
## order of elements is respected: string concatenation works. Use it for repeated range sums,
## minima, gcds or any associative summary over an array with updates; use a prefix-sum array when
## the data never changes.

import std/options

type
  Monoid*[T] = object
    identity*: T
    combine*: proc(a, b: T): T {.noSideEffect, raises: [].}
  Node[T] = ref object
    value: T
    left, right: Node[T]     ## nil in leaves
  SegTree*[T] = object
    monoid: Monoid[T]
    root: Node[T]
    size: int

func initMonoid*[T](identity: T; combine: proc(a, b: T): T {.noSideEffect, raises: [].}): Monoid[T] {.raises: [].} =
  Monoid[T](identity: identity, combine: combine)

func buildNode[T](m: Monoid[T]; items: openArray[T]; lo, hi: int): Node[T] =
  ## Node for items[lo ..< hi], hi > lo.
  if hi - lo == 1: Node[T](value: items[lo])
  else:
    let mid = (lo + hi) div 2
    let l = buildNode(m, items, lo, mid)
    let r = buildNode(m, items, mid, hi)
    Node[T](value: m.combine(l.value, r.value), left: l, right: r)

func fromSeq*[T](m: Monoid[T]; items: openArray[T]): SegTree[T] {.raises: [].} =
  if items.len == 0: SegTree[T](monoid: m, size: 0)
  else: SegTree[T](monoid: m, root: buildNode(m, items, 0, items.len), size: items.len)

func len*[T](t: SegTree[T]): int {.raises: [].} =
  t.size

func queryNode[T](m: Monoid[T]; n: Node[T]; lo, hi, l, r: int): T =
  ## Combination of the elements of [lo, hi) that fall inside [l, r).
  if r <= lo or hi <= l: m.identity
  elif l <= lo and hi <= r: n.value
  else:
    let mid = (lo + hi) div 2
    m.combine(queryNode(m, n.left, lo, mid, l, r), queryNode(m, n.right, mid, hi, l, r))

func query*[T](t: SegTree[T]; l, r: int): Option[T] {.raises: [].} =
  ## Combination of elements l, l+1, ..., r-1 in order. An empty range gives the identity; a range
  ## outside 0 <= l <= r <= len gives none.
  if l < 0 or r > t.size or l > r: none(T)
  elif l == r: some(t.monoid.identity)
  else: some(queryNode(t.monoid, t.root, 0, t.size, l, r))

func updateNode[T](m: Monoid[T]; n: Node[T]; lo, hi, i: int; x: T): Node[T] =
  if hi - lo == 1: Node[T](value: x)
  else:
    let mid = (lo + hi) div 2
    let l = if i < mid: updateNode(m, n.left, lo, mid, i, x) else: n.left
    let r = if i < mid: n.right else: updateNode(m, n.right, mid, hi, i, x)
    Node[T](value: m.combine(l.value, r.value), left: l, right: r)

func updated*[T](t: SegTree[T]; i: int; x: T): Option[SegTree[T]] {.raises: [].} =
  ## A tree with element `i` replaced by `x`; none when out of range.
  if i < 0 or i >= t.size: none(SegTree[T])
  else: some(SegTree[T](monoid: t.monoid, root: updateNode(t.monoid, t.root, 0, t.size, i, x), size: t.size))

func get*[T](t: SegTree[T]; i: int): Option[T] {.raises: [].} =
  if i < 0 or i >= t.size: none(T)
  else: t.query(i, i + 1)

func total*[T](t: SegTree[T]): T {.raises: [].} =
  ## Combination of all elements (the identity when empty).
  if t.size == 0: t.monoid.identity else: t.root.value

## Skew-binary random-access list: a persistent sequence with O(1) `cons`/`head`/`tail` and
## O(log n) indexed `get` and `updated`.
##
## The list is a short spine of complete binary trees whose sizes are of the form 2^k - 1, in
## non-decreasing order with at most the first two equal (a skew-binary number). Consing links the
## first two trees when they have equal size, otherwise starts a new one-element tree; that is why
## no carry ever ripples. Use it when you need a stack that also supports indexing and
## functional update; use `pvector` for append-at-the-end with indexing, `cons_list` when you never index.

import std/options
import nimcs/ds/cons_list

type
  Tree[T] = ref object
    elem: T
    left, right: Tree[T]    ## both nil for a single element
  Entry[T] = object
    weight: int             ## number of elements, 2^k - 1
    tree: Tree[T]
  SkewList*[T] = object
    spine: ConsList[Entry[T]]
    size: int

func emptySkew*[T](): SkewList[T] {.raises: [].} =
  SkewList[T]()

func len*[T](xs: SkewList[T]): int {.raises: [].} =
  xs.size

func isEmpty*[T](xs: SkewList[T]): bool {.raises: [].} =
  xs.size == 0

func cons*[T](xs: SkewList[T]; x: T): SkewList[T] {.raises: [].} =
  let first = xs.spine.head
  let second = xs.spine.tail.head
  if first.isSome and second.isSome and first.get.weight == second.get.weight:
    let w = first.get.weight
    let linked = Entry[T](weight: 1 + 2 * w,
      tree: Tree[T](elem: x, left: first.get.tree, right: second.get.tree))
    SkewList[T](spine: xs.spine.tail.tail.cons(linked), size: xs.size + 1)
  else:
    SkewList[T](spine: xs.spine.cons(Entry[T](weight: 1, tree: Tree[T](elem: x))), size: xs.size + 1)

func head*[T](xs: SkewList[T]): Option[T] {.raises: [].} =
  let first = xs.spine.head
  if first.isNone: none(T) else: some(first.get.tree.elem)

func tail*[T](xs: SkewList[T]): SkewList[T] {.raises: [].} =
  ## The list without its first element; the tail of the empty list is the empty list.
  let first = xs.spine.head
  if first.isNone: xs
  else:
    let e = first.get
    let rest = xs.spine.tail
    if e.weight == 1: SkewList[T](spine: rest, size: xs.size - 1)
    else:
      let half = e.weight div 2
      SkewList[T](spine: rest.cons(Entry[T](weight: half, tree: e.tree.right))
        .cons(Entry[T](weight: half, tree: e.tree.left)), size: xs.size - 1)

func lookupTree[T](w: int; t: Tree[T]; i: int): T =
  ## Requires 0 <= i < w.
  if i == 0: t.elem
  else:
    let half = w div 2
    if i <= half: lookupTree(half, t.left, i - 1)
    else: lookupTree(half, t.right, i - 1 - half)

func updateTree[T](w: int; t: Tree[T]; i: int; x: T): Tree[T] =
  if i == 0: Tree[T](elem: x, left: t.left, right: t.right)
  else:
    let half = w div 2
    if i <= half: Tree[T](elem: t.elem, left: updateTree(half, t.left, i - 1, x), right: t.right)
    else: Tree[T](elem: t.elem, left: t.left, right: updateTree(half, t.right, i - 1 - half, x))

func get*[T](xs: SkewList[T]; i: int): Option[T] {.raises: [].} =
  ## Element at index `i` (0 is the head); none when out of range.
  if i < 0 or i >= xs.size: return none(T)
  var offset = i
  for e in items(xs.spine):
    if offset < e.weight: return some(lookupTree(e.weight, e.tree, offset))
    offset -= e.weight
  none(T)

func updated*[T](xs: SkewList[T]; i: int; x: T): Option[SkewList[T]] {.raises: [].} =
  ## A copy with index `i` replaced; none when out of range. Shares every untouched tree.
  if i < 0 or i >= xs.size: return none(SkewList[T])
  var before: seq[Entry[T]]
  var offset = i
  var cur = xs.spine
  while not cur.isEmpty:
    let e = cur.head.get
    if offset < e.weight:
      var spine = cur.tail.cons(Entry[T](weight: e.weight, tree: updateTree(e.weight, e.tree, offset, x)))
      for j in countdown(before.high, 0):
        spine = spine.cons(before[j])
      return some(SkewList[T](spine: spine, size: xs.size))
    offset -= e.weight
    before.add e
    cur = cur.tail
  none(SkewList[T])

func toSeq*[T](xs: SkewList[T]): seq[T] {.raises: [].} =
  var cur = xs
  while not cur.isEmpty:
    result.add cur.head.get
    cur = cur.tail

func fromSeq*[T](items: openArray[T]): SkewList[T] {.raises: [].} =
  var acc = emptySkew[T]()
  for i in countdown(items.high, 0):
    acc = acc.cons(items[i])
  acc

func weights*[T](xs: SkewList[T]): seq[int] {.raises: [].} =
  ## Sizes of the trees in the spine, front first.
  for e in items(xs.spine):
    result.add e.weight

func invariantsHold*[T](xs: SkewList[T]): bool {.raises: [].} =
  ## Weights are 2^k - 1, non-decreasing, strictly increasing after the first two, and they sum to len.
  let ws = xs.weights
  var total = 0
  for i, w in ws:
    if ((w + 1) and w) != 0: return false
    if i >= 1 and w < ws[i - 1]: return false
    if i >= 2 and w == ws[i - 1]: return false
    total += w
  total == xs.size

## Persistent splay tree: a binary search tree that moves the key it just touched to the root.
##
## A classic splay tree rearranges itself on every read, which a persistent value cannot do in
## place. Here `lookup` returns the new tree next to the answer, as `tuple[found: bool, tree:
## SplayTree[K]]`, and the caller keeps using the returned tree. The splay itself is the usual
## zig, zig-zig and zig-zag rotations, written as a recursion that copies the path it walks.
## Amortized O(log n) per operation holds only for a sequence of operations where each uses the
## tree the previous one returned. A single version used again and again has no such bound: its
## deepest key costs O(n) every time. Use it for access patterns with locality (the same few keys
## asked for repeatedly) in single-threaded code; use `rb_tree` or `treap` when any version may be
## queried at any time. The key type needs `<`.

import std/options

type
  NodeObj[K] = object
    key: K
    left, right: Node[K]
  Node[K] = ref NodeObj[K]
  SplayTree*[K] = object
    root: Node[K]
    size: int

proc `=destroy`[K](n: var NodeObj[K]) =
  ## A splay tree can be a chain as long as it is large (ascending inserts), so the default
  ## destructor would recurse once per node. A work list frees the nodes this tree owns alone; a
  ## node still reachable from another version (`isUniqueRef` is false) is left to its last owner.
  var pending: seq[Node[K]]
  if not n.left.isNil: pending.add move(n.left)
  if not n.right.isNil: pending.add move(n.right)
  while pending.len > 0:
    let c = pending.pop
    if isUniqueRef(c):
      if not c.left.isNil: pending.add move(c.left)
      if not c.right.isNil: pending.add move(c.right)
  reset(n.key)

func emptyTree*[K](): SplayTree[K] {.raises: [].} =
  SplayTree[K]()

func len*[K](t: SplayTree[K]): int {.raises: [].} =
  t.size

func isEmpty*[K](t: SplayTree[K]): bool {.raises: [].} =
  t.root.isNil

func mk[K](key: K; l, r: Node[K]): Node[K] =
  Node[K](key: key, left: l, right: r)

func splayNode[K](n: Node[K]; key: K): Node[K] =
  ## Rebuilds the tree so that `key`, or the last node visited when it is absent, is the root.
  if n.isNil: return n
  if key < n.key:
    let x = n.left
    if x.isNil: return n
    if key < x.key:                      # zig-zig: both steps go left
      let t = splayNode(x.left, key)
      if t.isNil: mk(x.key, x.left, mk(n.key, x.right, n.right))
      else: mk(t.key, t.left, mk(x.key, t.right, mk(n.key, x.right, n.right)))
    elif x.key < key:                    # zig-zag: left, then right
      let t = splayNode(x.right, key)
      if t.isNil: mk(x.key, x.left, mk(n.key, x.right, n.right))
      else: mk(t.key, mk(x.key, x.left, t.left), mk(n.key, t.right, n.right))
    else:                                # zig: the key is the left child
      mk(x.key, x.left, mk(n.key, x.right, n.right))
  elif n.key < key:
    let x = n.right
    if x.isNil: return n
    if x.key < key:                      # zig-zig: both steps go right
      let t = splayNode(x.right, key)
      if t.isNil: mk(x.key, mk(n.key, n.left, x.left), x.right)
      else: mk(t.key, mk(x.key, mk(n.key, n.left, x.left), t.left), t.right)
    elif key < x.key:                    # zig-zag: right, then left
      let t = splayNode(x.left, key)
      if t.isNil: mk(x.key, mk(n.key, n.left, x.left), x.right)
      else: mk(t.key, mk(n.key, n.left, t.left), mk(x.key, t.right, x.right))
    else:                                # zig: the key is the right child
      mk(x.key, mk(n.key, n.left, x.left), x.right)
  else:
    n

func lookup*[K](t: SplayTree[K]; key: K): tuple[found: bool, tree: SplayTree[K]] {.raises: [].} =
  ## Looks `key` up and returns the tree with the touched node moved to the root. Keep using
  ## `tree`: that is what makes the amortized bound hold. When `key` is absent the last node
  ## visited is splayed instead, which keeps the bound for failed searches too.
  let r = splayNode(t.root, key)
  let hit = not r.isNil and not (key < r.key) and not (r.key < key)
  (hit, SplayTree[K](root: r, size: t.size))

func contains*[K](t: SplayTree[K]; key: K): bool {.raises: [].} =
  ## A read that does not adapt the tree: it walks without copying and leaves `t` as it is. It
  ## answers the same as `lookup(key).found` but gives up the locality gain.
  var n = t.root
  while not n.isNil:
    if key < n.key: n = n.left
    elif n.key < key: n = n.right
    else: return true
  false

func insert*[K](t: SplayTree[K]; key: K): SplayTree[K] {.raises: [].} =
  ## Adds `key` and leaves it at the root. A key that is present is only splayed to the root, so
  ## the key set is unchanged (idempotent on the set).
  let r = splayNode(t.root, key)
  if r.isNil:
    return SplayTree[K](root: mk(key, nil, nil), size: 1)
  if key < r.key:
    SplayTree[K](root: mk(key, r.left, mk(r.key, nil, r.right)), size: t.size + 1)
  elif r.key < key:
    SplayTree[K](root: mk(key, mk(r.key, r.left, nil), r.right), size: t.size + 1)
  else:
    SplayTree[K](root: r, size: t.size)

func delete*[K](t: SplayTree[K]; key: K): SplayTree[K] {.raises: [].} =
  ## Removes `key`; an absent key leaves the key set unchanged (the tree is splayed to the last
  ## node visited).
  let r = splayNode(t.root, key)
  if r.isNil or key < r.key or r.key < key:
    return SplayTree[K](root: r, size: t.size)
  if r.left.isNil:
    return SplayTree[K](root: r.right, size: t.size - 1)
  # `key` is larger than everything on the left, so splaying it brings the left maximum to the
  # root with an empty right side; the old right subtree hangs there.
  let l = splayNode(r.left, key)
  SplayTree[K](root: mk(l.key, l.left, r.right), size: t.size - 1)

func fromSeq*[K](items: openArray[K]): SplayTree[K] {.raises: [].} =
  var t = emptyTree[K]()
  for x in items:
    t = t.insert(x)
  t

func rootKey*[K](t: SplayTree[K]): Option[K] {.raises: [].} =
  if t.root.isNil: none(K) else: some(t.root.key)

func depthOf*[K](t: SplayTree[K]; key: K): Option[int] {.raises: [].} =
  ## Number of edges from the root to `key`, or none when absent. Does not splay.
  var n = t.root
  var d = 0
  while not n.isNil:
    if key < n.key: n = n.left
    elif n.key < key: n = n.right
    else: return some(d)
    inc d
  none(int)

func collect[K](n: Node[K]; acc: var seq[K]) =
  if not n.isNil:
    collect(n.left, acc)
    acc.add n.key
    collect(n.right, acc)

func toSeq*[K](t: SplayTree[K]): seq[K] {.raises: [].} =
  ## The keys in ascending order.
  collect(t.root, result)

func invariantsHold*[K](t: SplayTree[K]): bool {.raises: [].} =
  ## Keys strictly increasing and the stored size equal to the number of nodes.
  let keys = t.toSeq
  if keys.len != t.size: return false
  for i in 1 ..< keys.len:
    if not (keys[i - 1] < keys[i]): return false
  true

## Stack (last in, first out) and queue (first in, first out) as values, plus the monotonic stack.
##
## `Stack[T]` wraps a `seq` used from its end; `Queue[T]` wraps a `std/deques` ring buffer. Both are
## value types (ADR-NCK-0002): `push`, `pop`, `enqueue` and `dequeue` return a new container and
## copy the storage, O(n), so keep a `var` local to one routine when you need the O(1) amortized
## in-place operations (the monotonic stack below does exactly that). When old versions must stay
## cheap, use `cons_list` as a persistent stack and `bankers_queue` as a persistent queue.
## `nextGreaterIndex` is the monotonic-stack technique: scan once while a stack of indices keeps its
## values decreasing, and every index leaves the stack exactly when its answer is found.

import std/[options, deques]

type
  Stack*[T] = object
    items: seq[T]       ## the top of the stack is the last element
  Queue*[T] = object
    buf: Deque[T]       ## the front of the queue is the first element

func emptyStack*[T](): Stack[T] {.raises: [].} =
  Stack[T]()

func len*[T](s: Stack[T]): int {.raises: [].} =
  s.items.len

func isEmpty*[T](s: Stack[T]): bool {.raises: [].} =
  s.items.len == 0

func push*[T](s: Stack[T]; x: T): Stack[T] {.raises: [].} =
  Stack[T](items: s.items & @[x])

func top*[T](s: Stack[T]): Option[T] {.raises: [].} =
  if s.items.len == 0: none(T) else: some(s.items[s.items.len - 1])

func pop*[T](s: Stack[T]): Stack[T] {.raises: [].} =
  ## The stack without its top item; the empty stack stays empty.
  if s.items.len == 0: s
  else: Stack[T](items: s.items[0 ..< s.items.len - 1])

func toSeq*[T](s: Stack[T]): seq[T] {.raises: [].} =
  ## The items from the top down to the bottom (the order `pop` would return them).
  result = newSeq[T](s.items.len)
  for i in 0 ..< s.items.len:
    result[i] = s.items[s.items.len - 1 - i]

func emptyQueue*[T](): Queue[T] {.raises: [].} =
  Queue[T](buf: initDeque[T]())

func len*[T](q: Queue[T]): int {.raises: [].} =
  q.buf.len

func isEmpty*[T](q: Queue[T]): bool {.raises: [].} =
  q.buf.len == 0

func enqueue*[T](q: Queue[T]; x: T): Queue[T] {.raises: [].} =
  var d = q.buf
  d.addLast x
  Queue[T](buf: d)

func front*[T](q: Queue[T]): Option[T] {.raises: [].} =
  if q.buf.len == 0: none(T) else: some(q.buf.peekFirst)

func dequeue*[T](q: Queue[T]): Queue[T] {.raises: [].} =
  ## The queue without its front item; the empty queue stays empty.
  if q.buf.len == 0: q
  else:
    var d = q.buf
    d.popFirst
    Queue[T](buf: d)

func toSeq*[T](q: Queue[T]): seq[T] {.raises: [].} =
  ## The items from the front to the back (the order `dequeue` would return them).
  for i in 0 ..< q.buf.len:
    result.add q.buf[i]

func nextGreaterIndex*[T](xs: openArray[T]): seq[Option[int]] {.raises: [].} =
  ## For each position `i`, the index of the nearest later element that is strictly greater than
  ## `xs[i]`, or `none` when there is none. O(n): each index is pushed and popped at most once.
  result = newSeq[Option[int]](xs.len)
  var pending: seq[int]           # indices still waiting, their values non-increasing from bottom to top
  for i in 0 ..< xs.len:
    while pending.len > 0 and xs[pending[pending.len - 1]] < xs[i]:
      result[pending.pop] = some(i)
    pending.add i

func nextGreater*[T](xs: openArray[T]): seq[Option[T]] {.raises: [].} =
  ## Like `nextGreaterIndex`, but gives the greater value instead of its index.
  let idx = nextGreaterIndex(xs)
  result = newSeq[Option[T]](xs.len)
  for i in 0 ..< xs.len:
    if idx[i].isSome: result[i] = some(xs[idx[i].get])

## Naive suffix trie for small texts: substring counts, distinct substrings, longest repeat.
##
## This is not a suffix tree. A suffix tree compresses unary paths and is built in O(n) by
## Ukkonen's algorithm, which needs suffix links and shared mutable end indices; that does not fit
## the persistent, value-only style of this repository without losing the O(n) bound. This module
## instead inserts every suffix of the text into a plain trie (one node per character), which is
## simple, immutable and obviously correct, but takes O(n^2) nodes: `buildSuffixTrie` refuses texts
## longer than `maxTextLen`. Each node stores how many suffixes pass through it, which equals the
## number of (possibly overlapping) occurrences of the string spelled by the path. Use it to learn
## what a suffix tree answers and to test other implementations on short strings; for real texts
## use `suffix_array` in `nimcs/algo`.

import nimcs/fp/result

const maxTextLen* = 400
  ## Longest text accepted; the trie of a text of length n has up to n(n+1)/2 nodes.

type
  Node = ref object
    count: int                                        ## suffixes passing through this node
    kids: seq[tuple[c: char, child: Node]]            ## sorted by character
  SuffixTrie* = object
    root: Node
    textLen: int
  TrieError* = enum
    textTooLong   ## the text is longer than `maxTextLen`

func childOf(n: Node; c: char): Node =
  for k in n.kids:
    if k.c == c: return k.child
  nil

func withChild(kids: seq[tuple[c: char, child: Node]]; c: char; child: Node): seq[tuple[c: char, child: Node]] =
  ## A copy of `kids` where the entry for `c` is `child`, keeping the order by character.
  var placed = false
  for k in kids:
    if k.c == c:
      result.add (c: c, child: child)
      placed = true
    elif not placed and c < k.c:
      result.add (c: c, child: child)
      result.add k
      placed = true
    else:
      result.add k
  if not placed:
    result.add (c: c, child: child)

func insertSuffix(n: Node; text: string; i: int): Node =
  ## A copy of `n` with the suffix `text[i..]` added; the untouched subtrees are shared.
  if i >= text.len:
    return Node(count: n.count, kids: n.kids)
  let c = text[i]
  let old = childOf(n, c)
  let base = if old.isNil: Node() else: old
  let below = insertSuffix(base, text, i + 1)
  let counted = Node(count: base.count + 1, kids: below.kids)
  Node(count: n.count, kids: withChild(n.kids, c, counted))

func buildSuffixTrie*(text: string): Result[SuffixTrie, TrieError] {.raises: [].} =
  ## Builds the trie of all suffixes of `text` (bytes are the characters). Fails with
  ## `textTooLong` above `maxTextLen`.
  if text.len > maxTextLen:
    return err(SuffixTrie, textTooLong)
  var root = Node()
  for i in 0 ..< text.len:
    root = insertSuffix(root, text, i)
  ok(SuffixTrie(root: root, textLen: text.len), TrieError)

func textLen*(t: SuffixTrie): int {.raises: [].} =
  t.textLen

func walk(t: SuffixTrie; s: string): Node =
  var n = t.root
  for c in s:
    n = childOf(n, c)
    if n.isNil: return nil
  n

func count*(t: SuffixTrie; sub: string): int {.raises: [].} =
  ## How many times `sub` occurs in the text, overlapping occurrences included. The empty string
  ## occurs `textLen + 1` times (once at every position, end included), as in a naive scan.
  if sub.len == 0: return t.textLen + 1
  let n = walk(t, sub)
  if n.isNil: 0 else: n.count

func contains*(t: SuffixTrie; sub: string): bool {.raises: [].} =
  not walk(t, sub).isNil

func countNodes(n: Node): int =
  result = 1
  for k in n.kids:
    result += countNodes(k.child)

func distinctSubstrings*(t: SuffixTrie): int {.raises: [].} =
  ## The number of different non-empty substrings: every node except the root is one.
  countNodes(t.root) - 1

func deepestRepeat(n: Node; path: string): string =
  ## The longest string below `n` with count >= 2, smallest first among equal lengths because the
  ## children are visited in character order and only a strictly longer one replaces the best.
  result = path
  for k in n.kids:
    if k.child.count >= 2:
      let cand = deepestRepeat(k.child, path & k.c)
      if cand.len > result.len:
        result = cand

func longestRepeated*(t: SuffixTrie): string {.raises: [].} =
  ## The longest substring that occurs at least twice (occurrences may overlap); among equally
  ## long ones the lexicographically smallest. Empty when no character repeats.
  deepestRepeat(t.root, "")

func shortestAbsent*(t: SuffixTrie; alphabet: string): string {.raises: [].} =
  ## The shortest string over `alphabet` that is not a substring of the text; among equally short
  ## ones the smallest in the order of `alphabet`. `alphabet` must be non-empty and have distinct
  ## characters; an empty `alphabet` gives "".
  if alphabet.len == 0: return ""
  var level: seq[tuple[s: string, n: Node]] = @[(s: "", n: t.root)]
  while true:
    var nextLevel: seq[tuple[s: string, n: Node]]
    for (s, n) in level:
      for c in alphabet:
        let child = childOf(n, c)
        if child.isNil: return s & c
        nextLevel.add (s: s & c, n: child)
    level = nextLevel

## Persistent treap: an ordered set whose balance comes from priorities derived from a seed.
##
## A treap is a binary search tree on the keys that is also a max-heap on a priority stored in each
## node. Here the priority is not drawn from a random generator: it is a fixed mixing function of
## the seed and the key, so the same seed and the same key set always give the same tree, whatever
## order the keys were inserted in. With priorities that behave like random numbers the expected
## height is O(log n). All updates are `split` and `merge`, which copy only the path they walk and
## share the rest, so every earlier version stays valid. Use it for an ordered set that also needs
## cheap `split` and `merge` (cutting a key range off, joining two disjoint sets); use `rb_tree`
## when a worst-case height bound matters more than the simple code. The key type needs `<` and
## `hash`.

import std/[hashes, options]
import nimcs/fp/result

type
  Node[K] = ref object
    key: K
    prio: uint64
    size: int
    left, right: Node[K]
  Treap*[K] = object
    root: Node[K]
    seed: uint64
  TreapError* = enum
    seedMismatch   ## the two treaps were made with different seeds, so their priorities disagree
    keysOverlap    ## some key of the left treap is not smaller than every key of the right one

func mix64(z0: uint64): uint64 =
  ## A bijective 64-bit finaliser (the splitmix64 steps); unsigned arithmetic wraps by definition.
  var z = z0 + 0x9E3779B97F4A7C15'u64
  z = (z xor (z shr 30)) * 0xBF58476D1CE4E5B9'u64
  z = (z xor (z shr 27)) * 0x94D049BB133111EB'u64
  z xor (z shr 31)

func priorityOf[K](seed: uint64; key: K): uint64 =
  ## The masked hash is non-negative, so the conversion to `uint64` keeps its value.
  mix64(seed xor mix64(uint64(int(hash(key)) and high(int))))

func emptyTreap*[K](seed: uint64 = 0'u64): Treap[K] {.raises: [].} =
  ## An empty treap whose priorities will all be derived from `seed`.
  Treap[K](seed: seed)

func seed*[K](t: Treap[K]): uint64 {.raises: [].} =
  t.seed

func sizeOf[K](n: Node[K]): int =
  if n.isNil: 0 else: n.size

func mk[K](key: K; prio: uint64; l, r: Node[K]): Node[K] =
  Node[K](key: key, prio: prio, size: 1 + sizeOf(l) + sizeOf(r), left: l, right: r)

func len*[K](t: Treap[K]): int {.raises: [].} =
  sizeOf(t.root)

func isEmpty*[K](t: Treap[K]): bool {.raises: [].} =
  t.root.isNil

func contains*[K](t: Treap[K]; key: K): bool {.raises: [].} =
  var n = t.root
  while not n.isNil:
    if key < n.key: n = n.left
    elif n.key < key: n = n.right
    else: return true
  false

func splitNodes[K](n: Node[K]; key: K): tuple[less: Node[K], found: bool, greater: Node[K]] =
  if n.isNil: (nil, false, nil)
  elif key < n.key:
    let s = splitNodes(n.left, key)
    (s.less, s.found, mk(n.key, n.prio, s.greater, n.right))
  elif n.key < key:
    let s = splitNodes(n.right, key)
    (mk(n.key, n.prio, n.left, s.less), s.found, s.greater)
  else:
    (n.left, true, n.right)

func mergeNodes[K](a, b: Node[K]): Node[K] =
  ## Every key of `a` must be smaller than every key of `b`.
  if a.isNil: b
  elif b.isNil: a
  elif a.prio >= b.prio: mk(a.key, a.prio, a.left, mergeNodes(a.right, b))
  else: mk(b.key, b.prio, mergeNodes(a, b.left), b.right)

func split*[K](t: Treap[K]; key: K): tuple[less: Treap[K], found: bool, greater: Treap[K]] {.raises: [].} =
  ## Cuts `t` at `key`: the keys below it, whether `key` was present, and the keys above it.
  let s = splitNodes(t.root, key)
  (Treap[K](root: s.less, seed: t.seed), s.found, Treap[K](root: s.greater, seed: t.seed))

func minKey*[K](t: Treap[K]): Option[K] {.raises: [].} =
  var n = t.root
  if n.isNil: return none(K)
  while not n.left.isNil:
    n = n.left
  some(n.key)

func maxKey*[K](t: Treap[K]): Option[K] {.raises: [].} =
  var n = t.root
  if n.isNil: return none(K)
  while not n.right.isNil:
    n = n.right
  some(n.key)

func merge*[K](a, b: Treap[K]): Result[Treap[K], TreapError] {.raises: [].} =
  ## Joins two treaps made with the same seed whose key ranges do not overlap (all of `a` below
  ## all of `b`). Anything else is reported, never merged into a broken tree.
  if a.seed != b.seed:
    return err(Treap[K], seedMismatch)
  let hi = a.maxKey
  let lo = b.minKey
  if hi.isSome and lo.isSome and not (hi.get < lo.get):
    return err(Treap[K], keysOverlap)
  ok(Treap[K](root: mergeNodes(a.root, b.root), seed: a.seed), TreapError)

func insert*[K](t: Treap[K]; key: K): Treap[K] {.raises: [].} =
  ## Adds `key`; inserting a key that is present returns `t` itself (idempotent).
  let s = splitNodes(t.root, key)
  if s.found: return t
  let middle = mk(key, priorityOf(t.seed, key), nil, nil)
  Treap[K](root: mergeNodes(mergeNodes(s.less, middle), s.greater), seed: t.seed)

func delete*[K](t: Treap[K]; key: K): Treap[K] {.raises: [].} =
  ## Removes `key`; removing an absent key returns `t` itself (idempotent).
  let s = splitNodes(t.root, key)
  if not s.found: return t
  Treap[K](root: mergeNodes(s.less, s.greater), seed: t.seed)

func fromSeq*[K](seed: uint64; items: openArray[K]): Treap[K] {.raises: [].} =
  var t = emptyTreap[K](seed)
  for x in items:
    t = t.insert(x)
  t

func collect[K](n: Node[K]; acc: var seq[K]) =
  if not n.isNil:
    collect(n.left, acc)
    acc.add n.key
    collect(n.right, acc)

func toSeq*[K](t: Treap[K]): seq[K] {.raises: [].} =
  ## The keys in ascending order.
  collect(t.root, result)

func collectPre[K](n: Node[K]; acc: var seq[K]) =
  if not n.isNil:
    acc.add n.key
    collectPre(n.left, acc)
    collectPre(n.right, acc)

func preorder*[K](t: Treap[K]): seq[K] {.raises: [].} =
  ## The keys in root-first order: two treaps have the same shape exactly when this agrees.
  collectPre(t.root, result)

func heightOf[K](n: Node[K]): int =
  if n.isNil: 0 else: 1 + max(heightOf(n.left), heightOf(n.right))

func height*[K](t: Treap[K]): int {.raises: [].} =
  heightOf(t.root)

func invariantsHold*[K](t: Treap[K]): bool {.raises: [].} =
  ## Keys strictly increasing, priorities equal to the seeded function of the key and not growing
  ## towards the leaves, and every stored size correct.
  func local(n: Node[K]; seed: uint64): bool =
    if n.isNil: true
    else:
      n.prio == priorityOf(seed, n.key) and n.size == 1 + sizeOf(n.left) + sizeOf(n.right) and
        (n.left.isNil or n.left.prio <= n.prio) and (n.right.isNil or n.right.prio <= n.prio) and
        local(n.left, seed) and local(n.right, seed)
  let keys = t.toSeq
  for i in 1 ..< keys.len:
    if not (keys[i - 1] < keys[i]): return false
  local(t.root, t.seed)

## Persistent string trie: a set of words stored as a tree of characters.
##
## Each node has a flag "a word ends here" and children sorted by character. `insert` copies the
## nodes along the word (one per character) and shares every other branch. `contains` costs
## O(length of the word); `keysWithPrefix` walks to the prefix and lists the words below it in
## sorted (byte-wise) order. Recursion depth equals the word length (a release build handles words of
## tens of thousands of characters, a debug build about 2,000). Use it for autocompletion and prefix search; use `hamt` or `rb_tree`
## when you only need whole-key lookup.

type
  Node = ref object
    terminal: bool
    kids: seq[(char, Node)]   ## sorted by char, one entry per char
  Trie* = object
    root: Node
    count: int

func emptyTrie*(): Trie {.raises: [].} =
  Trie()

func len*(t: Trie): int {.raises: [].} =
  ## Number of distinct words.
  t.count

func isEmpty*(t: Trie): bool {.raises: [].} =
  t.count == 0

func childIndex(n: Node; c: char): int =
  ## Index of `c` in `n.kids`, or -1.
  for i, kid in n.kids:
    if kid[0] == c: return i
    if kid[0] > c: return -1
  -1

func walk(root: Node; s: string): Node =
  ## The node reached by `s`, or nil.
  var n = root
  for c in s:
    if n.isNil: return nil
    let i = childIndex(n, c)
    if i < 0: return nil
    n = n.kids[i][1]
  n

func contains*(t: Trie; word: string): bool {.raises: [].} =
  let n = walk(t.root, word)
  not n.isNil and n.terminal

func hasPrefix*(t: Trie; prefix: string): bool {.raises: [].} =
  ## True when at least one stored word starts with `prefix` (the word itself counts).
  let n = walk(t.root, prefix)
  not n.isNil and (n.terminal or n.kids.len > 0)

func insertAt(n: Node; word: string; i: int): Node =
  let base = if n.isNil: Node() else: n
  if i == word.len: return Node(terminal: true, kids: base.kids)
  let c = word[i]
  var kids = base.kids
  let at = childIndex(base, c)
  if at >= 0:
    kids[at] = (c, insertAt(base.kids[at][1], word, i + 1))
  else:
    var pos = kids.len
    for j, kid in kids:
      if kid[0] > c:
        pos = j
        break
    kids.insert((c, insertAt(nil, word, i + 1)), pos)
  Node(terminal: base.terminal, kids: kids)

func insert*(t: Trie; word: string): Trie {.raises: [].} =
  ## Adds `word`; adding a word that is already present gives an equal trie.
  if t.contains(word): t
  else: Trie(root: insertAt(t.root, word, 0), count: t.count + 1)

func collect(n: Node; prefix: string; into: var seq[string]) =
  if n.terminal: into.add prefix
  for kid in n.kids:
    collect(kid[1], prefix & kid[0], into)

func keysWithPrefix*(t: Trie; prefix: string): seq[string] {.raises: [].} =
  ## Every stored word that starts with `prefix`, in sorted order. The empty prefix lists all words.
  let n = walk(t.root, prefix)
  if not n.isNil:
    collect(n, prefix, result)

func toSeq*(t: Trie): seq[string] {.raises: [].} =
  t.keysWithPrefix("")

func fromSeq*(words: openArray[string]): Trie {.raises: [].} =
  var t = emptyTrie()
  for w in words:
    t = t.insert(w)
  t

## Persistent union-find (disjoint sets) built on a persistent map.
##
## The classic imperative version keeps parents in an array and compresses paths while it finds,
## giving near-constant amortized time but destroying the old state. Here the parent and rank
## tables are `RbMap`s, so `union` returns a new structure and every earlier version stays
## usable (backtracking, undo, speculative merges). Union by rank alone bounds a root path by
## log2(n), so `find` is O(log n * log n) with the map lookups; `findCompress` also returns the
## compressed structure, which you must keep to benefit. Use it when you need old versions;
## use an array with path compression when only the latest state matters and speed counts.

import std/options
import nimcs/ds/rb_tree

type
  UnionFind* = object
    parent: RbMap[int, int]
    rank: RbMap[int, int]
    sets: int

func emptyUnionFind*(): UnionFind {.raises: [].} =
  UnionFind()

func components*(u: UnionFind): int {.raises: [].} =
  ## Number of disjoint sets among the elements seen so far.
  u.sets

func len*(u: UnionFind): int {.raises: [].} =
  ## Number of elements seen so far.
  u.parent.len

func contains*(u: UnionFind; x: int): bool {.raises: [].} =
  u.parent.contains(x)

func add*(u: UnionFind; x: int): UnionFind {.raises: [].} =
  ## Registers `x` as a singleton set; no change when it is already known.
  if u.contains(x): u
  else: UnionFind(parent: u.parent.put(x, x), rank: u.rank.put(x, 0), sets: u.sets + 1)

func parentOf(u: UnionFind; x: int): int =
  let p = u.parent.get(x)
  if p.isSome: p.get else: x

func find*(u: UnionFind; x: int): int {.raises: [].} =
  ## The representative of the set of `x`; an unknown element is its own representative.
  var cur = x
  while true:
    let p = u.parentOf(cur)
    if p == cur: return cur
    cur = p

func findCompress*(u: UnionFind; x: int): (int, UnionFind) {.raises: [].} =
  ## Like `find`, and also returns the structure with every node on the path pointing at the root.
  let root = u.find(x)
  var parent = u.parent
  var cur = x
  while cur != root and parent.get(cur).isSome:
    let p = parent.get(cur).get
    if p != root: parent = parent.put(cur, root)
    cur = p
  (root, UnionFind(parent: parent, rank: u.rank, sets: u.sets))

func rankOf(u: UnionFind; x: int): int =
  let r = u.rank.get(x)
  if r.isSome: r.get else: 0

func union*(u: UnionFind; a, b: int): UnionFind {.raises: [].} =
  ## Merges the sets of `a` and `b` (adding unknown elements first); idempotent.
  let base = u.add(a).add(b)
  let ra = base.find(a)
  let rb = base.find(b)
  if ra == rb: return base
  let rka = base.rankOf(ra)
  let rkb = base.rankOf(rb)
  if rka < rkb:
    UnionFind(parent: base.parent.put(ra, rb), rank: base.rank, sets: base.sets - 1)
  elif rkb < rka:
    UnionFind(parent: base.parent.put(rb, ra), rank: base.rank, sets: base.sets - 1)
  else:
    UnionFind(parent: base.parent.put(rb, ra), rank: base.rank.put(ra, rka + 1), sets: base.sets - 1)

func same*(u: UnionFind; a, b: int): bool {.raises: [].} =
  u.find(a) == u.find(b)

func pathLength*(u: UnionFind; x: int): int {.raises: [].} =
  ## Number of parent links from `x` to its representative.
  var cur = x
  while true:
    let p = u.parentOf(cur)
    if p == cur: return result
    cur = p
    inc result

## Zippers: a cursor into an immutable list or binary tree.
##
## A zipper is the data structure turned inside out around one focus: the part you have passed
## is kept in reverse, ready to be put back. Moving the focus and replacing the focused element
## are O(1); rebuilding the whole structure costs one step per level you went down. Nothing is
## mutated: every move or edit gives a new zipper that shares the rest. Use it for editors,
## parsers that backtrack and tree rewriting where "change this place and keep everything else"
## is the operation; use plain recursion when you transform every node.

import std/options
import nimcs/ds/cons_list

type
  ListZipper*[T] = object
    before: ConsList[T]     ## elements left of the focus, nearest first
    focus: T
    after: ConsList[T]      ## elements right of the focus, nearest first

  Tree*[T] = object
    node: Node[T]           ## nil is the empty tree
  Node[T] = ref object
    value: T
    left, right: Tree[T]

  Direction = enum
    goLeft, goRight
  Crumb[T] = object
    dir: Direction          ## which child the focus is
    value: T                ## the parent's value
    other: Tree[T]          ## the sibling subtree
  TreeZipper*[T] = object
    focus: Tree[T]
    trail: ConsList[Crumb[T]]

# ---- list zipper ------------------------------------------------------------------------------

func zipList*[T](items: openArray[T]): Option[ListZipper[T]] {.raises: [].} =
  ## A zipper focused on the first element; none for an empty list.
  if items.len == 0: none(ListZipper[T])
  else: some(ListZipper[T](before: emptyList[T](), focus: items[0],
    after: fromSeq(items.toOpenArray(1, items.high))))

func focus*[T](z: ListZipper[T]): T {.raises: [].} =
  z.focus

func moveRight*[T](z: ListZipper[T]): Option[ListZipper[T]] {.raises: [].} =
  let next = z.after.head
  if next.isNone: none(ListZipper[T])
  else: some(ListZipper[T](before: z.before.cons(z.focus), focus: next.get, after: z.after.tail))

func moveLeft*[T](z: ListZipper[T]): Option[ListZipper[T]] {.raises: [].} =
  let prev = z.before.head
  if prev.isNone: none(ListZipper[T])
  else: some(ListZipper[T](before: z.before.tail, focus: prev.get, after: z.after.cons(z.focus)))

func setFocus*[T](z: ListZipper[T]; x: T): ListZipper[T] {.raises: [].} =
  ListZipper[T](before: z.before, focus: x, after: z.after)

func modify*[T](z: ListZipper[T]; f: proc(x: T): T {.noSideEffect, raises: [].}): ListZipper[T] {.raises: [].} =
  z.setFocus(f(z.focus))

func toSeq*[T](z: ListZipper[T]): seq[T] {.raises: [].} =
  ## The whole list, rebuilt.
  z.before.reverse.toSeq & @[z.focus] & z.after.toSeq

func position*[T](z: ListZipper[T]): int {.raises: [].} =
  ## Index of the focus.
  z.before.len

# ---- binary tree ------------------------------------------------------------------------------

func leaf*[T](): Tree[T] {.raises: [].} =
  Tree[T]()

func branch*[T](left: Tree[T]; value: T; right: Tree[T]): Tree[T] {.raises: [].} =
  Tree[T](node: Node[T](value: value, left: left, right: right))

func isLeaf*[T](t: Tree[T]): bool {.raises: [].} =
  t.node.isNil

func value*[T](t: Tree[T]): Option[T] {.raises: [].} =
  if t.isLeaf: none(T) else: some(t.node.value)

func `==`*[T](a, b: Tree[T]): bool {.raises: [].} =
  if a.isLeaf or b.isLeaf: a.isLeaf and b.isLeaf
  else: a.node.value == b.node.value and a.node.left == b.node.left and a.node.right == b.node.right

func toSeq*[T](t: Tree[T]): seq[T] {.raises: [].} =
  ## In-order traversal.
  if t.isLeaf: return
  result = t.node.left.toSeq & @[t.node.value] & t.node.right.toSeq

func zipTree*[T](t: Tree[T]): TreeZipper[T] {.raises: [].} =
  TreeZipper[T](focus: t, trail: emptyList[Crumb[T]]())

func focusTree*[T](z: TreeZipper[T]): Tree[T] {.raises: [].} =
  z.focus

func downLeft*[T](z: TreeZipper[T]): Option[TreeZipper[T]] {.raises: [].} =
  ## Moves to the left child; none at a leaf.
  if z.focus.isLeaf: none(TreeZipper[T])
  else:
    let n = z.focus.node
    some(TreeZipper[T](focus: n.left,
      trail: z.trail.cons(Crumb[T](dir: goLeft, value: n.value, other: n.right))))

func downRight*[T](z: TreeZipper[T]): Option[TreeZipper[T]] {.raises: [].} =
  if z.focus.isLeaf: none(TreeZipper[T])
  else:
    let n = z.focus.node
    some(TreeZipper[T](focus: n.right,
      trail: z.trail.cons(Crumb[T](dir: goRight, value: n.value, other: n.left))))

func up*[T](z: TreeZipper[T]): Option[TreeZipper[T]] {.raises: [].} =
  ## Moves to the parent, putting the (possibly edited) focus back; none at the root.
  let crumb = z.trail.head
  if crumb.isNone: none(TreeZipper[T])
  else:
    let c = crumb.get
    let rebuilt =
      case c.dir
      of goLeft: branch(z.focus, c.value, c.other)
      of goRight: branch(c.other, c.value, z.focus)
    some(TreeZipper[T](focus: rebuilt, trail: z.trail.tail))

func replace*[T](z: TreeZipper[T]; t: Tree[T]): TreeZipper[T] {.raises: [].} =
  ## Swaps the focused subtree for `t`.
  TreeZipper[T](focus: t, trail: z.trail)

func modify*[T](z: TreeZipper[T]; f: proc(x: T): T {.noSideEffect, raises: [].}): TreeZipper[T] {.raises: [].} =
  ## Applies `f` to the value at the focus; a focused leaf has no value and stays as it is.
  if z.focus.isLeaf: z
  else:
    let n = z.focus.node
    z.replace(branch(n.left, f(n.value), n.right))

func rebuild*[T](z: TreeZipper[T]): Tree[T] {.raises: [].} =
  ## Goes up to the root and returns the whole tree.
  var cur = z
  while true:
    let parent = cur.up
    if parent.isNone: return cur.focus
    cur = parent.get

func depth*[T](z: TreeZipper[T]): int {.raises: [].} =
  ## Number of steps down from the root.
  z.trail.len

## Algebraic data types: a closed set of shapes as an object variant (ADR-NCK-0002 S2, S3).
##
## `Expr` is an arithmetic expression tree: a number, a negation, or a sum, product or quotient of
## two sub-expressions. Every routine over it is a `case` on `kind` with one branch per shape and
## no `else`, so adding a shape to `ExprKind` makes the compiler list every routine that must learn
## about it. Nodes are `ref` to immutable data (S3: `ref` only for recursion); nothing here mutates
## a node after construction. `eval` is total: arithmetic that cannot be done (division by zero,
## `int` overflow) is an `EvalError` value, never an exception.

import nimcs/fp/result

type
  ExprKind* = enum
    ekNum, ekNeg, ekAdd, ekMul, ekDiv

  Expr* = ref object
    case kind*: ExprKind
    of ekNum:
      value*: int
    of ekNeg:
      operand*: Expr
    of ekAdd, ekMul, ekDiv:
      left*, right*: Expr

  EvalError* = enum
    divideByZero, overflow

func num*(n: int): Expr {.raises: [].} = Expr(kind: ekNum, value: n)
func neg*(e: Expr): Expr {.raises: [].} = Expr(kind: ekNeg, operand: e)
func add*(a, b: Expr): Expr {.raises: [].} = Expr(kind: ekAdd, left: a, right: b)
func mul*(a, b: Expr): Expr {.raises: [].} = Expr(kind: ekMul, left: a, right: b)
func divide*(a, b: Expr): Expr {.raises: [].} = Expr(kind: ekDiv, left: a, right: b)

func `==`*(a, b: Expr): bool {.raises: [].} =
  ## Structural equality (the default for `ref` would compare addresses).
  case a.kind
  of ekNum: b.kind == ekNum and a.value == b.value
  of ekNeg: b.kind == ekNeg and a.operand == b.operand
  of ekAdd: b.kind == ekAdd and a.left == b.left and a.right == b.right
  of ekMul: b.kind == ekMul and a.left == b.left and a.right == b.right
  of ekDiv: b.kind == ekDiv and a.left == b.left and a.right == b.right

func addChecked(a, b: int): Result[int, EvalError] {.raises: [].} =
  if (b > 0 and a > high(int) - b) or (b < 0 and a < low(int) - b): err(int, overflow)
  else: ok(a + b, EvalError)

func mulChecked(a, b: int): Result[int, EvalError] {.raises: [].} =
  if a == 0 or b == 0: return ok(0, EvalError)
  let tooBig =
    if a > 0:
      (if b > 0: a > high(int) div b else: b < low(int) div a)
    else:
      (if b > 0: a < low(int) div b else: a < high(int) div b)
  if tooBig: err(int, overflow) else: ok(a * b, EvalError)

func divChecked(a, b: int): Result[int, EvalError] {.raises: [].} =
  if b == 0: err(int, divideByZero)
  elif a == low(int) and b == -1: err(int, overflow)
  else: ok(a div b, EvalError)

func evalWith(e: Expr; op: proc(a, b: int): Result[int, EvalError] {.noSideEffect, raises: [].}):
    Result[int, EvalError] {.raises: [].}

func eval*(e: Expr): Result[int, EvalError] {.raises: [].} =
  ## The value of `e`, or the first error met (left operand before right).
  case e.kind
  of ekNum:
    ok(e.value, EvalError)
  of ekNeg:
    let inner = eval(e.operand)
    if inner.isErr: inner
    elif inner.value == low(int): err(int, overflow)
    else: ok(-inner.value, EvalError)
  of ekAdd: evalWith(e, addChecked)
  of ekMul: evalWith(e, mulChecked)
  of ekDiv: evalWith(e, divChecked)

func evalWith(e: Expr; op: proc(a, b: int): Result[int, EvalError] {.noSideEffect, raises: [].}):
    Result[int, EvalError] {.raises: [].} =
  ## Evaluates both operands of a binary node (left first) and combines them with `op`.
  ## Precondition: `e.kind` is `ekAdd`, `ekMul` or `ekDiv` (only `eval` calls this).
  let l = eval(e.left)
  if l.isErr: return l
  let r = eval(e.right)
  if r.isErr: return r
  op(l.value, r.value)

func size*(e: Expr): int {.raises: [].} =
  ## Number of nodes.
  case e.kind
  of ekNum: 1
  of ekNeg: 1 + size(e.operand)
  of ekAdd, ekMul, ekDiv: 1 + size(e.left) + size(e.right)

func show*(e: Expr): string {.raises: [].} =
  ## Fully parenthesised text, e.g. `(1 + (2 * 3))`; a negation is `neg(...)`, so that
  ## `neg(num(1))` and `num(-1)` print differently (`show` is injective on trees).
  case e.kind
  of ekNum: $e.value
  of ekNeg: "neg(" & show(e.operand) & ")"
  of ekAdd: "(" & show(e.left) & " + " & show(e.right) & ")"
  of ekMul: "(" & show(e.left) & " * " & show(e.right) & ")"
  of ekDiv: "(" & show(e.left) & " / " & show(e.right) & ")"

func `$`*(e: Expr): string {.raises: [].} = show(e)

func isNum(e: Expr; n: int): bool {.raises: [].} =
  e.kind == ekNum and e.value == n

func simplify*(e: Expr): Expr {.raises: [].} =
  ## Rewrites bottom-up: constant folding when it cannot overflow, `0 + x`, `x + 0`, `1 * x`,
  ## `x * 1` and `x / 1` disappear. `--x` is deliberately kept unless `x` is a number: `-x`
  ## overflows for the smallest `int`, so dropping a double negation could turn an error into a value. `eval(simplify(e)) == eval(e)`, and simplifying twice
  ## gives the same tree as simplifying once.
  case e.kind
  of ekNum:
    e
  of ekNeg:
    let x = simplify(e.operand)
    if x.kind == ekNum and x.value != low(int): num(-x.value)
    else: neg(x)
  of ekAdd:
    let a = simplify(e.left)
    let b = simplify(e.right)
    if a.isNum(0): b
    elif b.isNum(0): a
    elif a.kind == ekNum and b.kind == ekNum and addChecked(a.value, b.value).isOk:
      num(a.value + b.value)
    else: add(a, b)
  of ekMul:
    let a = simplify(e.left)
    let b = simplify(e.right)
    if a.isNum(1): b
    elif b.isNum(1): a
    elif a.kind == ekNum and b.kind == ekNum and mulChecked(a.value, b.value).isOk:
      num(a.value * b.value)
    else: mul(a, b)
  of ekDiv:
    let a = simplify(e.left)
    let b = simplify(e.right)
    if b.isNum(1): a
    else: divide(a, b)

## Equational reasoning: refactoring pure code by replacing a form with an equal one
## (ADR-NCK-0002 S1, S6).
##
## In pure code a name can be replaced by its definition and a definition by its name without
## changing the program, so two forms that a short argument shows equal are interchangeable. The
## pairs below are each a staged, readable form and a rewritten form: map/filter/sum fused into
## one pass, an idempotent step removed, a loop replaced by its closed form, a count computed in
## chunks. Each equality is stated as a law and checked on generated inputs; a test is evidence,
## the argument is the proof. The rewrites are valid only for pure functions and exact
## arithmetic: with effects, or with floating point, "equal" forms can differ (`sumLeft`,
## `sumRight`).

import std/[strutils, sequtils]

func stagedTotal*(xs: openArray[int]): int {.raises: [].} =
  ## Sum of `x * 2 + 1` over the even elements, written as separate stages that each build a list.
  let evens = xs.filter(proc(x: int): bool = x mod 2 == 0)
  let doubled = evens.map(proc(x: int): int = x * 2)
  let shifted = doubled.map(proc(x: int): int = x + 1)
  for x in shifted:
    result += x

func fusedTotal*(xs: openArray[int]): int {.raises: [].} =
  ## The same value in one pass: the three stages fused (`map f . map g == map (f . g)`, and
  ## `filter` before `map` becomes a test before the step).
  for x in xs:
    if x mod 2 == 0:
      result += x * 2 + 1

func normalizeStaged*(s: string): string {.raises: [].} =
  ## Strip, lower-case, strip again.
  s.strip.toLowerAscii.strip

func normalizeOnce*(s: string): string {.raises: [].} =
  ## Lower-case, then strip once. Equal to `normalizeStaged`: lower-casing does not change which
  ## characters are whitespace (so it commutes with `strip`), and `strip` is idempotent.
  s.toLowerAscii.strip

func rangeSumLoop*(n: Natural): int {.raises: [].} =
  ## `0 + 1 + ... + n` by a loop. Keep `n` below about 3 * 10^9 so the sum fits in `int`.
  for i in 0 .. n:
    result += i

func rangeSumFormula*(n: Natural): int {.raises: [].} =
  ## The closed form `n * (n + 1) / 2`, equal to `rangeSumLoop(n)` by induction on `n`.
  n * (n + 1) div 2

func countIf*[T](xs: openArray[T]; p: proc(x: T): bool {.noSideEffect, raises: [].}): int {.raises: [].} =
  ## How many elements satisfy `p`.
  for x in xs:
    if p(x):
      inc result

func countIfChunked*[T](xs: openArray[T]; p: proc(x: T): bool {.noSideEffect, raises: [].};
    chunk: Positive): int {.raises: [].} =
  ## The same count computed chunk by chunk and added up. Equal to `countIf` because counting is a
  ## homomorphism from concatenation to addition: `count(a & b) == count(a) + count(b)`.
  var start = 0
  while start < xs.len:
    let stop = min(start + chunk, xs.len)
    result += countIf(xs[start ..< stop], p)
    start = stop

func sumLeft*(xs: openArray[float]): float {.raises: [].} =
  ## Left-to-right sum: `((x0 + x1) + x2) + ...`.
  for x in xs:
    result += x

func sumRight*(xs: openArray[float]): float {.raises: [].} =
  ## Right-to-left sum: `x0 + (x1 + (x2 + ...))`. Not equal to `sumLeft` for floats in general,
  ## because float addition is not associative: reassociating is not an equational step there.
  for i in countdown(xs.high, 0):
    result = xs[i] + result

## Functor, applicative and monad shapes across Nim's container types (ADR-NCK-0002 S2, S6).
##
## `Option[T]` (std/options), `Result[T, E]` (nimcs/fp/result), `seq[T]` and `Stream[T]`
## (nimcs/fp/lazy_stream) each have their own `map`; the first three also have a `flatMap`. They
## share a shape, not a type: Nim 2 cannot write "any container `F` with `map`" as a type
## parameter, so the shape is a convention that the laws in the tests pin down. This module adds
## what is missing for that shape to be complete: `ap` (apply a wrapped function to a wrapped
## value), `map2` (combine two wrapped values), and `flatMap` for `seq` (the list monad).
## Use it to combine independent wrapped values; use `flatMap` when a later step depends on an
## earlier result.

import std/options
import nimcs/fp/[result, compose]

func ap*[A, B](f: Option[Fn[A, B]]; x: Option[A]): Option[B] {.raises: [].} =
  ## `some` of the application when both hold a value, else `none`.
  if f.isSome and x.isSome: some(f.get()(x.get())) else: none(B)

func ap*[A, B, E](f: Result[Fn[A, B], E]; x: Result[A, E]): Result[B, E] {.raises: [].} =
  ## Applies the function when both are `ok`. When both failed, the error of `f` is reported
  ## (left to right); no error is collected from `x` then.
  if not f.isOk: Result[B, E](isOk: false, error: f.error)
  elif not x.isOk: Result[B, E](isOk: false, error: x.error)
  else: Result[B, E](isOk: true, value: f.value(x.value))

func ap*[A, B](fs: openArray[Fn[A, B]]; xs: openArray[A]): seq[B] {.raises: [].} =
  ## Every function applied to every value, functions in the outer loop.
  result = newSeqOfCap[B](fs.len * xs.len)
  for f in fs:
    for x in xs:
      result.add f(x)

func flatMap*[A, B](xs: openArray[A]; f: proc(x: A): seq[B] {.noSideEffect, raises: [].}): seq[B] {.raises: [].} =
  ## Maps every element to a list and concatenates the lists in order (the list monad).
  for x in xs:
    result.add f(x)

func map2*[A, B, C](a: Option[A]; b: Option[B];
    f: proc(x: A; y: B): C {.noSideEffect, raises: [].}): Option[C] {.raises: [].} =
  ## Combines two independent options; `none` if either is `none`.
  if a.isSome and b.isSome: some(f(a.get(), b.get())) else: none(C)

func map2*[A, B, C, E](a: Result[A, E]; b: Result[B, E];
    f: proc(x: A; y: B): C {.noSideEffect, raises: [].}): Result[C, E] {.raises: [].} =
  ## Combines two independent results; the first error (left to right) wins.
  if not a.isOk: Result[C, E](isOk: false, error: a.error)
  elif not b.isOk: Result[C, E](isOk: false, error: b.error)
  else: Result[C, E](isOk: true, value: f(a.value, b.value))

## Idempotence: doing it twice is the same as doing it once (ADR-NCK-0002 S4, S6).
##
## An operation `f` is idempotent when `f(f(x)) == f(x)` for every `x`. That is what makes a retry
## safe: a client that does not know whether its request arrived can send it again. This module
## holds four small idempotent operations and the law checker they share:
## `normalizeSpaces` (a normal form), `setInsert` (add to a sorted set), `upsertByKey` (insert or
## replace by key), and `apply` on a `Ledger` (a state transition guarded by an idempotency key,
## "apply this command at most once", where a reused key with a different command is an error).
## Every state is a value; nothing is mutated in place.

import std/algorithm
import nimcs/fp/result

func isIdempotentAt*[T](f: proc(x: T): T {.noSideEffect, raises: [].}; x: T): bool {.raises: [].} =
  ## True when `f(f(x)) == f(x)`. Use it as the body of a property test.
  f(f(x)) == f(x)

func normalizeSpaces*(s: string): string {.raises: [].} =
  ## Removes leading and trailing spaces and turns every run of spaces into a single space.
  var pendingSpace = false
  for c in s:
    if c == ' ':
      pendingSpace = result.len > 0
    else:
      if pendingSpace:
        result.add ' '
        pendingSpace = false
      result.add c

func setInsert*(xs: seq[int]; x: int): seq[int] {.raises: [].} =
  ## `xs` must be sorted and without duplicates; the result is too, and contains `x` exactly once.
  let at = xs.lowerBound(x)
  if at < xs.len and xs[at] == x:
    return xs
  result = xs[0 ..< at]
  result.add x
  result.add xs[at .. ^1]

type
  Entry* = object
    key*: string
    value*: int

func upsertByKey*(entries: seq[Entry]; key: string; value: int): seq[Entry] {.raises: [].} =
  ## Sets the value of `key`: the first entry with that key takes `value`, any further entries
  ## with the same key are dropped, and a missing key is appended. The result has exactly one
  ## entry for `key` even when the input had duplicates; other keys keep their order.
  result = newSeqOfCap[Entry](entries.len + 1)
  var found = false
  for e in entries:
    if e.key != key:
      result.add e
    elif not found:
      result.add Entry(key: key, value: value)
      found = true
  if not found:
    result.add Entry(key: key, value: value)

type
  Command* = object
    key*: string      ## idempotency key: a retry of the same request carries the same key
    amount*: int

  Ledger* = object
    ## The balance and, for each key already applied, the command that was applied.
    balance*: int
    applied*: seq[Command]   ## sorted by key, one command per key

  ApplyError* = enum
    keyConflict   ## the key was used before for a different command: a client bug, not a retry

func initLedger*(): Ledger {.raises: [].} =
  Ledger(balance: 0, applied: @[])

func `==`*(a, b: Command): bool {.raises: [].} =
  a.key == b.key and a.amount == b.amount

func `==`*(a, b: Ledger): bool {.raises: [].} =
  a.balance == b.balance and a.applied == b.applied

func findKey(l: Ledger; key: string): int {.raises: [].} =
  ## Index of the first applied command whose key is not below `key` (binary search).
  var lo = 0
  var hi = l.applied.len
  while lo < hi:
    let mid = (lo + hi) div 2
    if l.applied[mid].key < key: lo = mid + 1 else: hi = mid
  lo

func hasApplied*(l: Ledger; key: string): bool {.raises: [].} =
  let at = l.findKey(key)
  at < l.applied.len and l.applied[at].key == key

func apply*(l: Ledger; c: Command): Result[Ledger, ApplyError] {.raises: [].} =
  ## Adds `c.amount` to the balance the first time `c.key` is seen. The same command again
  ## (same key, same amount) is a retry and returns the same ledger. The same key with a
  ## different amount is `keyConflict`: it is reported, never silently ignored.
  ## Precondition: the balance stays within `int`.
  let at = l.findKey(c.key)
  if at < l.applied.len and l.applied[at].key == c.key:
    if l.applied[at] == c: return ok(l, ApplyError)
    return err(Ledger, keyConflict)
  var next = Ledger(balance: l.balance + c.amount, applied: l.applied[0 ..< at])
  next.applied.add c
  next.applied.add l.applied[at .. ^1]
  ok(next, ApplyError)

func applyAll*(l: Ledger; commands: openArray[Command]): Result[Ledger, ApplyError] {.raises: [].} =
  ## Applies the commands in order and stops at the first conflict.
  var cur = l
  for c in commands:
    let r = cur.apply(c)
    if r.isErr:
      return r
    cur = r.value
  ok(cur, ApplyError)

## Copy-and-update of value objects (ADR-NCK-0002 S3, S4).
##
## A `Cart` is a plain value: "changing" it means building a new `Cart` and leaving the old one
## valid, so every earlier version can still be read, compared or restored. Nim copies objects and
## sequences on assignment, which is what makes this safe; a `sink` parameter lets the compiler move
## the argument instead of copying it when the caller no longer needs it. The module is a worked
## example of the pattern: each update is a `func` that takes the old value and returns the new one.

import nimcs/fp/result

type
  CartError* = enum
    badQuantity, priceConflict

  Item* = object
    sku*: string
    qty*: int
    unitCents*: int

  Cart* = object
    ## Items in the order they were first added; at most one entry per `sku`.
    items*: seq[Item]

func initCart*(): Cart {.raises: [].} =
  Cart(items: @[])

func indexOf(items: seq[Item]; sku: string): int {.raises: [].} =
  result = -1
  for i, it in items:
    if it.sku == sku:
      return i

func added*(cart: sink Cart; item: Item): Result[Cart, CartError] {.raises: [].} =
  ## A cart with `item` added; the quantity is summed when the `sku` is already there.
  ## `item.qty` must be at least 1 (`badQuantity`), and an item whose `sku` is already in the
  ## cart must carry the same unit price (`priceConflict`): the cart never guesses which price is meant.
  ## `cart` is `sink`: a caller who keeps using the old cart gets a copy, one who does not gets a move.
  if item.qty < 1:
    return err(Cart, badQuantity)
  var next = cart
  let at = indexOf(next.items, item.sku)
  if at < 0:
    next.items.add item
  elif next.items[at].unitCents != item.unitCents:
    return err(Cart, priceConflict)
  else:
    next.items[at].qty += item.qty
  ok(next, CartError)

func withQty*(cart: sink Cart; sku: string; qty: int): Result[Cart, CartError] {.raises: [].} =
  ## A cart where `sku` has exactly `qty` units (`qty` at least 1, else `badQuantity`); a `sku`
  ## that is not in the cart is left alone. Setting the same quantity twice is the same as
  ## setting it once.
  if qty < 1:
    return err(Cart, badQuantity)
  var next = cart
  let at = indexOf(next.items, sku)
  if at >= 0:
    next.items[at].qty = qty
  ok(next, CartError)

func removed*(cart: sink Cart; sku: string): Cart {.raises: [].} =
  ## A cart without `sku`. Removing an absent `sku` changes nothing, so removing twice equals once.
  result = Cart(items: @[])
  for it in cart.items:
    if it.sku != sku:
      result.items.add it

func totalCents*(cart: Cart): int {.raises: [].} =
  ## Sum of `qty * unitCents` over the items. Precondition: the sum fits in an `int`.
  for it in cart.items:
    result += it.qty * it.unitCents

func `==`*(a, b: Cart): bool {.raises: [].} =
  a.items == b.items

## Lazy streams: sequences that compute their elements only when asked (ADR-NCK-0002 S3, S4).
##
## A `Stream[T]` is an immutable value holding a function that, when pulled, returns either "done"
## or "this element and the rest of the stream". `map`, `filter`, `take` and `takeWhile` build a new
## stream without computing anything and without building a `seq`; only `toSeq(limit)` walks the
## stream. Because a stream never changes, it can be walked twice with the same result, and an
## infinite stream (`iterate`) is safe as long as it is cut with `take` or `toSeq`'s limit.

type
  StreamStep[T] = object
    case hasValue: bool
    of true:
      head: T
      rest: Stream[T]
    of false:
      discard

  Stream*[T] = object
    pull: proc(): StreamStep[T] {.noSideEffect, raises: [].}

func endStep[T](): StreamStep[T] {.raises: [].} =
  StreamStep[T](hasValue: false)

func stepOf[T](head: T; rest: Stream[T]): StreamStep[T] {.raises: [].} =
  StreamStep[T](hasValue: true, head: head, rest: rest)

func emptyStream*[T](): Stream[T] {.raises: [].} =
  ## A stream with no elements.
  result = Stream[T](pull: proc(): StreamStep[T] {.noSideEffect, raises: [].} = endStep[T]())

type
  Shared[T] = ref object
    ## An immutable block of elements that all the stages of one `fromSeq` stream point to,
    ## so that moving to the next element copies a pointer, not the elements (ADR S3: `ref`
    ## only to immutable data).
    items: seq[T]

func fromShared[T](block0: Shared[T]; start: int): Stream[T] {.raises: [].} =
  result = Stream[T](pull: proc(): StreamStep[T] {.noSideEffect, raises: [].} =
    if start >= block0.items.len: endStep[T]()
    else: stepOf(block0.items[start], fromShared(block0, start + 1)))

func fromSeq*[T](xs: openArray[T]): Stream[T] {.raises: [].} =
  ## The stream of the elements of `xs`, in order. The elements are copied once, here.
  fromShared(Shared[T](items: @xs), 0)

func iterate*[T](seed: T; next: proc(x: T): T {.noSideEffect, raises: [].}): Stream[T] {.raises: [].} =
  ## The infinite stream `seed, next(seed), next(next(seed)), ...`. `next` is applied only when
  ## the element after `seed` is pulled, never ahead of need.
  result = Stream[T](pull: proc(): StreamStep[T] {.noSideEffect, raises: [].} =
    let rest = Stream[T](pull: proc(): StreamStep[T] {.noSideEffect, raises: [].} =
      iterate(next(seed), next).pull())
    stepOf(seed, rest))

func map*[T, U](s: Stream[T]; f: proc(x: T): U {.noSideEffect, raises: [].}): Stream[U] {.raises: [].} =
  ## Applies `f` to each element when it is reached.
  result = Stream[U](pull: proc(): StreamStep[U] {.noSideEffect, raises: [].} =
    let step = s.pull()
    if step.hasValue: stepOf(f(step.head), step.rest.map(f))
    else: endStep[U]())

func filter*[T](s: Stream[T]; keep: proc(x: T): bool {.noSideEffect, raises: [].}): Stream[T] {.raises: [].} =
  ## The elements for which `keep` holds. On an infinite stream with no match, pulling never returns.
  result = Stream[T](pull: proc(): StreamStep[T] {.noSideEffect, raises: [].} =
    var cur = s
    while true:
      let step = cur.pull()
      if not step.hasValue:
        return endStep[T]()
      if keep(step.head):
        return stepOf(step.head, step.rest.filter(keep))
      cur = step.rest
    endStep[T]())

func take*[T](s: Stream[T]; n: Natural): Stream[T] {.raises: [].} =
  ## At most the first `n` elements.
  result = Stream[T](pull: proc(): StreamStep[T] {.noSideEffect, raises: [].} =
    if n == 0:
      return endStep[T]()
    let step = s.pull()
    if step.hasValue: stepOf(step.head, step.rest.take(n - 1))
    else: endStep[T]())

func takeWhile*[T](s: Stream[T]; keep: proc(x: T): bool {.noSideEffect, raises: [].}): Stream[T] {.raises: [].} =
  ## The longest prefix whose elements all satisfy `keep`.
  result = Stream[T](pull: proc(): StreamStep[T] {.noSideEffect, raises: [].} =
    let step = s.pull()
    if step.hasValue and keep(step.head): stepOf(step.head, step.rest.takeWhile(keep))
    else: endStep[T]())

func toSeq*[T](s: Stream[T]; limit: Natural): seq[T] {.raises: [].} =
  ## Walks the stream and collects at most `limit` elements. The limit is required so that an
  ## infinite stream cannot hang the caller.
  var cur = s
  while result.len < limit:
    let step = cur.pull()
    if not step.hasValue:
      break
    result.add step.head
    cur = step.rest

## Working with `std/options` without sentinels (ADR-NCK-0002 S2).
##
## `Option[T]` says "there may be no value". The standard library already gives `map`, `flatMap`,
## `filter`, `get(default)` and `isSome`; this module adds the pieces that are missing when options
## meet each other or meet `Result`: turn absence into a reason (`okOr`), pick the first present
## value (`orElse`), combine two options (`both`), and flip a list of options into an option of a
## list (`sequence`). Reach for it whenever "not found" is an expected answer, not an error.

import std/options
import nimcs/fp/result

func okOr*[T, E](o: Option[T]; reason: E): Result[T, E] {.raises: [].} =
  ## Absence becomes the given error; presence becomes `ok`.
  if o.isSome: Result[T, E](isOk: true, value: o.get)
  else: Result[T, E](isOk: false, error: reason)

func toOption*[T, E](r: Result[T, E]): Option[T] {.raises: [].} =
  ## Forgets why a result failed.
  if r.isOk: some(r.value) else: none(T)

func orElse*[T](a, b: Option[T]): Option[T] {.raises: [].} =
  ## The first option that holds a value (left-biased). `none` is the identity, so this is a
  ## monoid on options.
  if a.isSome: a else: b

func both*[A, B](a: Option[A]; b: Option[B]): Option[(A, B)] {.raises: [].} =
  ## `some` of the pair only when both hold a value.
  if a.isSome and b.isSome: some((a.get, b.get)) else: none((A, B))

func sequence*[T](xs: openArray[Option[T]]): Option[seq[T]] {.raises: [].} =
  ## `some` of all the values, in order, when every element holds one; otherwise `none`.
  var values = newSeqOfCap[T](xs.len)
  for x in xs:
    if x.isNone:
      return none(seq[T])
    values.add x.get
  some(values)

func catSome*[T](xs: openArray[Option[T]]): seq[T] {.raises: [].} =
  ## Keeps the values that are present and drops the absent ones, preserving order.
  result = newSeqOfCap[T](xs.len)
  for x in xs:
    if x.isSome:
      result.add x.get

func firstSome*[T](xs: openArray[Option[T]]): Option[T] {.raises: [].} =
  ## The first element that holds a value, or `none` for an empty or all-absent input.
  for x in xs:
    if x.isSome:
      return x
  none(T)

## Phantom types: a type parameter that is never stored, only checked (ADR-NCK-0002 S3).
##
## `Id[T]` is an `int` at run time and a different type for each `T`, so a user id cannot be passed
## where an order id is expected. `Quantity[U]` carries its unit in the type: lengths add to
## lengths, never to durations. `Email[S]` records in the type whether the text was validated, so a
## routine that needs a valid address (`domainOf`) cannot be handed a raw one. The parameter costs
## nothing at run time. It is built with `distinct`, so a conversion such as `Email[Validated]("x")`
## still compiles anywhere: the phantom parameter stops accidents, not a caller who forges it. When
## the value must be unforgeable, hide the field in an object and export only the smart
## constructor (see `smart_constructor.nim`).

import nimcs/fp/result

type
  Id*[T] = distinct int
    ## An identifier of something of kind `T`; `T` is only a label.

  Meter* = object
    ## Unit tag for lengths in meters.
  Centimeter* = object
    ## Unit tag for lengths in centimeters.
  Second* = object
    ## Unit tag for durations.

  Quantity*[U] = distinct int
    ## An exact whole amount measured in unit `U`.

  Raw* = object
    ## Tag: text that has not been checked.
  Validated* = object
    ## Tag: text that `validateEmail` accepted.

  Email*[S] = distinct string
    ## An e-mail address in state `S` (`Raw` or `Validated`).

func idOf*[T](n: int): Id[T] {.raises: [].} =
  ## Labels a number as an id of kind `T`.
  Id[T](n)

func raw*[T](id: Id[T]): int {.raises: [].} =
  ## The number inside the id.
  int(id)

func `==`*[T](a, b: Id[T]): bool {.raises: [].} = int(a) == int(b)

func `<`*[T](a, b: Id[T]): bool {.raises: [].} = int(a) < int(b)

func qty*[U](n: int): Quantity[U] {.raises: [].} =
  ## An amount of `n` units `U`.
  Quantity[U](n)

func amount*[U](q: Quantity[U]): int {.raises: [].} =
  ## The number inside the quantity.
  int(q)

func `+`*[U](a, b: Quantity[U]): Quantity[U] {.raises: [].} = Quantity[U](int(a) + int(b))

func `-`*[U](a, b: Quantity[U]): Quantity[U] {.raises: [].} = Quantity[U](int(a) - int(b))

func `==`*[U](a, b: Quantity[U]): bool {.raises: [].} = int(a) == int(b)

func scaled*[U](q: Quantity[U]; factor: int): Quantity[U] {.raises: [].} =
  ## The amount multiplied by a plain number; the unit is unchanged.
  Quantity[U](int(q) * factor)

func toCentimeters*(m: Quantity[Meter]): Quantity[Centimeter] {.raises: [].} =
  ## The only way to turn meters into centimeters: the unit change is explicit.
  Quantity[Centimeter](int(m) * 100)

func toMetersExact*(cm: Quantity[Centimeter]): Result[Quantity[Meter], string] {.raises: [].} =
  ## Whole meters, or an error when the centimeters are not a multiple of 100 (no silent rounding).
  if int(cm) mod 100 == 0: ok(Quantity[Meter](int(cm) div 100), string)
  else: err(Quantity[Meter], "not a whole number of meters")

func rawEmail*(text: string): Email[Raw] {.raises: [].} =
  ## Wraps unchecked text; says nothing about its validity.
  Email[Raw](text)

func validateEmail*(e: Email[Raw]): Result[Email[Validated], string] {.raises: [].} =
  ## Accepts text with exactly one `@`, a non-empty part before it and a part after it that has a
  ## `.` which is neither its first nor its last character. This is a teaching rule, not RFC 5322.
  let s = string(e)
  var at = -1
  var ats = 0
  for i, c in s:
    if c == '@':
      inc ats
      at = i
  if ats != 1 or at == 0:
    return err(Email[Validated], "needs one @ and a name before it")
  let domain = s[at + 1 .. ^1]
  var innerDot = false
  for i, c in domain:
    if c == '.' and i > 0 and i < domain.high:
      innerDot = true
  if not innerDot:
    return err(Email[Validated], "domain needs a dot between two parts")
  ok(Email[Validated](s), string)

func domainOf*(e: Email[Validated]): string {.raises: [].} =
  ## The part after `@`. Only a validated address is accepted, so there is no failure case.
  let s = string(e)
  for i in 0 ..< s.len:
    if s[i] == '@':
      return s[i + 1 .. ^1]
  ""

func text*[S](e: Email[S]): string {.raises: [].} =
  ## The text of an address in any state.
  string(e)

## `Result[T, E]`: a value or the reason there is none (ADR-NCK-0002 S2).
##
## A small, dependency-free version of what `results` (Status) offers, so that every module and
## every dataset record compiles with the standard library alone. The names (`ok`, `err`, `isOk`,
## `map`, `flatMap`, `mapErr`, `valueOr`) resemble those of the `results` package, but the API is
## not compatible: here `ok` and `err` take a type argument (`ok(1, string)`, `err(int, "e")`),
## and reading `.value` of an error, or `.error` of a success, raises `FieldDefect` instead of
## following the `results` rules. Check `isOk` first, or leave the railway with `valueOr`.
## A program that already uses `results` should keep using it and not mix the two types.

type
  Result*[T, E] = object
    case isOk*: bool
    of true:
      value*: T
    of false:
      error*: E

func ok*[T, E](v: T; _: typedesc[E]): Result[T, E] {.raises: [].} =
  Result[T, E](isOk: true, value: v)

func err*[T, E](_: typedesc[T]; e: E): Result[T, E] {.raises: [].} =
  Result[T, E](isOk: false, error: e)

func isErr*[T, E](r: Result[T, E]): bool {.raises: [].} = not r.isOk

func map*[T, E, U](r: Result[T, E]; f: proc(x: T): U {.noSideEffect, raises: [].}): Result[U, E] {.raises: [].} =
  ## Functor law (spec FP-RESULT-01): r.map(identity) == r; r.map(f).map(g) == r.map(g ∘ f).
  if r.isOk: Result[U, E](isOk: true, value: f(r.value))
  else: Result[U, E](isOk: false, error: r.error)

func flatMap*[T, E, U](r: Result[T, E];
    f: proc(x: T): Result[U, E] {.noSideEffect, raises: [].}): Result[U, E] {.raises: [].} =
  ## The railway: the first error stops the chain (spec FP-RESULT-02).
  if r.isOk: f(r.value)
  else: Result[U, E](isOk: false, error: r.error)

func mapErr*[T, E, F](r: Result[T, E]; f: proc(e: E): F {.noSideEffect, raises: [].}): Result[T, F] {.raises: [].} =
  if r.isOk: Result[T, F](isOk: true, value: r.value)
  else: Result[T, F](isOk: false, error: f(r.error))

func valueOr*[T, E](r: Result[T, E]; fallback: T): T {.raises: [].} =
  if r.isOk: r.value else: fallback

func `==`*[T, E](a, b: Result[T, E]): bool {.raises: [].} =
  if a.isOk != b.isOk: false
  elif a.isOk: a.value == b.value
  else: a.error == b.error

## Recursion and loops in Nim: the accumulator rewrite and when to stop recursing
## (ADR-NCK-0002 S1, S5, S6).
##
## A recursive call is a tail call when it is the last thing a routine does. Nim does not
## guarantee that a tail call reuses the stack frame: whether a C compiler turns it into a jump
## depends on the backend and its settings, so a recursion whose
## depth grows with the input (a list of 100 000 elements, `n = 10^6`) can overflow the stack even
## when written in tail form. The portable rule is: write the recursion to find the invariant,
## carry the partial result in an accumulator argument, then make the final routine a loop with a
## local `var` (invisible outside, ADR S5). Each family here has the naive recursion, the
## accumulator form and the loop, and the tests show that all three agree.

type
  FibIndex* = range[0 .. 92]
    ## `fib(92)` is the largest Fibonacci number that fits in a 64-bit `int`.

func sumToNaive*(n: Natural): int {.raises: [].} =
  ## `0 + 1 + ... + n`, recursing on `n - 1`: the addition happens after the call returns, so the
  ## stack grows by one frame per step. Use only for small `n`.
  if n == 0: 0 else: n + sumToNaive(n - 1)

func sumToAcc*(n: Natural; acc: int): int {.raises: [].} =
  ## `acc + (0 + 1 + ... + n)`, with the partial sum carried in `acc`: the recursive call is the last
  ## action (a tail call), but Nim does not promise to reuse the frame.
  if n == 0: acc else: sumToAcc(n - 1, acc + n)

func sumToLoop*(n: Natural): int {.raises: [].} =
  ## The same sum as a loop with a local accumulator: constant stack for any `n`.
  for i in 1 .. n:
    result += i

func fibNaive*(n: FibIndex): int {.raises: [].} =
  ## Fibonacci by the definition: two recursive calls, time exponential in `n`. Small `n` only.
  if n < 2: int(n) else: fibNaive(n - 1) + fibNaive(n - 2)

func fibAcc*(n: Natural; a, b: int): int {.raises: [].} =
  ## Fibonacci with two accumulators holding `fib(k)` and `fib(k + 1)`: `fibAcc(n, 0, 1)` is
  ## `fib(n)`. A tail call, linear time. It never computes a sum beyond `fib(n)`, so it does not
  ## overflow for `n <= 92`.
  if n == 0: a elif n == 1: b else: fibAcc(n - 1, b, a + b)

func fibLoop*(n: FibIndex): int {.raises: [].} =
  ## The pair of accumulators as two local variables; no sum beyond `fib(n)` is computed.
  if n < 2:
    return int(n)
  var previous = 0
  var current = 1
  for _ in 2 .. n:
    (previous, current) = (current, previous + current)
  current

func gcdRec*(a, b: Natural): int {.raises: [].} =
  ## Euclid's algorithm. Naturally a tail call: nothing is left to do after the recursive call.
  if b == 0: a else: gcdRec(b, a mod b)

func gcdLoop*(a, b: Natural): int {.raises: [].} =
  ## The same algorithm as a loop over two local variables.
  var x: int = a
  var y: int = b
  while y != 0:
    (x, y) = (y, x mod y)
  x

## Type classes in Nim: `concept` constraints on generics, and laws checked per instance
## (ADR-NCK-0002 S3, S6).
##
## A type class says "any type that supports these operations". In Nim that is a generic routine
## whose type parameter is constrained by a `concept`; an instance is simply a type that defines
## the operations (`<` and `==` here). The compiler checks that the operations exist, never that
## they behave: `Orderable` accepts a type whose `<` is not a total order, and `maxOf` then gives
## an arbitrary answer. `isTotalOrderOn` is the missing check; run it on generated values for each
## instance, as the tests do. Use a concept when one routine must serve several unrelated types;
## use a plain generic (`[T]`) when it only moves values around and never inspects them.

import std/options

type
  Orderable* = concept x, y
    ## Types with `<` and `==`: the instance contract of an ordered type.
    (x < y) is bool
    (x == y) is bool

func maxOf*[T: Orderable](xs: openArray[T]): Option[T] {.raises: [].} =
  ## The largest element, or `none` for an empty input.
  if xs.len == 0:
    return none(T)
  var best = xs[0]
  for i in 1 ..< xs.len:
    if best < xs[i]:
      best = xs[i]
  some(best)

func minOf*[T: Orderable](xs: openArray[T]): Option[T] {.raises: [].} =
  ## The smallest element, or `none` for an empty input.
  if xs.len == 0:
    return none(T)
  var best = xs[0]
  for i in 1 ..< xs.len:
    if xs[i] < best:
      best = xs[i]
  some(best)

func insertSorted*[T: Orderable](sortedXs: openArray[T]; x: T): seq[T] {.raises: [].} =
  ## A new sequence with `x` placed after the elements not greater than it; the input, which must
  ## be sorted, is not changed. Inserting into a sorted sequence keeps it sorted.
  result = newSeqOfCap[T](sortedXs.len + 1)
  var placed = false
  for e in sortedXs:
    if not placed and x < e:
      result.add x
      placed = true
    result.add e
  if not placed:
    result.add x

func isSorted*[T: Orderable](xs: openArray[T]): bool {.raises: [].} =
  ## True when no element is smaller than the one before it.
  for i in 1 ..< xs.len:
    if xs[i] < xs[i - 1]:
      return false
  true

func isTotalOrderOn*[T: Orderable](a, b, c: T): bool {.raises: [].} =
  ## The laws of a strict total order on three sample values: irreflexive, asymmetric, transitive,
  ## and total (two values are `==` or one is `<` the other), with `==` agreeing with the order.
  ## It checks only these samples; the caller supplies many.
  let irreflexive = not (a < a)
  let asymmetric = not (a < b and b < a)
  let transitive = not (a < b and b < c) or a < c
  let total = a == b or a < b or b < a
  let consistent = not (a == b) or not (a < b or b < a)
  irreflexive and asymmetric and transitive and total and consistent

func backwards*[T](xs: openArray[T]): seq[T] {.raises: [].} =
  ## The elements in the opposite order. It never looks inside an element, so by parametricity it
  ## commutes with `map`: `xs.map(g).backwards == xs.backwards.map(g)`.
  result = newSeqOfCap[T](xs.len)
  for i in countdown(xs.high, 0):
    result.add xs[i]

## Adapter as a function between two types.
##
## The OO pattern wraps an object with an incompatible interface so that existing client code can
## use it. In Nim the interface is a type, so the adapter is a `func` that converts the old shape to
## the new one; adapting a source of values is mapping that func over it. Here a legacy schedule
## source returns "HH:MM" strings and the new code wants `Minutes` since midnight. Use it at the
## boundary where a foreign shape enters; do not let the foreign shape leak further in.

import nimcs/fp/result

type
  Minutes* = distinct int

  AdaptError* = enum
    aeBadLength, aeBadSeparator, aeBadDigit, aeOutOfRange

  LegacySource* = proc(): seq[string] {.noSideEffect, raises: [].}

func `==`*(a, b: Minutes): bool {.borrow.}

func digit(c: char): int {.raises: [].} =
  if c in {'0' .. '9'}: ord(c) - ord('0') else: -1

func fromLegacy*(s: string): Result[Minutes, AdaptError] {.raises: [].} =
  ## Parses "HH:MM"; every malformed input is a specific error, never an exception.
  if s.len != 5:
    err(Minutes, aeBadLength)
  elif s[2] != ':':
    err(Minutes, aeBadSeparator)
  else:
    let (a, b, c, d) = (digit(s[0]), digit(s[1]), digit(s[3]), digit(s[4]))
    if a < 0 or b < 0 or c < 0 or d < 0:
      err(Minutes, aeBadDigit)
    else:
      let h = a * 10 + b
      let m = c * 10 + d
      if h > 23 or m > 59: err(Minutes, aeOutOfRange)
      else: ok(Minutes(h * 60 + m), AdaptError)

func toLegacy*(m: Minutes): string {.raises: [].} =
  ## Inverse of `fromLegacy` on `0 .. 1439`.
  let v = int(m)
  let h = v div 60
  let mm = v mod 60
  $(h div 10) & $(h mod 10) & ":" & $(mm div 10) & $(mm mod 10)

func adaptAll*(src: LegacySource): Result[seq[Minutes], AdaptError] {.raises: [].} =
  ## Adapts a whole source; the first bad entry stops the conversion.
  var acc: seq[Minutes] = @[]
  for s in src():
    let r = fromLegacy(s)
    if r.isErr:
      return err(seq[Minutes], r.error)
    acc.add(r.value)
  ok(acc, AdaptError)

## Anti-corruption layer: translate a foreign model at the border so it never leaks inward.
##
## Another system's model (a supplier's order message) has its own words, codes and number formats,
## and it changes when they decide. If its types reach into your code, every change of theirs is a
## change of yours, and its mistakes (a status code you never meant to support) become your states.
## The layer is the only place that knows both. It is a pair of functions per foreign version: one
## from the foreign record to your `Order`, built through the same smart constructor as every
## order of your own, and one back; your code takes `Order` and cannot be handed a foreign record
## (the compiler refuses it). A new foreign version is a new pair, and nothing inward moves.
## Refusals are values with a reason and a position, not zeros and defaults. Use it where a model
## you do not control meets one you do; do not use it between two parts of your own model.

import nimcs/fp/result
export result

type
  OrderStatus* = enum
    osActive, osShipped, osCancelled

  Cents* = distinct int

  Order* = object
    ## The inner model: a non-empty id and a total that is never negative.
    id*: string
    status*: OrderStatus
    total*: Cents

  TranslateError* = enum
    teEmptyId, teUnknownStatus, teBadAmount

  ForeignOrderV1* = object
    ## The supplier's first format: a status letter and a decimal amount as text, "12.50".
    reference*: string
    statusCode*: string
    amount*: string

  ForeignOrderV2* = object
    ## Their second format: status words and an integer number of cents.
    orderId*: string
    state*: string
    minorUnits*: int

  Refusal* = tuple[index: int, error: TranslateError]

  Translated* = tuple[orders: seq[Order], refused: seq[Refusal]]

func `==`*(a, b: Cents): bool {.borrow.}
func `<`*(a, b: Cents): bool {.borrow.}
func `$`*(c: Cents): string {.borrow.}

func initOrder*(id: string; status: OrderStatus; total: int): Result[Order, TranslateError] {.raises: [].} =
  ## The one place the inner invariants are checked; every translator goes through it.
  if id.len == 0:
    err(Order, teEmptyId)
  elif total < 0:
    err(Order, teBadAmount)
  else:
    ok(Order(id: id, status: status, total: Cents(total)), TranslateError)

func canShip*(o: Order): bool {.raises: [].} =
  ## Inner business rule. It names only inner types, so a foreign record cannot reach it.
  o.status == osActive and int(o.total) > 0

func parseAmountV1(s: string): Result[int, TranslateError] {.raises: [].} =
  ## "digits.dd" with 1 to 9 whole digits (the length is checked first, so no overflow).
  let dot = s.len - 3
  if dot < 1 or dot > 9 or s[dot] != '.':
    return err(int, teBadAmount)
  var cents = 0
  for i, c in s:
    if i != dot:
      if c notin {'0' .. '9'}:
        return err(int, teBadAmount)
      cents = cents * 10 + (ord(c) - ord('0'))
  ok(cents, TranslateError)

func statusV1(code: string): Result[OrderStatus, TranslateError] {.raises: [].} =
  case code
  of "A": ok(osActive, TranslateError)
  of "S": ok(osShipped, TranslateError)
  of "X": ok(osCancelled, TranslateError)
  else: err(OrderStatus, teUnknownStatus)

func statusV2(word: string): Result[OrderStatus, TranslateError] {.raises: [].} =
  case word
  of "ACTIVE": ok(osActive, TranslateError)
  of "SHIPPED": ok(osShipped, TranslateError)
  of "CANCELLED": ok(osCancelled, TranslateError)
  else: err(OrderStatus, teUnknownStatus)

func fromV1*(f: ForeignOrderV1): Result[Order, TranslateError] {.raises: [].} =
  ## Checks in a fixed order: id, status, amount; the first problem is the error.
  if f.reference.len == 0:
    return err(Order, teEmptyId)
  let status = statusV1(f.statusCode)
  if status.isErr:
    return err(Order, status.error)
  let amount = parseAmountV1(f.amount)
  if amount.isErr:
    return err(Order, amount.error)
  initOrder(f.reference, status.value, amount.value)

func fromV2*(f: ForeignOrderV2): Result[Order, TranslateError] {.raises: [].} =
  if f.orderId.len == 0:
    return err(Order, teEmptyId)
  let status = statusV2(f.state)
  if status.isErr:
    return err(Order, status.error)
  initOrder(f.orderId, status.value, f.minorUnits)

func toV1*(o: Order): ForeignOrderV1 {.raises: [].} =
  let cents = int(o.total)
  let frac = cents mod 100
  let code = case o.status
    of osActive: "A"
    of osShipped: "S"
    of osCancelled: "X"
  ForeignOrderV1(reference: o.id, statusCode: code,
    amount: $(cents div 100) & "." & $(frac div 10) & $(frac mod 10))

func toV2*(o: Order): ForeignOrderV2 {.raises: [].} =
  let word = case o.status
    of osActive: "ACTIVE"
    of osShipped: "SHIPPED"
    of osCancelled: "CANCELLED"
  ForeignOrderV2(orderId: o.id, state: word, minorUnits: int(o.total))

func translateAll*[F](xs: seq[F]; translate: proc(f: F): Result[Order, TranslateError] {.noSideEffect, raises: [].}
    ): Translated {.raises: [].} =
  ## A bad record does not stop the batch and is not dropped silently: it is listed with its index.
  result = (orders: @[], refused: @[])
  for i, x in xs:
    let r = translate(x)
    if r.isOk:
      result.orders.add r.value
    else:
      result.refused.add (index: i, error: r.error)

## Bulkhead: a fixed number of permits per compartment, so one partition's load cannot take another's capacity.
##
## A ship's bulkheads keep a flooded compartment from sinking the rest. In a service, one shared pool
## of workers lets a slow tenant or a slow dependency hold every worker; giving each partition its
## own number of permits keeps the damage inside the partition. The whole state is one value,
## `Bulkhead`: the permit limit and the permits in use of every compartment. `tryAcquire` is a pure
## admission function that returns the new value and the answer; `release` returns a permit and
## refuses to release one that was never taken, so a double release cannot grow the capacity.
## Nothing here blocks or waits: a refusal is a value, and what to do with it (queue, shed, fail
## fast) belongs to the caller, see `load_shedding` for deciding by queue length and deadline.
## Use it around calls that share a scarce resource and can be grouped by tenant, dependency or
## priority class.

import std/[tables, algorithm]
import nimcs/fp/result
export result

type
  Bulkhead* = object
    limits: Table[string, int]
    inUse: Table[string, int]

  Admission* = enum
    aAdmitted, aFull, aUnknownCompartment

  SetupError* = enum
    seNoCompartments, seEmptyName, seDuplicateName, seLimitNotPositive

  ReleaseError* = enum
    reUnknownCompartment, reNothingToRelease

func `==`*(a, b: Bulkhead): bool {.raises: [].} = a.limits == b.limits and a.inUse == b.inUse

func initBulkhead*(limits: openArray[(string, int)]): Result[Bulkhead, SetupError] {.raises: [].} =
  ## One `(name, permits)` pair per compartment. Names are non-empty and distinct, permits are
  ## positive, and there is at least one compartment; the first violated rule is reported.
  if limits.len == 0:
    return err(Bulkhead, seNoCompartments)
  var table = initTable[string, int]()
  var used = initTable[string, int]()
  for (name, permits) in limits:
    if name.len == 0: return err(Bulkhead, seEmptyName)
    if table.hasKey(name): return err(Bulkhead, seDuplicateName)
    if permits < 1: return err(Bulkhead, seLimitNotPositive)
    table[name] = permits
    used[name] = 0
  ok(Bulkhead(limits: table, inUse: used), SetupError)

func limit*(b: Bulkhead; compartment: string): int {.raises: [].} =
  ## The permits of a compartment; 0 for an unknown name.
  b.limits.getOrDefault(compartment, 0)

func inUse*(b: Bulkhead; compartment: string): int {.raises: [].} =
  ## The permits taken now; 0 for an unknown name.
  b.inUse.getOrDefault(compartment, 0)

func available*(b: Bulkhead; compartment: string): int {.raises: [].} =
  b.limit(compartment) - b.inUse(compartment)

func usage*(b: Bulkhead): seq[(string, int)] {.raises: [].} =
  ## `(name, permits in use)` for every compartment, sorted by name (the table's own order is not
  ## part of the contract and never leaks).
  for name, n in b.inUse:
    result.add (name, n)
  result.sort(proc(x, y: (string, int)): int = cmp(x[0], y[0]))

func tryAcquire*(b: Bulkhead; compartment: string): tuple[bulkhead: Bulkhead, admission: Admission] {.raises: [].} =
  ## Take one permit of `compartment` when one is free. A refusal returns the bulkhead unchanged.
  if not b.limits.hasKey(compartment):
    return (b, aUnknownCompartment)
  if b.inUse(compartment) >= b.limit(compartment):
    return (b, aFull)
  var next = b
  next.inUse[compartment] = b.inUse(compartment) + 1
  (next, aAdmitted)

func release*(b: Bulkhead; compartment: string): Result[Bulkhead, ReleaseError] {.raises: [].} =
  ## Give back one permit. Releasing in a compartment with no permit taken is an error, not a
  ## no-op: it would mean some caller releases twice, and the capacity would silently grow.
  if not b.limits.hasKey(compartment):
    return err(Bulkhead, reUnknownCompartment)
  if b.inUse(compartment) < 1:
    return err(Bulkhead, reNothingToRelease)
  var next = b
  next.inUse[compartment] = b.inUse(compartment) - 1
  ok(next, ReleaseError)

## Chain of Responsibility: a list of "maybe handle it" functions; the first `some` wins.
##
## The OO pattern links handler objects, each holding a reference to its successor and deciding to
## handle or pass on. In Nim a handler is `proc(request): Option[Response]`, a chain is a plain
## `seq` of them, and "pass it on" is simply moving to the next element. `orElse` composes two
## handlers into one, which makes handlers a monoid (associative, with `never` as identity), so
## chains can be nested or built in pieces. Unhandled is a `Result` error, not a nil. Use it for
## approvals, middleware, parsers that try alternatives, and fallbacks. The example approves
## expense claims by the lowest authority whose limit covers the amount.

import std/options
import nimcs/fp/result

type
  Handler*[Req, Resp] = proc(request: Req): Option[Resp] {.noSideEffect, raises: [].}

  Unhandled* = object
    ## No handler in the chain accepted the request.

  Claim* = object
    amount*: int
    category*: string

  Approval* = object
    by*: string
    amount*: int

func `==`*(a, b: Approval): bool {.raises: [].} = a.by == b.by and a.amount == b.amount
func `$`*(a: Approval): string {.raises: [].} = a.by & "@" & $a.amount

func never*[Req, Resp](request: Req): Option[Resp] {.raises: [].} =
  ## The handler that accepts nothing; the identity of `orElse`.
  none(Resp)

func firstSome*[Req, Resp](chain: openArray[Handler[Req, Resp]]; request: Req): Option[Resp] {.raises: [].} =
  ## Asks the handlers in order and returns the first answer. Handlers after the one that answered
  ## are not called.
  for h in chain:
    let r = h(request)
    if r.isSome: return r
  none(Resp)

func handle*[Req, Resp](chain: openArray[Handler[Req, Resp]];
                        request: Req): Result[Resp, Unhandled] {.raises: [].} =
  let r = firstSome(chain, request)
  if r.isSome: ok(r.get, Unhandled) else: err(Resp, Unhandled())

func orElse*[Req, Resp](first, second: Handler[Req, Resp]): Handler[Req, Resp] {.raises: [].} =
  ## One handler that tries `first`, then `second`.
  result = proc(request: Req): Option[Resp] {.noSideEffect, raises: [].} =
    let r = first(request)
    if r.isSome: r else: second(request)

func within*(name: string; limit: int): Handler[Claim, Approval] {.raises: [].} =
  ## Approves claims up to `limit` (inclusive); passes on anything larger or non-positive.
  result = proc(c: Claim): Option[Approval] {.noSideEffect, raises: [].} =
    if c.amount > 0 and c.amount <= limit: some(Approval(by: name, amount: c.amount))
    else: none(Approval)

func onlyCategory*(h: Handler[Claim, Approval]; category: string): Handler[Claim, Approval] {.raises: [].} =
  ## Restricts a handler to one category of claim; other categories are passed on.
  result = proc(c: Claim): Option[Approval] {.noSideEffect, raises: [].} =
    if c.category == category: h(c) else: none(Approval)

func authorityChain*(): seq[Handler[Claim, Approval]] {.raises: [].} =
  ## Clerk up to 100, manager up to 1000, director up to 10000.
  @[within("clerk", 100), within("manager", 1000), within("director", 10000)]

## Command: an edit is a value; undo is another value.
##
## Positions and lengths are byte offsets into a UTF-8 text. A command that would cut a multi-byte
## character (a position on a continuation byte) or insert invalid UTF-8 is refused, so a valid
## document stays valid and `inverse` always describes the edit that was applied.
##
## The OO pattern wraps a request in an object with `execute` and `undo` so it can be queued,
## logged and reversed. In Nim a command is plain data (an object variant), `apply` is a pure
## function from document and command to a new document, and undo is the inverse command, computed
## from the document as it was before the edit. The editor keeps two stacks of inverse/forward
## commands. Use it when operations must be replayed, logged, undone or sent elsewhere; when you
## only need "go back to an earlier state", keep the old values instead (see `memento`).

import std/unicode
import nimcs/fp/result

type
  CmdKind* = enum
    ckInsert, ckDelete

  Cmd* = object
    ## Insert `text` before index `pos`, or delete `len` characters starting at `pos`.
    case kind*: CmdKind
    of ckInsert:
      pos*: int
      text*: string
    of ckDelete:
      at*: int
      len*: int

  EditError* = enum
    eeOutOfRange, eeNotCharBoundary, eeInvalidUtf8, eeNothingToUndo, eeNothingToRedo

  Editor* = object
    text*: string
    undoStack*: seq[Cmd]   ## inverse commands, most recent last
    redoStack*: seq[Cmd]   ## forward commands that were undone, most recent last

func insertCmd*(pos: int; text: string): Cmd {.raises: [].} =
  Cmd(kind: ckInsert, pos: pos, text: text)

func deleteCmd*(at, len: int): Cmd {.raises: [].} =
  Cmd(kind: ckDelete, at: at, len: len)

func `==`*(a, b: Cmd): bool {.raises: [].} =
  if a.kind != b.kind: return false
  case a.kind
  of ckInsert: a.pos == b.pos and a.text == b.text
  of ckDelete: a.at == b.at and a.len == b.len

func `==`*(a, b: Editor): bool {.raises: [].} =
  a.text == b.text and a.undoStack == b.undoStack and a.redoStack == b.redoStack

func `$`*(c: Cmd): string {.raises: [].} =
  case c.kind
  of ckInsert: "insert(" & $c.pos & ", " & c.text & ")"
  of ckDelete: "delete(" & $c.at & ", " & $c.len & ")"

func initEditor*(text: string): Editor {.raises: [].} =
  Editor(text: text, undoStack: @[], redoStack: @[])

func onBoundary(doc: string; p: int): bool {.raises: [].} =
  ## `p` (already in `0 .. doc.len`) does not fall inside a multi-byte character.
  p == doc.len or (ord(doc[p]) and 0xC0) != 0x80

func checkInsert(doc: string; c: Cmd): Result[bool, EditError] {.raises: [].} =
  if c.pos < 0 or c.pos > doc.len: return err(bool, eeOutOfRange)
  if not onBoundary(doc, c.pos): return err(bool, eeNotCharBoundary)
  if validateUtf8(c.text) != -1: return err(bool, eeInvalidUtf8)
  ok(true, EditError)

func checkDelete(doc: string; c: Cmd): Result[bool, EditError] {.raises: [].} =
  if c.at < 0 or c.len < 0 or c.at > doc.len - c.len: return err(bool, eeOutOfRange)
  if not onBoundary(doc, c.at) or not onBoundary(doc, c.at + c.len):
    return err(bool, eeNotCharBoundary)
  ok(true, EditError)

func apply*(doc: string; cmd: Cmd): Result[string, EditError] {.raises: [].} =
  ## The pure transition. A command that points outside the document, into the middle of a
  ## character, or inserts invalid UTF-8 is an error, not a clamp.
  case cmd.kind
  of ckInsert:
    let c = checkInsert(doc, cmd)
    if c.isErr: return err(string, c.error)
    ok(doc[0 ..< cmd.pos] & cmd.text & doc[cmd.pos .. ^1], EditError)
  of ckDelete:
    let c = checkDelete(doc, cmd)
    if c.isErr: return err(string, c.error)
    ok(doc[0 ..< cmd.at] & doc[cmd.at + cmd.len .. ^1], EditError)

func inverse*(doc: string; cmd: Cmd): Result[Cmd, EditError] {.raises: [].} =
  ## The command that undoes `cmd` when run on the document produced from `doc`.
  ## It needs `doc` because a delete must remember what it removed. Same validity rules as `apply`.
  case cmd.kind
  of ckInsert:
    let c = checkInsert(doc, cmd)
    if c.isErr: return err(Cmd, c.error)
    ok(deleteCmd(cmd.pos, cmd.text.len), EditError)
  of ckDelete:
    let c = checkDelete(doc, cmd)
    if c.isErr: return err(Cmd, c.error)
    ok(insertCmd(cmd.at, doc[cmd.at ..< cmd.at + cmd.len]), EditError)

func exec*(ed: Editor; cmd: Cmd): Result[Editor, EditError] {.raises: [].} =
  ## Runs a new command: pushes its inverse on the undo stack and clears redo.
  let next = apply(ed.text, cmd)
  if next.isErr: return err(Editor, next.error)
  let inv = inverse(ed.text, cmd)
  if inv.isErr: return err(Editor, inv.error)
  ok(Editor(text: next.value, undoStack: ed.undoStack & inv.value, redoStack: @[]), EditError)

func undo*(ed: Editor): Result[Editor, EditError] {.raises: [].} =
  if ed.undoStack.len == 0: return err(Editor, eeNothingToUndo)
  let inv = ed.undoStack[^1]
  let back = apply(ed.text, inv)
  if back.isErr: return err(Editor, back.error)
  # The redo command is the inverse of the inverse, taken on the current text.
  let fwd = inverse(ed.text, inv)
  if fwd.isErr: return err(Editor, fwd.error)
  ok(Editor(text: back.value, undoStack: ed.undoStack[0 ..< ed.undoStack.len - 1],
            redoStack: ed.redoStack & fwd.value), EditError)

func redo*(ed: Editor): Result[Editor, EditError] {.raises: [].} =
  if ed.redoStack.len == 0: return err(Editor, eeNothingToRedo)
  let fwd = ed.redoStack[^1]
  let next = apply(ed.text, fwd)
  if next.isErr: return err(Editor, next.error)
  let inv = inverse(ed.text, fwd)
  if inv.isErr: return err(Editor, inv.error)
  ok(Editor(text: next.value, undoStack: ed.undoStack & inv.value,
            redoStack: ed.redoStack[0 ..< ed.redoStack.len - 1]), EditError)

func replay*(start: string; log: openArray[Cmd]): Result[string, EditError] {.raises: [].} =
  ## Folds a command log over a document; stops at the first failing command.
  var doc = start
  for c in log:
    let r = apply(doc, c)
    if r.isErr: return r
    doc = r.value
  ok(doc, EditError)

## Facade as a module that exports a small API over several private steps.
##
## The OO pattern puts one simple class in front of a set of subsystem classes. In Nim the module
## boundary is the facade: the steps (`tokenize`, `countWords`, ...) are not exported, and the
## exported surface is `normalizeText` and `summarize`. Use it when callers need one or two
## answers and should not know the order or number of internal steps. No class is needed.

import std/[algorithm, options, tables]

type
  Summary* = object
    words*: int
    unique*: int
    longest*: Option[string]
    top*: seq[(string, int)]

func isWordChar(c: char): bool {.raises: [].} =
  c in {'a' .. 'z', '0' .. '9'}

func lowerAscii(c: char): char {.raises: [].} =
  if c in {'A' .. 'Z'}: char(ord(c) + 32) else: c

func normalizeText*(text: string): string {.raises: [].} =
  ## Lower-cases ASCII letters, turns every other character into a space, collapses runs of
  ## spaces and trims. Idempotent.
  var pendingSpace = false
  for raw in text:
    let c = lowerAscii(raw)
    if isWordChar(c):
      if pendingSpace and result.len > 0:
        result.add(' ')
      pendingSpace = false
      result.add(c)
    else:
      pendingSpace = true

func tokenize(normalized: string): seq[string] =
  var current = ""
  for c in normalized:
    if c == ' ':
      if current.len > 0:
        result.add(current)
        current = ""
    else:
      current.add(c)
  if current.len > 0:
    result.add(current)

func countWords(words: seq[string]): seq[(string, int)] =
  ## Sorted by count descending, then word ascending, so the order never depends on hashing.
  var counts = initTable[string, int]()
  for w in words:
    counts[w] = counts.getOrDefault(w, 0) + 1
  for w, n in counts:
    result.add((w, n))
  result.sort(proc(a, b: (string, int)): int =
    if a[1] != b[1]: cmp(b[1], a[1]) else: cmp(a[0], b[0]))

func summarize*(text: string; topN: int = 3): Summary {.raises: [].} =
  let words = tokenize(normalizeText(text))
  let counts = countWords(words)
  var longest = none(string)
  for w in words:
    if longest.isNone or w.len > longest.get.len:
      longest = some(w)
  Summary(words: words.len, unique: counts.len, longest: longest,
          top: counts[0 ..< min(max(topN, 0), counts.len)])

## Flyweight as interning against an explicit immutable pool value.
##
## The OO pattern shares one object among many users when the objects are identical, to save memory
## and to make equality a cheap comparison. In Nim the shared thing is a `Sym` (an index) and the
## pool is a value you pass in and get back: `intern` returns the new pool and the symbol. No
## global table, so interning is deterministic and testable. `intern` copies the pool when it adds a
## string (O(pool)); to intern many strings use `internAll`, which copies once. Use it for many repeated strings
## (identifiers, font names, tags); skip it when the data is small or unique.

import std/[options, tables]

type
  Sym* = distinct int

  Pool* = object
    names: seq[string]
    index: Table[string, int]

func `==`*(a, b: Sym): bool {.borrow.}

func `==`*(a, b: Pool): bool {.raises: [].} =
  ## Pools are equal when they hold the same strings in the same order (`index` is derived).
  a.names == b.names

func initPool*(): Pool {.raises: [].} =
  Pool(names: @[], index: initTable[string, int]())

func size*(p: Pool): int {.raises: [].} =
  p.names.len

func intern*(p: Pool; s: string): tuple[pool: Pool, sym: Sym] {.raises: [].} =
  ## Symbols are numbered by first appearance. Interning a string the pool already holds returns
  ## the same pool and the same symbol (idempotent).
  if p.index.hasKey(s):
    (p, Sym(p.index.getOrDefault(s, 0)))
  else:
    var next = p
    let id = next.names.len
    next.names.add(s)
    next.index[s] = id
    (next, Sym(id))

func resolve*(p: Pool; sym: Sym): Option[string] {.raises: [].} =
  let i = int(sym)
  if i >= 0 and i < p.names.len: some(p.names[i]) else: none(string)

func internAll*(p: Pool; items: seq[string]): tuple[pool: Pool, syms: seq[Sym]] {.raises: [].} =
  ## Same result as interning one by one, but the pool is copied once, not once per new string.
  var next = p
  var syms: seq[Sym] = @[]
  for s in items:
    let known = next.index.getOrDefault(s, -1)
    if known >= 0:
      syms.add(Sym(known))
    else:
      let id = next.names.len
      next.names.add(s)
      next.index[s] = id
      syms.add(Sym(id))
  (next, syms)

## Layered architecture: modules in layers, imports in one direction, rules in the lowest layer.
##
## The program is a task board driven by text commands, split into three layers that live in
## `layered_architecture/`: `domain` (rules, imports nothing of the program), `service` (parsing
## and replies, imports `domain`) and `shell` (the effects, imports `service` and `domain`). A
## module may import a layer below it and never one above or beside it; with this rule the domain
## can be tested with no parser and the service with no terminal, and a cycle cannot form. This
## file is the composition root: it re-exports the layers and keeps `tangledBefore`, the same
## behaviour written as one routine that parses, decides and formats together. Use layers when a
## program has rules, a protocol and effects that change at different rates; skip them for a
## script. The functional-core pattern (`functional_core`) is the same split seen from the effects.

import nimcs/patterns/layered_architecture/[domain, service, shell]
export domain, service, shell

func tangledBefore*(lines: openArray[string]): seq[string] {.raises: [].} =
  ## Before: one routine that splits the line, owns the task lists and builds each reply.
  var titles: seq[string]
  var done: seq[bool]
  for line in lines:
    var verb = line
    var rest = ""
    for i in 0 ..< line.len:
      if line[i] == ' ':
        verb = line[0 ..< i]
        rest = line[i + 1 .. ^1]
        break
    if verb == "add":
      if rest.len == 0:
        result.add "error: empty title"
      else:
        titles.add rest
        done.add false
        result.add "added " & $titles.len & ": " & rest
    elif verb == "done":
      var n = 0
      var good = rest.len > 0 and rest.len <= 6
      for c in rest:
        if c < '0' or c > '9': good = false
        else: n = n * 10 + (ord(c) - ord('0'))
      if not good:
        result.add "error: bad id"
      elif n < 1 or n > titles.len:
        result.add "error: no task " & $n
      else:
        done[n - 1] = true
        result.add "done " & $n
    elif verb == "list":
      if titles.len == 0:
        result.add "(empty)"
      else:
        var s = ""
        for i in 0 ..< titles.len:
          if i > 0: s.add "; "
          s.add $(i + 1) & (if done[i]: " [x] " else: " [ ] ") & titles[i]
        result.add s
    else:
      result.add "error: unknown command"

## Load shedding: under overload, refuse some work early and say why, instead of slowing everyone.
##
## A service with a queue that grows without bound answers late to every caller. Shedding is the
## decision, taken before the work is queued, to reject a request that cannot succeed: the queue is
## full, only important work is wanted now, or the request's deadline passes before it would be
## served. `decide` is that decision as a pure function of the limits, the time, the current
## queue length and the request, so every rule is a law of a function. The ledger makes it
## idempotent per request id: a client that retries the same id gets the answer it got the first
## time, even if the queue has changed meanwhile, so a retry cannot turn a refusal into a
## double admission or an admission into a surprise. Time and queue length are arguments; the
## caller reads them. Use it at the entry of any queue with callers who can retry or give up;
## pair it with `retry_backoff` on the client side.

import std/tables
import nimcs/fp/result
export result

type
  Priority* = enum
    pLow, pHigh

  Request* = object
    id*: string
    priority*: Priority
    deadline*: int      ## absolute tick by which the answer is useless to the caller

  Reason* = enum
    rNoId, rExpired, rQueueFull, rLowPriorityShed, rDeadlineUnreachable

  Decision* = object
    case admitted*: bool
    of true:
      discard
    of false:
      reason*: Reason

  Limits* = object
    maxQueue: int
    softQueue: int
    ticksPerItem: int

  Ledger* = object
    ## The decisions already given, by request id.
    decided: Table[string, Decision]

func `==`*(a, b: Decision): bool {.raises: [].} =
  if a.admitted != b.admitted: false
  elif a.admitted: true
  else: a.reason == b.reason

func `==`*(a, b: Ledger): bool {.raises: [].} = a.decided == b.decided

func initLimits*(maxQueue, softQueue, ticksPerItem: int): Result[Limits, string] {.raises: [].} =
  ## `softQueue` is the length from which low-priority work is shed; it may not exceed `maxQueue`.
  if ticksPerItem < 1:
    err(Limits, "ticksPerItem must be at least 1")
  elif softQueue < 1 or softQueue > maxQueue:
    err(Limits, "softQueue must be in 1 .. maxQueue")
  else:
    ok(Limits(maxQueue: maxQueue, softQueue: softQueue, ticksPerItem: ticksPerItem), string)

func emptyLedger*(): Ledger {.raises: [].} = Ledger(decided: initTable[string, Decision]())

func admit(): Decision {.raises: [].} = Decision(admitted: true)

func shed(r: Reason): Decision {.raises: [].} = Decision(admitted: false, reason: r)

func judge*(l: Limits; now, queueLen: int; req: Request): Decision {.raises: [].} =
  ## The rules with no memory, checked in this order: an empty id, a deadline already past, a full
  ## queue, a queue at the soft limit for low-priority work, and a deadline that the queue ahead
  ## makes unreachable (the request needs `queueLen + 1` service times).
  if req.id.len == 0: shed(rNoId)
  elif req.deadline <= now: shed(rExpired)
  elif queueLen >= l.maxQueue: shed(rQueueFull)
  elif req.priority == pLow and queueLen >= l.softQueue: shed(rLowPriorityShed)
  elif now + (queueLen + 1) * l.ticksPerItem > req.deadline: shed(rDeadlineUnreachable)
  else: admit()

func decide*(ledger: Ledger; l: Limits; now, queueLen: int;
    req: Request): tuple[ledger: Ledger, decision: Decision] {.raises: [].} =
  ## Idempotent per id: a known id returns its first decision and the same ledger, whatever `now`
  ## and `queueLen` are now. A request with no id is judged but never recorded.
  let fresh = l.judge(now, queueLen, req)
  if req.id.len == 0:
    return (ledger, fresh)
  # A known id answers with its recorded decision; `fresh` is the answer only for an unknown id.
  let d = ledger.decided.getOrDefault(req.id, fresh)
  if ledger.decided.hasKey(req.id):
    return (ledger, d)
  var next = ledger
  next.decided[req.id] = d
  (next, d)

func decidedCount*(ledger: Ledger): int {.raises: [].} = ledger.decided.len

func knows*(ledger: Ledger; id: string): bool {.raises: [].} = ledger.decided.hasKey(id)

## Object capability: authority only by reference (ADR-NCK-0002).
##
## A capability is a value that names a resource and, by existing, grants the right to use it in
## specific ways. There is no ambient authority: no function here reaches a file, a global or a
## clock on its own; every operation takes the capability (and the `Store` it acts on) as an
## argument, so reading a signature tells you what a routine may touch. `FileCap` is sealed (a
## private field and `{.requiresInit.}`), so code outside this module cannot write
## `FileCap(rights: ...)` or declare an empty one; the only ways to get one are `rootCap` and the
## attenuations `readOnly`, `restrict` and `narrow`, and each of them returns a capability that
## permits no more than the one it came from. Delegation is passing the value.
##
## Honest limit: Nim cannot hide `rootCap`, the one function that creates authority from nothing.
## The convention is the powerbox: call it only at the program's edge (`main`), and hand narrower
## capabilities inward. A review (or a text search) for `rootCap` finds every place that can
## create authority. The `Store` is a plain persistent value standing for the resource; a real
## program applies the same shape to a directory, a socket or a device.

import std/[options, strutils]
import nimcs/ds/hamt
import nimcs/fp/result

type
  Right* = enum
    rtRead, rtWrite

  CapError* = enum
    ceDenied      ## the capability lacks the right
    ceOutside     ## the path is not below the capability's prefix
    ceBadPath     ## empty, absolute, or containing an empty, `.` or `..` segment
    ceNotFound

  FileCap* {.requiresInit.} = object
    ## Rights and a path prefix (whole segments). The empty prefix covers every path.
    held: set[Right]
    base: seq[string]

  Store* = Hamt[string, string]

func segments(path: string): Option[seq[string]] =
  ## The segments of a relative path, or `none` if any segment is empty, `.` or `..`.
  if path.len == 0: return none(seq[string])
  let parts = path.split('/')
  for p in parts:
    if p.len == 0 or p == "." or p == "..": return none(seq[string])
  some(parts)

func rootCap*(rights: set[Right]): FileCap {.raises: [].} =
  ## Authority from nothing: call it once, at the program's edge.
  FileCap(held: rights, base: @[])

func rights*(c: FileCap): set[Right] {.raises: [].} = c.held

func prefix*(c: FileCap): string {.raises: [].} = c.base.join("/")

func `==`*(a, b: FileCap): bool {.raises: [].} = a.held == b.held and a.base == b.base

func restrict*(c: FileCap; keep: set[Right]): FileCap {.raises: [].} =
  ## Keeps only the rights in `keep`; it can drop rights, never add them.
  FileCap(held: c.held * keep, base: c.base)

func readOnly*(c: FileCap): FileCap {.raises: [].} = c.restrict({rtRead})

func narrow*(c: FileCap; sub: string): Result[FileCap, CapError] {.raises: [].} =
  ## A capability for the directory `sub` below this one's prefix (`sub` is a relative path).
  let s = segments(sub)
  if s.isNone: return err(FileCap, ceBadPath)
  ok(FileCap(held: c.held, base: c.base & s.get), CapError)

func check(c: FileCap; right: Right; path: string): Result[bool, CapError] =
  let s = segments(path)
  if s.isNone: return err(bool, ceBadPath)
  if right notin c.held: return err(bool, ceDenied)
  if s.get.len <= c.base.len: return err(bool, ceOutside)
  for i in 0 ..< c.base.len:
    if s.get[i] != c.base[i]: return err(bool, ceOutside)
  ok(true, CapError)

func permits*(c: FileCap; right: Right; path: string): bool {.raises: [].} =
  c.check(right, path).isOk

func emptyStore*(): Store {.raises: [].} = emptyHamt[string, string]()

func read*(store: Store; c: FileCap; path: string): Result[string, CapError] {.raises: [].} =
  let allowed = c.check(rtRead, path)
  if allowed.isErr: return err(string, allowed.error)
  let found = store.get(path)
  if found.isNone: err(string, ceNotFound) else: ok(found.get, CapError)

func write*(store: Store; c: FileCap; path, data: string): Result[Store, CapError] {.raises: [].} =
  ## Returns the new store; the argument is unchanged.
  let allowed = c.check(rtWrite, path)
  if allowed.isErr: return err(Store, allowed.error)
  ok(store.put(path, data), CapError)

## Parallel change (expand, migrate, contract): change a shape without a moment when callers break.
##
## A change to something many callers use (a column, a field, a function's argument) is done in
## three steps that each leave every caller working: expand (the new shape exists next to the old
## one and every writer keeps both in step), migrate (fill the new shape for data written before,
## move callers one at a time) and contract (remove the old shape once nothing reads it). Here a
## person's name moves from one legacy text, "Family, Given", to a `Name` with two parts. A record
## holds both columns; writers through either door set both, readers fall back to translating the
## other column, `backfill` fills rows that predate the change, and `contract` is a function that
## refuses to drop the legacy column while any row would lose its only copy. Use it when callers
## cannot all be changed in one commit or one deploy; it costs a period with two shapes, so give the
## period an end.

import std/options
import nimcs/fp/result
export result

type
  NameError* = enum
    neEmptyGiven, neEmptyFamily, neComma, neNoSeparator

  Name* = object
    given*, family*: string

  Record* = object
    ## During expand both fields may be set. A row written before the change has only `legacy`;
    ## after contract only `current` is set.
    legacy*: Option[string]
    current*: Option[Name]

  Store* = seq[Record]

  ContractError* = object
    firstUnmigrated*: int   ## index of the first row with no current name

const Separator = ", "

func initName*(given, family: string): Result[Name, NameError] {.raises: [].} =
  ## A part may be neither empty nor contain a comma, so the legacy text splits back uniquely.
  if given.len == 0:
    err(Name, neEmptyGiven)
  elif family.len == 0:
    err(Name, neEmptyFamily)
  elif ',' in given or ',' in family:
    err(Name, neComma)
  else:
    ok(Name(given: given, family: family), NameError)

func formatLegacy*(n: Name): string {.raises: [].} = n.family & Separator & n.given

func parseLegacy*(s: string): Result[Name, NameError] {.raises: [].} =
  ## Splits at the first separator; every other shape is an error, never an exception.
  var at = -1
  for i in 0 ..< s.len - 1:
    if s[i] == ',' and s[i + 1] == ' ':
      at = i
      break
  if at < 0:
    err(Name, neNoSeparator)
  else:
    initName(s[at + Separator.len .. ^1], s[0 ..< at])

func writeCurrent*(n: Name): Record {.raises: [].} =
  ## The new door keeps the old column in step so legacy readers stay right.
  Record(legacy: some(formatLegacy(n)), current: some(n))

func writeLegacy*(s: string): Result[Record, NameError] {.raises: [].} =
  ## The old door keeps the new column in step; a text that does not parse is refused here, not
  ## stored where only one reader could use it.
  let parsed = parseLegacy(s)
  if parsed.isOk:
    ok(Record(legacy: some(s), current: some(parsed.value)), NameError)
  else:
    err(Record, parsed.error)

func readCurrent*(r: Record): Option[Name] {.raises: [].} =
  if r.current.isSome:
    r.current
  elif r.legacy.isSome:
    let parsed = parseLegacy(r.legacy.get)
    if parsed.isOk: some(parsed.value) else: none(Name)
  else:
    none(Name)

func readLegacy*(r: Record): Option[string] {.raises: [].} =
  ## Kept after contract only to show that an old caller would still get the same answer.
  if r.legacy.isSome:
    r.legacy
  elif r.current.isSome:
    some(formatLegacy(r.current.get))
  else:
    none(string)

func backfill*(r: Record): Record {.raises: [].} =
  ## Fills the current name of a row written before the change. Idempotent; a text that does not
  ## parse stays as it is, for a person to look at.
  if r.current.isNone:
    Record(legacy: r.legacy, current: readCurrent(r))
  else:
    r

func contract*(s: Store): Result[Store, ContractError] {.raises: [].} =
  ## Drops the legacy column, but only when no row would lose its only copy of the name.
  for i, r in s:
    if r.current.isNone:
      return err(Store, ContractError(firstUnmigrated: i))
  var done: Store = @[]
  for r in s:
    done.add Record(legacy: none(string), current: r.current)
  ok(done, ContractError)

## Parser combinators: small parsers are values, and bigger parsers are functions of them.
##
## A `Parser[T]` takes the input and a position and returns either a value with the position
## after it, or a `ParseError` saying where and what was expected. Nothing is thrown and nothing
## is mutated, so a parser is a pure function you can test on any string. Combinators (`thenP`,
## `orElse`, `many`, `chainl1`, `between`) build larger parsers from smaller ones, and the
## grammar of arithmetic below reads like its own specification. Use it for small formats where a
## parser generator is too heavy; for large or ambiguous grammars use a generator. Alternatives
## are tried left to right and the first success wins (no backtracking into a chosen branch).

import nimcs/fp/result

type
  ParseError* = object
    pos*: int
    expected*: string

  Parsed*[T] = object
    value*: T
    next*: int  ## position just after what was consumed

  Parser*[T] = proc(input: string; pos: int): Result[Parsed[T], ParseError] {.noSideEffect, raises: [].}

  CharTest* = proc(c: char): bool {.noSideEffect, raises: [].}

  BinOp* = enum
    opAdd, opSub, opMul

  ExprKind* = enum
    ekNum, ekBin

  Expr* = ref ExprNode
  ExprNode* = object
    ## An immutable tree: build it with `num` and `bin`, never assign to a field.
    case kind*: ExprKind
    of ekNum:
      value*: int
    of ekBin:
      op*: BinOp
      left*, right*: Expr

  EvalError* = enum
    eeOutOfRange

const MaxLiteral* = 999_999_999
const MaxNesting* = 64      ## deepest parenthesis nesting `parseArithmetic` accepts
const MaxInputLen* = 1024   ## longest input `parseArithmetic` accepts, in bytes
const ValueLimit* = 2_147_483_648  ## intermediate results beyond +-2^31 are refused

# ── combinators ────────────────────────────────────────────────────────────

func satisfy*(test: CharTest; what: string): Parser[char] {.raises: [].} =
  ## One character that passes `test`; `what` names it in the error.
  proc(input: string; pos: int): Result[Parsed[char], ParseError] {.noSideEffect, raises: [].} =
    if pos >= 0 and pos < input.len and test(input[pos]):
      ok(Parsed[char](value: input[pos], next: pos + 1), ParseError)
    else:
      err(Parsed[char], ParseError(pos: pos, expected: what))

func charP*(c: char): Parser[char] {.raises: [].} =
  satisfy(proc(x: char): bool {.noSideEffect, raises: [].} = x == c, "'" & c & "'")

func digit*(): Parser[char] {.raises: [].} =
  satisfy(proc(x: char): bool {.noSideEffect, raises: [].} = x in {'0' .. '9'}, "a digit")

func mapP*[T, U](p: Parser[T]; f: proc(x: T): U {.noSideEffect, raises: [].}): Parser[U] {.raises: [].} =
  ## Changes the value of a successful parse.
  proc(input: string; pos: int): Result[Parsed[U], ParseError] {.noSideEffect, raises: [].} =
    let r = p(input, pos)
    if r.isOk: ok(Parsed[U](value: f(r.value.value), next: r.value.next), ParseError)
    else: err(Parsed[U], r.error)

func flatMapP*[T, U](p: Parser[T]; f: proc(x: T): Result[U, string] {.noSideEffect, raises: [].}): Parser[U] {.raises: [].} =
  ## Like `mapP`, but `f` may refuse the value; its message becomes the error at the start position.
  proc(input: string; pos: int): Result[Parsed[U], ParseError] {.noSideEffect, raises: [].} =
    let r = p(input, pos)
    if r.isErr: return err(Parsed[U], r.error)
    let mapped = f(r.value.value)
    if mapped.isOk: ok(Parsed[U](value: mapped.value, next: r.value.next), ParseError)
    else: err(Parsed[U], ParseError(pos: pos, expected: mapped.error))

func thenP*[A, B](p: Parser[A]; q: Parser[B]): Parser[(A, B)] {.raises: [].} =
  ## `p` then `q`; both values are kept.
  proc(input: string; pos: int): Result[Parsed[(A, B)], ParseError] {.noSideEffect, raises: [].} =
    let a = p(input, pos)
    if a.isErr: return err(Parsed[(A, B)], a.error)
    let b = q(input, a.value.next)
    if b.isErr: err(Parsed[(A, B)], b.error)
    else: ok(Parsed[(A, B)](value: (a.value.value, b.value.value), next: b.value.next), ParseError)

func orElse*[T](p, q: Parser[T]): Parser[T] {.raises: [].} =
  ## `p`'s result when it succeeds, otherwise `q`'s. When both fail, the error is the one that
  ## got further; when they failed at the same position, the expectations are joined with "or".
  proc(input: string; pos: int): Result[Parsed[T], ParseError] {.noSideEffect, raises: [].} =
    let a = p(input, pos)
    if a.isOk: return a
    let b = q(input, pos)
    if b.isOk: return b
    if a.error.pos > b.error.pos: err(Parsed[T], a.error)
    elif b.error.pos > a.error.pos: err(Parsed[T], b.error)
    elif a.error.expected == b.error.expected: err(Parsed[T], b.error)
    else: err(Parsed[T], ParseError(pos: a.error.pos, expected: a.error.expected & " or " & b.error.expected))

func many*[T](p: Parser[T]): Parser[seq[T]] {.raises: [].} =
  ## Zero or more repetitions; it never fails. A repetition that consumes nothing ends the loop,
  ## so a parser that can succeed on empty input cannot make it spin.
  proc(input: string; pos: int): Result[Parsed[seq[T]], ParseError] {.noSideEffect, raises: [].} =
    var items: seq[T]
    var cur = pos
    while true:
      let r = p(input, cur)
      if r.isErr or r.value.next <= cur: break
      items.add r.value.value
      cur = r.value.next
    ok(Parsed[seq[T]](value: items, next: cur), ParseError)

func many1*[T](p: Parser[T]): Parser[seq[T]] {.raises: [].} =
  ## One or more repetitions; the error is that of the first attempt.
  proc(input: string; pos: int): Result[Parsed[seq[T]], ParseError] {.noSideEffect, raises: [].} =
    let first = p(input, pos)
    if first.isErr: return err(Parsed[seq[T]], first.error)
    let rest = many(p)(input, first.value.next)
    if rest.isErr: return err(Parsed[seq[T]], rest.error)
    ok(Parsed[seq[T]](value: @[first.value.value] & rest.value.value, next: rest.value.next), ParseError)

func skipSpaces*(): Parser[int] {.raises: [].} =
  ## Skips blanks and returns how many; never fails.
  many(satisfy(proc(x: char): bool {.noSideEffect, raises: [].} = x == ' ', "a space")).mapP(
    proc(xs: seq[char]): int {.noSideEffect, raises: [].} = xs.len)

func token*[T](p: Parser[T]): Parser[T] {.raises: [].} =
  ## `p` followed by any blanks, whose count is dropped.
  proc(input: string; pos: int): Result[Parsed[T], ParseError] {.noSideEffect, raises: [].} =
    let r = p(input, pos)
    if r.isErr: return r
    let blanks = skipSpaces()(input, r.value.next)
    if blanks.isErr: return err(Parsed[T], blanks.error)
    ok(Parsed[T](value: r.value.value, next: blanks.value.next), ParseError)

func between*[O, T, C](open: Parser[O]; p: Parser[T]; close: Parser[C]): Parser[T] {.raises: [].} =
  ## `open`, then `p`, then `close`; keeps only `p`'s value.
  proc(input: string; pos: int): Result[Parsed[T], ParseError] {.noSideEffect, raises: [].} =
    let o = open(input, pos)
    if o.isErr: return err(Parsed[T], o.error)
    let inner = p(input, o.value.next)
    if inner.isErr: return inner
    let c = close(input, inner.value.next)
    if c.isErr: return err(Parsed[T], c.error)
    ok(Parsed[T](value: inner.value.value, next: c.value.next), ParseError)

func lazyP*[T](make: proc(): Parser[T] {.noSideEffect, raises: [].}): Parser[T] {.raises: [].} =
  ## Builds the parser only when it first runs, which lets a grammar rule refer to itself.
  proc(input: string; pos: int): Result[Parsed[T], ParseError] {.noSideEffect, raises: [].} =
    make()(input, pos)

func chainl1*[T, O](operand: Parser[T]; op: Parser[O];
                    combine: proc(o: O; l, r: T): T {.noSideEffect, raises: [].}): Parser[T] {.raises: [].} =
  ## `operand (op operand)*`, combined from the left: `1-2-3` is `(1-2)-3`. Once an operator has
  ## been read, a missing operand is an error rather than a silent stop.
  proc(input: string; pos: int): Result[Parsed[T], ParseError] {.noSideEffect, raises: [].} =
    let first = operand(input, pos)
    if first.isErr: return first
    var acc = first.value.value
    var cur = first.value.next
    while true:
      let o = op(input, cur)
      if o.isErr: break
      let rhs = operand(input, o.value.next)
      if rhs.isErr: return err(Parsed[T], rhs.error)
      acc = combine(o.value.value, acc, rhs.value.value)
      cur = rhs.value.next
    ok(Parsed[T](value: acc, next: cur), ParseError)

# ── the expression type ────────────────────────────────────────────────────

func `==`*(a, b: Expr): bool {.raises: [].} =
  ## Structural equality (the default for `ref` would compare addresses).
  if a.isNil or b.isNil: return a.isNil and b.isNil
  if a.kind != b.kind: return false
  case a.kind
  of ekNum: a.value == b.value
  of ekBin: a.op == b.op and a.left == b.left and a.right == b.right

func num*(v: range[0 .. MaxLiteral]): Expr {.raises: [].} =
  ## A literal. Out-of-range values raise a `RangeDefect`: callers can check the bound.
  Expr(kind: ekNum, value: v)

func bin*(op: BinOp; left, right: Expr): Expr {.raises: [].} =
  Expr(kind: ekBin, op: op, left: left, right: right)

func opChar(op: BinOp): char {.raises: [].} =
  case op
  of opAdd: '+'
  of opSub: '-'
  of opMul: '*'

func print*(e: Expr): string {.raises: [].} =
  ## Fully parenthesised, no spaces: `((1+2)*3)`. `parseArithmetic` reads it back to the same tree.
  case e.kind
  of ekNum: $e.value
  of ekBin: "(" & print(e.left) & $opChar(e.op) & print(e.right) & ")"

func printSpaced*(e: Expr): string {.raises: [].} =
  ## Like `print` with one blank between tokens: `( ( 1 + 2 ) * 3 )`.
  case e.kind
  of ekNum: $e.value
  of ekBin: "( " & printSpaced(e.left) & " " & $opChar(e.op) & " " & printSpaced(e.right) & " )"

func evaluate*(e: Expr): Result[int, EvalError] {.raises: [].} =
  ## Evaluates in `int`; an intermediate value beyond +-2^31 is `eeOutOfRange`, which also keeps
  ## every product inside 64 bits.
  case e.kind
  of ekNum: ok(e.value, EvalError)
  of ekBin:
    let l = evaluate(e.left)
    if l.isErr: return l
    let r = evaluate(e.right)
    if r.isErr: return r
    let v =
      case e.op
      of opAdd: l.value + r.value
      of opSub: l.value - r.value
      of opMul: l.value * r.value
    if abs(v) > ValueLimit: err(int, eeOutOfRange) else: ok(v, EvalError)

# ── the grammar ────────────────────────────────────────────────────────────
#   expr   = term   (('+' | '-') term)*
#   term   = factor ('*' factor)*
#   factor = number | '(' expr ')'

func exprP*(): Parser[Expr] {.raises: [].}

func numberP(): Parser[Expr] {.raises: [].} =
  token(many1(digit())).flatMapP(
    proc(ds: seq[char]): Result[Expr, string] {.noSideEffect, raises: [].} =
      if ds.len > 9:
        err(Expr, "a number of at most 9 digits")
      else:
        var n = 0
        for c in ds: n = n * 10 + (ord(c) - ord('0'))
        ok(num(n), string))

func combineOp(o: BinOp; l, r: Expr): Expr {.raises: [].} = bin(o, l, r)

func addOp(): Parser[BinOp] {.raises: [].} =
  let plus = token(charP('+')).mapP(proc(c: char): BinOp {.noSideEffect, raises: [].} = opAdd)
  let minus = token(charP('-')).mapP(proc(c: char): BinOp {.noSideEffect, raises: [].} = opSub)
  orElse(plus, minus)

func mulOp(): Parser[BinOp] {.raises: [].} =
  token(charP('*')).mapP(proc(c: char): BinOp {.noSideEffect, raises: [].} = opMul)

func factorP(): Parser[Expr] {.raises: [].} =
  orElse(numberP(), between(token(charP('(')), lazyP(exprP), token(charP(')'))))

func termP(): Parser[Expr] {.raises: [].} =
  chainl1(factorP(), mulOp(), combineOp)

func exprP*(): Parser[Expr] {.raises: [].} =
  chainl1(termP(), addOp(), combineOp)

func parseArithmetic*(input: string): Result[Expr, ParseError] {.raises: [].} =
  ## Parses the whole input (blanks allowed around tokens). Unconsumed input is an error at the
  ## position where it starts. Input longer than `MaxInputLen` or nested deeper than `MaxNesting`
  ## is refused with an error before parsing, because recursion depth (here and in `print`,
  ## `evaluate`, `==`) follows nesting and chain length. `exprP()` called directly has no limit.
  if input.len > MaxInputLen:
    return err(Expr, ParseError(pos: MaxInputLen, expected: "input of at most " & $MaxInputLen & " bytes"))
  var depth = 0
  for i, c in input:
    if c == '(':
      inc depth
      if depth > MaxNesting:
        return err(Expr, ParseError(pos: i, expected: "nesting of at most " & $MaxNesting & " levels"))
    elif c == ')' and depth > 0:
      dec depth
  let lead = skipSpaces()(input, 0)
  if lead.isErr: return err(Expr, lead.error)
  let r = exprP()(input, lead.value.next)
  if r.isErr: return err(Expr, r.error)
  if r.value.next != input.len:
    return err(Expr, ParseError(pos: r.value.next, expected: "end of input"))
  ok(r.value.value, ParseError)

## Seam: a place where behaviour can be changed without editing the code at that place.
##
## Legacy code reaches for what it needs (a price list, a clock, a database) from inside, so it
## cannot be run, or tested, without all of it. A seam is a point where the call can be redirected:
## in functional Nim the simplest is a parameter, a proc the routine is handed (a *function seam*;
## a record of procs is the same idea for several operations). Making a seam must not change what the
## routine does, so the first test is old against new on the same inputs. With the seam in place a
## test supplies its own answers, and a pinned list of input and output pairs (a characterization)
## says whether a later change kept the behaviour nobody wrote down. Here a hard-wired price list
## becomes a seam. The old routine counted an unknown SKU as 0; the seam version says so instead
## of inventing a price, which is the one difference, shown by its own law. Use it before changing code
## you cannot yet test, and keep the default seam equal to the old wiring until the pins are green.

import std/options
import nimcs/fp/result
export result

type
  Seam* = proc(sku: string): Option[int] {.noSideEffect, raises: [].}
    ## Answers the price of a SKU in cents, or none when it does not know the SKU.

  PriceError* = object
    unknownSku*: string

  Total* = proc(skus: seq[string]): int {.noSideEffect, raises: [].}

  Pin* = tuple[input: seq[string], output: int]

  Pins* = seq[Pin]

func hardWiredPrice(sku: string): int {.raises: [].} =
  case sku
  of "apple": 120
  of "pear": 150
  of "fig": 300
  else: 0   # what the legacy routine did with a SKU it did not know

func discounted(sum, lines: int): int {.raises: [].} =
  ## Three or more lines earn a tenth off, rounded down.
  if lines >= 3: sum - sum div 10 else: sum

func legacyTotal*(skus: seq[string]): int {.raises: [].} =
  ## The routine before the seam: the price list is inside.
  var sum = 0
  for s in skus:
    sum += hardWiredPrice(s)
  discounted(sum, skus.len)

func defaultSeam*(): Seam {.raises: [].} =
  ## The old wiring as a seam: the same list, but an unknown SKU is none, not 0.
  proc(sku: string): Option[int] {.noSideEffect, raises: [].} =
    if sku in ["apple", "pear", "fig"]: some(hardWiredPrice(sku)) else: none(int)

func total*(prices: Seam; skus: seq[string]): Result[int, PriceError] {.raises: [].} =
  ## The same arithmetic with the lookup handed in; the first unknown SKU is the error.
  var sum = 0
  for s in skus:
    let p = prices(s)
    if p.isNone:
      return err(int, PriceError(unknownSku: s))
    sum += p.get
  ok(discounted(sum, skus.len), PriceError)

func pin*(f: Total; inputs: seq[seq[string]]): Pins {.raises: [].} =
  ## Records what `f` does now, input by input.
  for i in inputs:
    result.add (input: i, output: f(i))

func firstDifference*(pins: Pins; f: Total): Option[int] {.raises: [].} =
  ## The index of the first pinned input on which `f` no longer gives the pinned output.
  for i, p in pins:
    if f(p.input) != p.output:
      return some(i)
  none(int)

func holds*(pins: Pins; f: Total): bool {.raises: [].} = firstDifference(pins, f).isNone

## Strategy: the algorithm you swap is a function value.
##
## The OO pattern puts each interchangeable algorithm in its own class behind one interface so the
## caller can choose at run time. In Nim the interface is a proc type, the classes are procs (or
## closures made by a constructor func), and "choosing" is passing an argument. Here the varying
## part is how an order total is discounted; `checkout` never learns which rule it received. Use it
## when one step of a computation has several interchangeable implementations. When the choice is
## fixed at compile time, the proc can be passed as a generic parameter instead (`total2` below);
## that removes the closure but is not a promise of inlining.
##
## Prices are `Cents >= 0` (see `cents`); amounts near `high(int)` are handled without overflow.

import std/options

type
  Cents* = distinct int

  PriceRule* = proc(price: Cents): Cents {.noSideEffect, raises: [].}
    ## A strategy: maps a price to a price. The constructors below keep results in `0 .. price`.

func `==`*(a, b: Cents): bool {.borrow.}
func `<=`*(a, b: Cents): bool {.borrow.}
func `<`*(a, b: Cents): bool {.borrow.}
func `$`*(a: Cents): string {.borrow.}

func cents*(n: int): Option[Cents] {.raises: [].} =
  ## Smart constructor: a price is never negative.
  if n < 0: none(Cents) else: some(Cents(n))

func value*(c: Cents): int {.raises: [].} = int(c)

func noDiscount*(price: Cents): Cents {.raises: [].} =
  ## The identity strategy.
  price

func percentOff*(pct: int): PriceRule {.raises: [].} =
  ## Takes `pct` percent off, rounding the discount down. `pct` is clamped into 0..100.
  ## The discount is computed as `q*p + (r*p) div 100` for `price = 100*q + r`, which equals
  ## `(price*p) div 100` for non-negative prices without ever forming `price*p` (no overflow).
  let p = max(0, min(100, pct))
  result = proc(price: Cents): Cents {.noSideEffect, raises: [].} =
    let v = value(price)
    Cents(v - ((v div 100) * p + ((v mod 100) * p) div 100))

func flatOff*(amount: int): PriceRule {.raises: [].} =
  ## Takes a fixed amount off, never going below zero. A negative amount counts as zero.
  let a = max(0, amount)
  result = proc(price: Cents): Cents {.noSideEffect, raises: [].} =
    if value(price) <= a: Cents(0) else: Cents(value(price) - a)

func then*(first, second: PriceRule): PriceRule {.raises: [].} =
  ## Applies `first`, then `second` to its result.
  result = proc(price: Cents): Cents {.noSideEffect, raises: [].} =
    second(first(price))

func sumSaturating(items: openArray[Cents]): Cents {.raises: [].} =
  ## Sum of the items; a total beyond `high(int)` stays at `high(int)` instead of overflowing.
  var sum = 0
  for it in items:
    let x = value(it)
    sum = if x > 0 and sum > high(int) - x: high(int) else: sum + x
  Cents(sum)

func checkout*(items: openArray[Cents]; rule: PriceRule): Cents {.raises: [].} =
  ## The context: sums the items (saturating at `high(int)`), then lets the strategy decide the
  ## final price. Items are assumed non-negative (build them with `cents`).
  rule(sumSaturating(items))

func total2*[R](items: openArray[Cents]; rule: R): Cents {.raises: [].} =
  ## Same, with the strategy as a generic parameter: the rule's type is known at compile time, so
  ## no closure is required (whether the C compiler inlines the call is not guaranteed; measure).
  rule(sumSaturating(items))

func cheapest*(rules: openArray[PriceRule]; price: Cents): Cents {.raises: [].} =
  ## Best price over all strategies (no rules: the price itself).
  result = price
  for r in rules:
    let p = r(price)
    if p < result: result = p

## Tagless final: write the program once against an interface, choose the meaning by choosing a type.
##
## A program such as `dotProduct` is a generic function over a type `R` that satisfies `ExprSym`:
## it can make a literal and combine two values. It never says what `R` is. Instantiate it with
## `Eval` and you get the number, with `Show` the text, with `Size` a node count, with `Ast` a
## data tree. Compared with `free_interpreter` the program is not data you can inspect or
## rewrite, but there is no interpreter loop and no instruction type: adding an interpreter means
## adding a type and four small funcs, and adding an operation means adding a func to the concept
## and to each interpreter. Use it when the set of operations is stable and the set of
## interpretations grows.

type
  Eval* = distinct int     ## interpretation: the value
  Show* = distinct string  ## interpretation: fully parenthesised text
  Size* = distinct int     ## interpretation: number of nodes

  AstKind = enum
    akLit, akAdd, akMul, akNeg

  AstNode = object
    case kind: AstKind
    of akLit: n: int
    of akAdd, akMul:
      left, right: Ast
    of akNeg: inner: Ast

  Ast* = ref AstNode  ## interpretation: the program reified as an immutable tree

  ExprSym* = concept
    ## The interface a program is written against.
    proc lit(t: typedesc[Self]; n: int): Self
    proc add(a, b: Self): Self
    proc mul(a, b: Self): Self
    proc neg(a: Self): Self

# ── Eval ───────────────────────────────────────────────────────────────────

func lit*(t: typedesc[Eval]; n: int): Eval {.raises: [].} = Eval(n)
func add*(a, b: Eval): Eval {.raises: [].} = Eval(int(a) + int(b))
func mul*(a, b: Eval): Eval {.raises: [].} = Eval(int(a) * int(b))
func neg*(a: Eval): Eval {.raises: [].} = Eval(-int(a))
func value*(e: Eval): int {.raises: [].} = int(e)

# ── Show ───────────────────────────────────────────────────────────────────

func lit*(t: typedesc[Show]; n: int): Show {.raises: [].} = Show($n)
func add*(a, b: Show): Show {.raises: [].} = Show("(" & string(a) & "+" & string(b) & ")")
func mul*(a, b: Show): Show {.raises: [].} = Show("(" & string(a) & "*" & string(b) & ")")
func neg*(a: Show): Show {.raises: [].} = Show("-(" & string(a) & ")")
func text*(s: Show): string {.raises: [].} = string(s)

# ── Size ───────────────────────────────────────────────────────────────────

func lit*(t: typedesc[Size]; n: int): Size {.raises: [].} = Size(1)
func add*(a, b: Size): Size {.raises: [].} = Size(int(a) + int(b) + 1)
func mul*(a, b: Size): Size {.raises: [].} = Size(int(a) + int(b) + 1)
func neg*(a: Size): Size {.raises: [].} = Size(int(a) + 1)
func nodes*(s: Size): int {.raises: [].} = int(s)

# ── Ast (the initial encoding, for comparison) ─────────────────────────────

func lit*(t: typedesc[Ast]; n: int): Ast {.raises: [].} = Ast(kind: akLit, n: n)
func add*(a, b: Ast): Ast {.raises: [].} = Ast(kind: akAdd, left: a, right: b)
func mul*(a, b: Ast): Ast {.raises: [].} = Ast(kind: akMul, left: a, right: b)
func neg*(a: Ast): Ast {.raises: [].} = Ast(kind: akNeg, inner: a)

func evalAst*(a: Ast): int {.raises: [].} =
  ## Evaluates a reified tree; equals interpreting the program under `Eval`.
  case a.kind
  of akLit: a.n
  of akAdd: evalAst(a.left) + evalAst(a.right)
  of akMul: evalAst(a.left) * evalAst(a.right)
  of akNeg: -evalAst(a.inner)

func sizeAst*(a: Ast): int {.raises: [].} =
  case a.kind
  of akLit: 1
  of akAdd, akMul: sizeAst(a.left) + sizeAst(a.right) + 1
  of akNeg: sizeAst(a.inner) + 1

func printAst*(a: Ast): string {.raises: [].} =
  case a.kind
  of akLit: $a.n
  of akAdd: "(" & printAst(a.left) & "+" & printAst(a.right) & ")"
  of akMul: "(" & printAst(a.left) & "*" & printAst(a.right) & ")"
  of akNeg: "-(" & printAst(a.inner) & ")"

# ── programs: written once, for every interpretation ───────────────────────

func dotProduct*[R: ExprSym](pairs: openArray[(int, int)]): R {.raises: [].} =
  ## 0 + a1*b1 + a2*b2 + ..., left to right.
  result = lit(R, 0)
  for (a, b) in pairs:
    result = add(result, mul(lit(R, a), lit(R, b)))

func horner*[R: ExprSym](coeffs: openArray[int]; x: int): R {.raises: [].} =
  ## The polynomial with the given coefficients (highest degree first) at `x`, by Horner's rule.
  if coeffs.len == 0:
    return lit(R, 0)
  result = lit(R, coeffs[0])
  for i in 1 ..< coeffs.len:
    result = add(mul(result, lit(R, x)), lit(R, coeffs[i]))

func negated*[R: ExprSym](pairs: openArray[(int, int)]): R {.raises: [].} =
  ## A program built from another program: the negated dot product.
  neg(dotProduct[R](pairs))

# SPEC: STR-AHOCORASICK-02
test "STR-AHOCORASICK-02 Given patterns that overlap or contain one another, when searching, then every occurrence is reported once":
  let a = automaton(@["a", "aa", "aaa"])
  check a.findAll("aaaa").len == 4 + 3 + 2
  let b = automaton(@["abab", "ab", "b"])
  check b.findAll("ababab") == naiveFindAll("ababab", @["abab", "ab", "b"])

# SPEC: STR-AHOCORASICK-04
test "STR-AHOCORASICK-04 Given any text and pattern set, when counting, then each count equals the matches of that pattern":
  let outcome = check(inputs(), proc(p: (string, seq[string])): bool {.raises: [CatchableError].} =
    let a = automaton(p[1])
    var expected = newSeq[int](p[1].len)
    for m in a.findAll(p[0]):
      inc expected[m.pattern]
    a.countAll(p[0]) == expected and a.patternCount == p[1].len)
  checkpoint describe(outcome)
  check outcome.passed

# SPEC: STR-AHOCORASICK-07
test "STR-AHOCORASICK-07 Given one automaton, when searching twice or after rebuilding, then the answers repeat":
  let outcome = check(inputs(), proc(p: (string, seq[string])): bool {.raises: [CatchableError].} =
    let a = automaton(p[1])
    let first = a.findAll(p[0])
    first == a.findAll(p[0]) and first == automaton(p[1]).findAll(p[0]))
  checkpoint describe(outcome)
  check outcome.passed

# SPEC: ANALYSIS-AMORT-03
test "ANALYSIS-AMORT-03 Given any run of doubling appends, when the potential method is applied, then every amortized cost is at most 3 and the potential never goes negative":
  let outcome = check(intIn(1, 400), proc(n: int): bool {.raises: [CatchableError].} =
    let steps = appendSteps(n, gDoubling)
    let amortized = doublingAmortizedCosts(n)
    if amortized.len != n: return false
    var sumAmortized = 0
    for i, a in amortized:
      if a > 3 or potential(steps[i].size, steps[i].capacity) < 0: return false
      sumAmortized += a
    sumAmortized >= steps.totalCost)       # the credits pay for every real cost
  checkpoint describe(outcome)
  check outcome.passed

# SPEC: ANALYSIS-ASYMP-01
test "ANALYSIS-ASYMP-01 Given n distinct numbers, when duplicates are searched pair by pair, then exactly n(n-1)/2 comparisons are made":
  let outcome = check(intIn(0, 60), proc(n: int): bool {.raises: [CatchableError].} =
    let xs = toSeq(0 ..< n)
    let r = naiveDuplicateComparisons(xs)
    not r.found and r.comparisons == n * (n - 1) div 2)
  checkpoint describe(outcome)
  check outcome.passed

# SPEC: ANALYSIS-ASYMP-02
test "ANALYSIS-ASYMP-02 Given any sorted sequence and key, when binary searched, then the probes never exceed floor(log2 n) + 1":
  let outcome = check(pair(sortedInts(), intIn(-25, 25)), proc(c: (seq[int], int)): bool {.raises: [CatchableError].} =
    let (xs, x) = c
    let probes = binarySearchSteps(xs, x)
    if xs.len == 0: probes == 0 else: probes >= 1 and probes <= floorLog2(xs.len) + 1)
  checkpoint describe(outcome)
  check outcome.passed

# SPEC: APPROX-VC-02
test "APPROX-VC-02 Given any undirected graph, when covering, then the matching is disjoint and the cover has at most twice its size":
  let outcome = check(raws(), proc(raw: Raw): bool {.raises: [CatchableError].} =
    let g = build(raw)
    let r = coverOf(g)
    var seen = newSeq[int](g.vertexCount)
    var ok = r.cover.len <= 2 * r.matching.len
    for e in r.matching:
      ok = ok and g.hasArc(e.source, e.target)
      inc seen[e.source]
      if e.target != e.source:
        inc seen[e.target]
    for count in seen:
      ok = ok and count <= 1          # no vertex is in two matched edges
    ok)
  checkpoint describe(outcome)
  check outcome.passed

# SPEC: APPROX-VC-03
test "APPROX-VC-03 Given any small graph, when covering, then the cover is at most twice the exact minimum":
  let outcome = check(raws(), proc(raw: Raw): bool {.raises: [CatchableError].} =
    let g = build(raw)
    let found = vertexCover2Approx(g).value.len
    let best = optimum(g)
    found >= best and found <= 2 * best)
  checkpoint describe(outcome)
  check outcome.passed

# SPEC: APPROX-VC-08
test "APPROX-VC-08 Given the same graph twice, when covering, then the cover and matching repeat":
  let outcome = check(raws(), proc(raw: Raw): bool {.raises: [CatchableError].} =
    let g = build(raw)
    let a = coverOf(g)
    let b = coverOf(build(raw))
    a.cover == b.cover and a.matching == b.matching)
  checkpoint describe(outcome)
  check outcome.passed

# SPEC: GRAPH-BELLMAN-01
test "GRAPH-BELLMAN-01 Given weights that may be negative and no negative cycle, when searched, then distances equal Floyd-Warshall's row":
  let outcome = check(pair(raws(-3, 9), intIn(0, 6)), proc(c: (Raw, int)): bool {.raises: [CatchableError].} =
    let (raw, s) = c
    let source = s mod raw[0]
    let g = build(raw, gkDirected)
    let all = floydWarshall(g)
    if not all.isOk: return true
    let b = bellmanFord(g, source)
    if not b.isOk: return false
    for v in 0 ..< g.vertexCount:
      if b.value.distance(v) != all.value.distance(source, v): return false
    true)
  checkpoint describe(outcome)
  check outcome.passed

# SPEC: GRAPH-BELLMAN-02
test "GRAPH-BELLMAN-02 Given any graph, when a negative cycle is reported, then the cycle is real and negative":
  let outcome = check(pair(raws(-6, 6), intIn(0, 6)), proc(c: (Raw, int)): bool {.raises: [CatchableError].} =
    let (raw, s) = c
    for kind in [gkDirected, gkUndirected]:
      let g = build(raw, kind)
      let b = bellmanFord(g, s mod raw[0])
      if b.isErr:
        let w = g.cycleWeight(b.error.cycle)
        if b.error.kind != bfNegativeCycle or b.error.cycle.len == 0 or w.isNone or w.get >= 0: return false
    true)
  checkpoint describe(outcome)
  check outcome.passed

# SPEC: GRAPH-BFS-01
test "GRAPH-BFS-01 Given any graph and source, when searched breadth first, then distances are the fewest edges":
  let outcome = check(pair(raws(1, 9), intIn(0, 6)), proc(c: (Raw, int)): bool {.raises: [CatchableError].} =
    let (raw, s) = c
    let source = s mod raw[0]
    for kind in [gkDirected, gkUndirected]:
      let g = build(raw, kind)
